        RAIDBOSS_Witch_young = "MORGANA",
        RAIDBOSS_Witch_young_Title = "Morgana",
        RANDOM_AREA_HEALTH_DEGENERATION = "Vous perdez de la vie en tombant dans l'arène",
        TRANSIENT_BLEEDING = "Embrasement collectif",
        Tenebris_greetings_1 = "Vous êtes arrivé aux confins de la réalité, voyageur. L'ultime frontière. Par delà ce lieu, n'existe que le néant... Un néant nébuleux d'où jaillissent les mondes... dont je forge la lumière et les ténèbres !",
        Tenebris_greetings_2 = "Ombre, le portail qui se trouve derrière lui est peut-être notre seule chance de salut. Les Immortels ont dit qu'ils détruiraient notre monde. Peut-être ont-ils l'intention d'utiliser le portail ?",
        Tenebris_greetings_3 = "Le portail vous précipitera dans des ténèbres tentaculaires... des ténèbres qui engendrent des mondes. Mais vous ne savez point créer. Vous n'êtes capable que de destruction. Le portail vous dévorera !",
        Tenebris_greetings_4 = "C'est un risque, mais nous n'avons pas le choix ! Nous devons empêcher les Immortels de se frayer un chemin jusqu'au portail... mais en agissant ainsi, nous risquons de déclencher une catastrophe.",
        Tenebris_loses = "Craignez-vous les ténèbres ? À présent, vous devrez leur faire face sans aide aucune ! Le monde sombre dans le néant et renaît de ses cendres... ad vitam æternam !",
        Tenebris_wins = "Vous êtes tout aussi imbéciles que bornés ! Vous autres, humains, ne connaissez que la force brute... mais l'univers ne fonctionne pas ainsi. Après toutes ces années, vous n'avez donc rien appris ?...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "Relevez-vous, pantin... et battez-vous ! Qu'importe que vous gagniez ou perdiez. Lorsque vous combattrez, vous servirez ma cause !",
        War_AfterWin = "Où est donc votre furie ? Comment se battre sans elle ? Affrontez-moi ! Que la danse des lames débute ! Je perçois la rage en votre for intérieur !",
        War_Greetings1 = "Quelle belle journée ! Une bataille approche, telle une tempête. La furie des légions gronde et nourrit la puissance que recèle mon sanctuaire !",
        War_Greetings2 = "La fureur fait rage en son sein. Elle se délecte de batailles sans fin, mais pourquoi ? Qu'espère-t-elle trouver au sommet de sa montagne de crânes ?",
        War_Greetings3 = "Le frisson de la bataille vous est-il inconnu ? Feu, passion et puissance impétueuse ! Régalez-moi lors d'un combat solo... ou périssez !",
        ZONE_RAID = "Monde Souterrain : Palier 1",
        ZONE_RAID1 = "Monde Souterrain : Palier 2",
        ZONE_RAID2 = "Monde Souterrain : Palier 3",
        ZONE_RAID3 = "Monde Souterrain : Palier 4",
        ZONE_RAID4 = "Monde Souterrain : Palier 5",
        ZONE_RAID5 = "Monde Souterrain : Palier 6",
        ZONE_RAID6 = "Monde Souterrain : Palier 7",
        ZONE_RAID7 = "Monde Souterrain : Palier 8",
        blackness_enter_blackness_1 = "Descendance. Un grand sacrifice. Une sphère. L'esprit. Boucherie. Je ressens. Tu vas verser du sang. Je vois la douleur. Je vois l'avenir. Je vais te montrer.",
        blackness_greeting_blackness_1 = "Qu'y a-t-il, Shadow ? Tu ne te sens pas bien ?",
        blackness_greeting_lazarus_2 = "Simon ? Quel enfoiré tu fais ! Pourquoi as-tu amené des gens ici ? Ça va flairer l'odeur de vos pensées ! Éloignez-vous d'ici avant que la Noirceur ne goûte à votre esprit !",
        blackness_greeting_may_1 = "Vous entendez ça ? Rien ! Le silence. Sans le chant des oiseaux, c'est comme si cet endroit était figé dans l'ambre. Est-ce qu'on fait la bonne chose ? J'ai un très mauvais pressentiment…",
        blackness_greeting_saimon_2 = "Ces gentils messieurs sont ton billet pour la liberté, mon cher. Le grand en noir est lié d'une manière ou d'une autre à l'Obélisque et aux Portes. Il t'aide, et tu l'aides.",
        blackness_greetingn_saimon_1 = "Rien d'étonnant à cela. Depuis qu'un fragment des anciennes Portes s'est écrasé ici, la vie dans cet endroit est une anomalie statistique. Gardez les yeux ouverts — nous devons trouver Lazarus.",
        blackness_lose_blackness_1 = "Tu restes ici. Éternellement. Un seul sang. Pour toujours. Je vais te lire. Je vais me nourrir.",
        blackness_win_sensei = "Vous nous avez menti, homme de science ! Qui avons-nous libéré ? À quoi avons-nous condamné ce monde ? Est-ce que vous réalisez ce que vous avez fait ?!",
        characterMay = "MAY",
        characterMiniEventPriestess = "La Prêtresse",
        characterSensei = "SENSEI",
        characterThief = "SOURNOIS",
        character_Blind = "HERMINE",
        descAdanti = "Adanti a accepté votre défi.{br}(Niv. {0})",
        descArchitect = "Architecte a accepté votre défi.{br}(Niv. {0})",
        descArkhos = "Arkhos a accepté votre défi.{br}(Niv. {0})",
        descBanshee = "Banshee a accepté votre défi.{br}(Niv. {0})",
        descBerstuuk = "Berstuuk a accepté votre défi.{br}(Niv. {0})",
        descBlackness = "Le Néant obscur a accepté votre défi.{br}(Niv. {0})",
        descCountess = "Comtesse a accepté votre défi.{br}(Niv. {0})",
        descDandy = "Dandy a accepté votre défi.{br}(Niv. {0})",
        descDrakaina = "Drakaina a accepté votre défi.{br}(Niv. {0})",
        descFaradeya = "Faradeya a accepté votre défi.{br}(Niv. {0})",
        descFatum = "Fatum a accepté votre défi.{br}(Niv. {0})",
        descFungus = "Fungus a accepté votre défi.{br}(Niv. {0})",
        descGatekeeper = "Gardien a accepté votre défi.{br}(Niv. {0})",
        descHauntedPrince = "Prince hanté a accepté votre défi.{br}(Niv. {0})",
        descHoaxen = "Mystifieur a accepté votre défi.{br}(Niv. {0})",
        descInvisible = "Invisible a accepté votre défi.{br}(Niv. {0})",
        descKarcer = "Karcer a accepté votre défi.{br}(Niv. {0})",
        descLamb = "L'Agneau a accepté votre défi.{br}(Niv. {0})",
        descMegalith = "Mégalith a accepté votre défi.{br}(Niv. {0})",
        descMorgana = "Morgana a accepté votre défi.{br}(Niv. {0})",
        descPowerMode = "<color=#CC0101>MODE PUISSANCE</color>{br}(Niv. {0})",
        descPuppeteer = "Le Marionnettiste a accepté votre défi.{br}(Niv. {0})",
        descRakshasa = "Rakshasa a accepté votre défi.{br}(Niv. {0})",
        descRavana = "Ravana a accepté votre défi.{br}(Niv. {0})",
