        RANDOM_AREA_HEALTH_DEGENERATION = "Du verlierst im markierten Bereich Energie",
        TRANSIENT_BLEEDING = "Brennen-Zustand weitergeben",
        Tenebris_greetings_1 = "Du stehst am Rande der Realität, Reisender. Dies ist die letzte Grenze. Hinter dieser Linie liegt die Leere – dort entstehen Welten. Und ich habe ihr Licht und ihre Dunkelheit geschmiedet!",
        Tenebris_greetings_2 = "Schatten, das Portal hinter ihm ist vielleicht unsere Chance auf Erlösung. Die Unsterblichen sagten, sie würden unsere Welt vernichten. Vielleicht wollen Sie dieses Portal benutzen?",
        Tenebris_greetings_3 = "Du wirst das Portal nicht überleben! Es ist terra incognito. In dieser Dunkelheit können Welten erschaffen werden. Aber du kannst nicht erschaffen, nur zerstören. Das Portal wird dich einfach verschlingen!",
        Tenebris_greetings_4 = "Es besteht ein Risiko, aber bleibt uns eine andere Wahl? Wenn wir das Portal betreten, können wir die Unsterblichen vielleicht aufhalten. Aber wir können damit auch eine unglaubliche Katastrophe beschwören.",
        Tenebris_loses = "Fürchtest du dich vor dem Unbekannten, das in der Dunkelheit lauert? Nun musst du dich ihm alleine stellen! Die Welt zerfällt zu Staub und wird wiedergeboren. Dem Kreislauf gemäß.",
        Tenebris_wins = "Sturer Idiot! Ihr Menschen löst Probleme immer nur mit roher Gewalt. Aber so funktioniert das Universum nicht. All die Jahre hast du nicht dazugelernt ...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "Erhebe dich, Marionette! Und kämpfe! Es ist egal, ob du gewinnst oder verlierst. Wenn du kämpfst, dienst du mir!",
        War_AfterWin = "Betrüger! Wo ist die Wut? Kann man ohne sie kämpfen? Kämpfe gegen mich! Vollführen wir einen weiteren Klingentanz! Ich weiß, in dir lebt der Krieg!",
        War_Greetings1 = "Ein toller Tag! Ich spüre die kommende Schlacht – wie ein Sturm. Donner. Die ungeahnte Wut marschierender Legionen. Ein Geschenk auf meinem Altar!",
        War_Greetings2 = "Wut und Blutdurst kochen in ihr. Sie erfreut sich am endlosen Kampf, aber wozu? Was wird sie auf ihrem Schädelberg finden?",
        War_Greetings3 = "Ist dir der Nervenkitzel der blutigen Schlacht so fremd? Feuer, Leidenschaft, Kraft! Beweise dein Können! Unterhalte mich im Einzelkampf oder stirb!",
        ZONE_RAID = "Unterwelt: Stufe 1",
        ZONE_RAID1 = "Unterwelt: Stufe 2",
        ZONE_RAID2 = "Unterwelt: Stufe 3",
        ZONE_RAID3 = "Unterwelt: Stufe 4",
        ZONE_RAID4 = "Unterwelt: Stufe 5",
        ZONE_RAID5 = "Unterwelt: Stufe 6",
        ZONE_RAID6 = "Unterwelt: Stufe 7",
        ZONE_RAID7 = "Unterwelt: Stufe 8",
        blackness_enter_blackness_1 = "Nachwuchs. Ein großes Opfer. Eine Sphäre. Der Verstand. Gemetzel. Ich fühle. Du wirst Blut vergießen. Ich sehe Schmerz. Ich sehe die Zukunft. Ich werde es dir zeigen.",
        blackness_greeting_blackness_1 = "Was ist los, Shadow? Ist dir nicht gut?",
        blackness_greeting_lazarus_2 = "Simon? Was bist du doch für ein Mistkerl! Warum hast du Leute hierhergebracht? Es wird den Geruch eurer Gedanken wahrnehmen! Verschwindet von hier, bevor die Schwärze euren Verstand schmeckt!",
        blackness_greeting_may_1 = "Hört ihr das? Nichts! Stille. Ohne Vogelgezwitscher ist es, als wäre dieser Ort in Bernstein eingefroren. Tun wir das Richtige? Ich habe ein sehr ungutes Gefühl...",
        blackness_greeting_saimon_2 = "Diese feinen Herren sind deine Eintrittskarte in die Freiheit, mein Lieber. Der Große in Schwarz ist irgendwie mit dem Obelisken und den Toren verbunden. Er hilft dir, und du hilfst ihm.",
        blackness_greetingn_saimon_1 = "Kein Wunder. Seit ein Fragment der uralten Tore hier abgestürzt ist, ist das Leben an diesem Ort eine statistische Anomalie. Haltet die Augen offen – wir müssen Lazarus finden.",
        blackness_lose_blackness_1 = "Du bleibst hier. Auf ewig. Ein Blut. Für immer. Ich werde dich lesen. Ich werde mich nähren.",
        blackness_win_sensei = "Du hast uns belogen, Mann der Wissenschaft! Wen haben wir befreit? Wozu haben wir diese Welt verdammt? Ist dir klar, was du getan hast?!",
        characterMay = "MAY",
        characterMiniEventPriestess = "Die Priesterin",
        characterSensei = "SENSEI",
        characterThief = "DIEB",
        character_Blind = "HERMELIN",
