        descMegalith = "Megalith nimmt deine Herausforderung an.{br}(St. {0})",
        descMorgana = "Morgana nimmt deine Herausforderung an.{br}(St. {0})",
        descPowerMode = "<color=#CC0101>POWER-MODUS</color>{br}(St. {0})",
        descPuppeteer = "Puppenspieler hat deine Herausforderung angenommen.{br}(St. {0})",
        descRakshasa = "Rakshasa hat deine Herausforderung angenommen.{br}(Stufe {0})",
        descRavana = "Ravana hat deine Herausforderung angenommen.{br}(St. {0})",
