        descShurale = "Shurale hat deine Herausforderung angenommen.{br}(Stufe {0})",
        descSonOfHeaven = "Sohn des Himmels hat deine Herausforderung angenommen.{br}(St. {0})",
        descSonOfTheSun = "Sohn der Sonne hat deine Herausforderung angenommen.{br}(St. {0})",
        descStalker = "Pirscher hat deine Herausforderung angenommen.{br}(St. {0})",
        descTenebris = "Tenebris hat deine Herausforderung angenommen.{br}(St. {0})",
        descVolcano = "Vulkan hat deine Herausforderung angenommen.{br}(St. {0})",
        descVortex = "Vortex hat deine Herausforderung angenommen.{br}(St. {0})",
        descWhisper = "Whisper hat deine Herausforderung angenommen.{br}(St. {0})",
        descWolfWind = "Windwolf hat deine Herausforderung angenommen.{br}(St. {0})",
        dlgAmericanEvent22Story_May_1 = "Sie ist völlig durchgefroren, Sensei! Wir können sie nicht hinauswerfen, wenn solche Winde vor der Tür wüten...",
        dlgAmericanEvent22Story_Puma_1 = "In Schwierigkeiten, alter Mann... Ich hätte nie gedacht, dass die Vergangenheit meines Volkes mich verfolgen würde, aber das tut sie. Also bin ich geflohen, um sie zu beschützen. Bitte hör mir zu!",
        dlgAmericanEvent22Story_Puma_2 = "Könnt ihr das auch hören? Als ich ein Kind war, erzählte mir ein Schamane von einem Geist, dessen Heulen die Wellen aufpeitschte und die Blätter abriss. Ich hätte nie gedacht, dass sich dieses alte Märchen als wahr erweisen würde!",
        dlgAmericanEvent22Story_Puma_3 = "Er kommt hierher, um uns mit seinem Schrei zu jagen, bis wir atemlos zusammenbrechen... Nur zum Spaß! Ich weiß nicht, wo ich mich sonst verstecken soll...",
        dlgAmericanEvent22Story_Sensei_1 = "Die Türen meines Hauses stehen jedem offen, der leidet. Aber es kommt unerwartet, eine Piratin in diesen Mauern zu sehen... Und wo ist deine Bande von Halsabschneidern, Puma?",
        dlgAmericanEvent22Story_Sensei_2 = "Die Mythen der Schamanen sind Allegorien. Die Menschen haben Segel erfunden, um den Wind zu zähmen, und seitdem hat er ihnen gute Dienste geleistet. Du bist nur ein dummes Märchen, und Shadow wird das beweisen!",
        dlgAmericanEvent22Story_Wind_Wolf_1 = "Ich bin der Wolfswind! Wer auch immer mir entgegenkommt, wird wie eine Kerze ausgeblasen! Und früher oder später werde ich eure Tür eintreten. Es ist nur eine Frage der Zeit!",
        dlgAmericanEvent22Story_Wind_Wolf_Lose = "Ich werde heuuuulen, bis die Blätter die Trümmer bedecken. Niemand wird je den Weg hierher finden! Kühn und töricht... Wie kannst du gegen die Elemente ankämpfen, Sterblicher?",
        dlgAmericanEvent22Story_Wind_Wolf_Win_1 = "Welche Schande... Du hast mir meine mächtige Stimme genommen! Aber dein Glaube, Mädchen, wird mich wieder zum Leben erwecken... Und ich werde nicht allein kommen! Denn wir sind viele!",
        dlgArkhosGreetings = "Blinde Fanatiker! Ihr erinnert euch an mich und füttert mich mit dem Glauben an den Vater. Eltern können streng sein und du wirst meine Bestrafung mit Freuden hinnehmen...",
        dlgArkhosLost = "Wem soll ich huldigen in der letzten Stunde? Oh Schöpfer, warum hast du mich verlassen? Du gabst mir die Macht, sie zu führen, doch habe ich dich enttäuscht...mal wieder.",
        dlgArkhosStory1 = "Ich kenne solche Leute. Sie umgeben sich mit Anhängern, die sie mit ihren Lügen füttern. Höre nicht auf seine feurigen Predigten, denn diese sind seine stärkste Waffe.",
        dlgArkhosStory2 = "Du hast Unrecht, alter Mann. Ich habe auch Eisen als Mittel für ungehorsame Kinder. Du wirst mich noch anflehen, der Familie beitreten zu dürfen...aber ich werde keine Barmherzigkeit kennen. ",
        dlgArkhosWin = "Du schwarzes Schaf bist unwürdig eines Platzes an meiner Seite. Hinfort! Gesandt wird ein Wort an den Schöpfer und wie ihr Menschen wieder versagt habt, auf dass er meine Kinder wieder füttere...",
        dlgBerstuuk_Announce = "Auf der Suche nach verbotenem Wissen hat ein begabter Wissenschaftler Wissenschaft und Magie in seinem Bestreben, ein Gott zu werden, miteinander verschmolzen. Und die Transformation ist unausweichlich! Nun ist der Wald sein albtraumhaftes Labor und Menschen sind seine Beute. Nur du kannst diese furchterregende Metamorphose aufhalten! Verbanne deine Angst und wage dich ins Herz des Dickichts auf der Suche nach dem falschen Götzen!",
        dlgBerstuuk_Loose_1 = "Als du an meine Tür kamst, hast du mir alles ohne Worte erzählt! Ich werde an diesem Wissen wie an einem dünnen Faden ziehen, bis nichts mehr übrig ist!",
        dlgBerstuuk_Story_1 = "Sly ist draußen und klopft an die Scheunentür... Ich habe nachts schon vieles im Wald gesehen, aber das ist etwas Neues! Was ist los mit ihm?",
        dlgBerstuuk_Story_10 = "Nicht genug. Die Wissenschaft ist unberechenbar – sieh mich nur an! Nach und nach habe ich den Wald akzeptiert, aber er weigerte sich beharrlich, mich zu akzeptieren. Bis jetzt.",
        dlgBerstuuk_Story_2 = "Für diejenigen, die Hilfe suchen, führt der Weg zur richtigen Tür. Aber Sly scheint sich verirrt zu haben... Du alter Schurke, pass auf deine Hände auf! Was ist passiert?",
        dlgBerstuuk_Story_3 = "Der Schurke hat nach Hilfe gesucht und sie gefunden. Lass uns in den Wald gehen, bevor er sich nimmt, was rechtmäßig ihnen gehört. Das Leben der Menschen!",
        dlgBerstuuk_Story_4 = "‚Menschen‘? Der arme Kerl steht unter Schock – er hat kein Gesicht! Was hat ihn so sehr erschreckt, dass ihn eine plötzliche Gewissenskrise heimgesucht hat?",
        dlgBerstuuk_Story_5 = "Kannst du die Vögel singen hören? Um diese Uhrzeit sollten sie bereits zwitschern, aber hier herrscht nichts als Totenstille... Was lauert sonst noch in diesem Wald?",
        dlgBerstuuk_Story_6 = "Totenstille. Totenstille. Die Menschen brauchen Hilfe. Du musst h-e-l-f-e-n. Hilf jetzt!",
        dlgBerstuuk_Story_7 = "Bei den Göttern! Menschen verwandeln sich normalerweise nicht in trockene Zweige und Moos, ganz gleich, wie viel Angst sie haben! Was ist das für ein Ding, und wo ist der echte Sly?!",
        dlgBerstuuk_Story_8 = "Er ist hier irgendwo in der Nähe. Slys kleiner Verstand war sehr hilfreich. Er hat mir von dir erzählt, Shadow – von deiner besonderen Kraft. Und da ist es mir klar geworden!",
        dlgBerstuuk_Story_9 = "Du bist also derjenige, von dem die Kreatur gesprochen hat? Der Wald wird kommen und es sich holen. Und wie viele dieser ‚rechtmäßigen‘ Leben hast du dir genommen, Wahnsinniger?",
        dlgBerstuuk_Win_1 = "Die Natur findet immer einen Weg! Unser Kampf hat mir mehr verraten, als du ahnst, Shadow. Der Wald wird sich erinnern. Er wird mich verschlingen, um wieder aufzuerstehen...",
        dlgFatumGreetings = "Dein Mut wird nur durch deine Torheit übertroffen.{br}Jedoch wusste ich von eurem Kommen, du ihr meine Bestimmung seid und ich eure. Ich werde euer Schicksal auf ewig umschreiben.",
        dlgFatumLost = "Ich kenne die Menschheit. Ihr lauft ständig im Kreis. Ich habe das schon mehrmals beobachtet. Selbstzerstörung und Vernichtung. Nichts kann dies ändern. Dies ist euer Schicksal.",
        dlgFatumStory1 = "Vorsichtig, mein Held. Die dir gewohnten universellen Gesetze verlieren hier unten ihre Wirkung...",
        dlgFatumStory2 = "Du hast recht! Halte den Jungen an der Leine. Ich weiss alles über euer Schicksal: Wer ihr seid und wohin ihr geht. Wollt ihr erfahren, wer am Ende stirbt?",
        dlgFatumWin = "Dein Schicksal ist besiegelt. Du hast bereits verloren in dem Moment als du einen Fuß über meine Türschwelle gesetzt hast. Hast du genug Mut in dir um deine Geschichte umzuschreiben?",
        dlgFungusGreetings = "Ihr habt das Land vergiftet und nun sterben meine Pilze. Sie werden euren Verstand absorbieren und wir werden alle eins, Menschen. Dies wird das Ende eurer Geschichte sein!",
        dlgFungusLost = "Meine Brüder haben wohl zu viel Gott gespielt. Der Glaube macht sie schwach. Doch Zerstörung ist in der Natur der Menschen, die Welt ist besser dran ohne euch.",
        dlgFungusWin = "Verschwindet! Und geniesst die letzten Minuten eures Lebens!",
        dlgHW21LosePuppeteer_1 = "Ich würde dir nicht einmal eine stumme Rolle anvertrauen, Shadow. Die Bühne ist nicht der Ort, an den du gehörst – entehre mein Handwerk nicht!",
        dlgHW21StoryArkhos_1 = "Die Pest kommt in eure Stadt, Sterbliche! Verbeugt euch vor der Macht eures Gottes! Und erfreut eure Augen am Glanz des Goldes, oder sonst...",
        dlgHW21StoryPuppeteer_1 = "Was wisst ihr schon von Kunst! Ihr habt mein größtes Unterfangen ruiniert! Wie dem auch sei... der dritte Akt steht an. Und darin haucht der Held sein Leben aus!",
        dlgHW21StorySensei_1 = "Seit wann kommen die Götter der Unterwelt hier herauf, um von einfachen Leuten Geld zu erpressen? Wirf deine Maske ab, Betrüger, bevor wir zu den Waffen greifen!",
        dlgHW21StorySensei_2 = "Theater sollte inspirieren, nicht entsetzen. Und du hast die wahre Essenz der Kunst verdreht. Wir werden dich aufhalten, bevor deine ‚Schauspieler‘ zu Schaden kommen.",
        dlgHW21StoryThief_1 = "Wartet! Ich bin es... Sly! Schlagt mich nicht! Er hatte versprochen, dass mich jeder fürchten würde... Und dass mich niemand erkennen würde. Wie habe ich mich verraten?",
        dlgHW21StoryThief_2 = "Der Besitzer des Wandertheaters – der Puppenspieler. Er sagte, es würde seine beste Vorstellung werden. Götter unter den Menschen! Das hat mir nichts bedeutet. Aber das Geld hingegen...",
        dlgHW21WinPuppeteer_1 = "Das ist ein Fiasko! Du hast meine wunderbare Handlung ruiniert und meine Masken zerbrochen! Wie soll ich jetzt ein Stück ohne Requisiten inszenieren...",
        dlgHW22EnterArchitect = "All diese eure Fantasy-Erzählung hat mich erschöpft... Jetzt werden wir nach meinen Regeln spielen. Und es ist in deinem Interesse, mich zu überraschen, Shadow...",
        dlgHW22LooseArchitect_1 = "Das war zu erwarten. Ich kenne alle deine Bewegungen, Shadow. Schließlich war ich es, der dich erfunden hat. Vielleicht hatte ich damals nicht meinen besten Tag... Aber jetzt wird dir dein neues Leben gefallen.",
        dlgHW22StoryArchitect_1 = "Das nennt man ein ‚Klischee‘, Puppenspieler. Wofür werden Dramatiker bezahlt? Für die Anzahl der Symbole? Die Figur des plappernden, verrückten Genies ist abgedroschen, genau wie die Figur des Helden...",
        dlgHW22StoryArchitect_2 = "Das ist es. Wir werden eure Welt von Grund auf neu schreiben! Zeitgemäß, kreativ, relevant! Worauf stehen die Teenager heutzutage? Warum sagst du nichts, Shadow? Oh, ja...",
        dlgHW22StoryPuppeteer_1 = "Es klopft – ein unerwartetes Klopfen an deiner Tür! Ist das ein Reisender, der zu Besuch kommt, oder etwas mehr? Faszinierend, nicht wahr?",
        dlgHW22StoryPuppeteer_2 = "Ich wusste, dass du das sagen würdest, alter Mann. Was kann man von erfundenen Charakteren auch anderes erwarten? Papier ist geduldig... Aber das Publikum wird es nie sein!",
        dlgHW22StoryPuppeteer_3 = "Ich bin nur ein Sklave der Bühne, mehr nicht. Und mein neues Meisterwerk wird von einer Begegnung mit dem Schöpfer erzählen – von den Qualen der Vorherbestimmung und des freien Willens...",
        dlgHW22StorySensei_1 = "Was auch immer du dir ausgedacht hast, Puppenspieler, wir werden deine Spiele nicht länger mitspielen. Kunst mag Schmerz verursachen, aber nicht auf die Art und Weise, wie du sie praktizierst.",
        dlgHW22StorySensei_2 = "Du hast zu viel geschauspielert und kannst die Realität nicht mehr von deinen Fantasien unterscheiden, Künstler... Du bist verrückt.",
        dlgHW22StorySensei_3 = "Deine Worte sind merkwürdig und besorgniserregend, Fremder... Ich weiß nicht, welcher Wahnsinn in deinem Kopf vor sich geht, aber Shadow wird ihn aus dir herausprügeln.",
        dlgHW22WinArchitect_1 = "Vielleicht gehört die Schöpfung nicht mehr ihrem Schöpfer und hat ein Eigenleben entwickelt... Du hast mich überrascht. Ich möchte sehen, wohin die Geschichte als Nächstes führt.",
        dlgHoaxenGreetings = "Dein ganzes Leben ist lediglich eine Illusion. Und wir sind die Schöpfer. Wir rauben euch den Verstand während andere es mit roher Gewalt versuchen. Feuer, Wasser, Krankheiten - ha!",
        dlgHoaxenLost = "Wo bist du, Bruder? Ich kann deine Stimme nicht mehr hören! Wahrlich, einsam eingesperrt zu sein ist schlimmer als jegliches Feuer oder Schwert...Verzieht euch, Dümmlinge. Der Vater wartet.",
        dlgHoaxenStory1 = "\"Wir?\" Shadow, ich glaube unser Freund hier hat einen Vogel. Entschuldige, mit welcher deiner Persönlichkeiten sprechen wir gerade? Vielleicht könnte dein \"Bruder\" ein wenig vernünftiger sein?",
        dlgHoaxenStory2 = "Du lachst über uns, Menschlicher? Mein Bruder rät mir eure Seelen in die ewigen Abgründe der Verdammnis zu schicken...Dann wird sich eure Welt ergeben ohne auch nur einen Tropfen Blut zu vergiessen.",
        dlgHoaxenWin = "Ich hätte dich getötet, doch meine Barmherzigkeit kennt keine Grenzen. Doch mein Bruder hat weniger Geduld. Es steht dir frei zu gehen, stolpere jedoch nicht über deine Füsse auf dem Weg nach draussen.",
        dlgHunter_enter_hunter_1 = "Du! Hey, duuuu! Bist du gekommen, um zu beenden, was du aaaangefangen hast, hm? Du? Es steckt eine Kraft in dir. Sie ssspriiicht zu mir. Ruhe! Oder ich weeeerde dich dazu zwingen!",
        dlgHunter_greeting_may_1 = "Seht mal! Da ist etwas in dem Kristall... Soll das so sein?",
        dlgHunter_greeting_saimon_1 = "Wie seltsam... Ich hatte erwartet, dass Lazarus den Obelisken zu Staub zermahlt. Ich fürchtete das Gemetzel, aber es scheint, als wären nur du und ich übrig geblieben. Ich bin fasziniert.",
        dlgHunter_greeting_saimon_2 = "Die Konzentrationshalle. Siehst du den Kristall in der Mitte? So sammelt der Obelisk Schattenenergie an – das Herz der Finsternis, sozusagen.",
        dlgHunter_greeting_sensei_1 = "Stille ist ein schlechtes Omen, mein rationaler Freund. Sie kann lauter sprechen als die ohrenbetäubendsten Worte. Hmm... Wo sind wir? Was ist das für ein bizarrer Ort?",
        dlgHunter_greeting_sensei_2 = "Das bezweifle ich, meine Liebe... Dieser Ort sieht anders aus als bei meinem letzten Besuch. Ich beginne zu glauben, dass der alte Mann recht hatte...",
        dlgHunter_loose_hunter_1 = "Leg diiiich hin. Ich werde dich für iiiimmmmer hier laaaassen. Richte keeeinen weiteren Schaden mehr an.",
        dlgHunter_win_hunter_1 = "Halt, Shadow-Mensch! Lass es sich nicht auuuusssbreeeiten! Du wiiiirst wie eeeeeeer sein. Du wiiiirst getäääääuscht werden! Aber du hast noch eine Chaaaaannnnce.",
        dlgIE21AnnounceAssistant_1 = "Wer in aller Welt ist das? Was machst du in unserer Welt, und warum sollten wir dir überhaupt zuhören?",
        dlgIE21AnnounceAssistant_2 = "Ha! Ich weiß nicht, wo du herkommst, aber du wirst nicht lange hier bleiben!",
        dlgIE21AnnounceAssistant_3 = "Hey Shadow, dieser Schläger ist zu weit gegangen! Lass uns ihm ein paar Manieren beibringen!",
        dlgIE21AnnounceBoss_1 = "Ihr erbärmlichen Sterblichen! Verbeugt euch vor meinem Willen und meiner Herrlichkeit, oder ich werde euch in die Knie zwingen!",
        dlgIE21AnnounceBoss_2 = "Wie wagst du es, so mit mir zu sprechen – ich bin Ravana, der Eroberer aller drei Welten!",
        dlgIE21AnnounceBoss_3 = "Das ist eure letzte Chance, niederzuknien. Weigert euch, und ich nehme mir euren Kopf!",
        dlgIE21AnnounceSensei_1 = "Shadow, ich spüre, wie sich eine mysteriöse Bedrohung nähert. Etwas Böses hat sich wieder einmal den Weg in unsere Welt gebahnt.",
        dlgIE21Boss_After_Loose = "Wenn alle Menschen dieser Welt so schwach sind, dann ist ihre Eroberung nur eine Frage der Zeit!",
        dlgIE21Boss_After_Win = "NARREN! Ich ziehe mich für den Moment zurück, aber ihr werdet mich nicht so leicht besiegen. Ich werde wiederkommen!",
        dlgIndia22Story_May_1 = "Und so habt ihr angefangen zu hungern... Was konnte dieser Dämon bei eurem freudigen Fest gewollt haben? Wie konnten einfache Bauern ein solches Raubtier anlocken?",
        dlgIndia22Story_Rakshasa_1 = "Du hast einen interessanten Geruch, Mensch. Zweifellos würdest du genauso gut schmecken! Hörst du meinen Magen knurren? Ein feines Stück Fleisch zu meinem Reis wäre mir sehr willkommen!",
        dlgIndia22Story_Rakshasa_Lose = "Zum Glück für dich hat mich unser Kampf erschöpft. Außerdem ist mein Hunger gestillt... fürs Erste. Ich werde mir neuen Appetit holen und wieder auf die Jagd gehen!",
        dlgIndia22Story_Sensei_1 = "Erzähle mir von ihm, Reisender. An deiner Kleidung sehe ich, dass du weit gereist bist. Welche Not plagt deine Heimat?",
        dlgIndia22Story_Sensei_2 = "Zügle deinen Appetit, Dämon! Es wird keine Einladung zum Fest des Lebens für jemanden geben, der das Leben selbst stiehlt!",
        dlgIndia22Story_Sensei_Win = "Es ist keine Magie, die einen Garten zum Blühen bringt – es ist harte Arbeit. Und das wirst du selbst beweisen: Hilf deinen Nachbarn, ihre Farm wieder aufzubauen, oder sonst...",
        dlgIndia22Story_Sitaram_1 = "Ich habe deine Lebensgeschichte gehört. Mögen die Götter dich nach deinen Verdiensten belohnen! Ich überbringe schlechte Nachrichten: Ein böser Geist ist in meinem Land erschienen...",
        dlgIndia22Story_Sitaram_2 = "Die Bösartigkeit dieses Dämons wird nur von seinem Hunger übertroffen! Wir bereiteten uns darauf vor, Bohag Bihu zu feiern, als plötzlich diese... Kreatur auftauchte und all unsere Setzlinge verschlang!",
        dlgIndia22Story_Sitaram_3 = "Agni ist mein Zeuge, meine Dame, ich frage mich dasselbe! Jetzt warten wir in Angst auf den Sonnenuntergang... Kommt mit mir, ich flehe euch an!",
        dlgIndia24_Enter_Puppet_1 = "Hast du den nötigen Geist, um das Schicksal zu lenken? Entscheide über meines, als demütiger Diener der Künste, der ich bin. Nur im Kampf versteht man wirklich, was Sache ist. Sei mutig, Shadow – greif an!",
        dlgIndia24_Story_Dandy_1 = "Macht auf, oder ich breche diese verdammte Tür ein! Ich weiß, dass ihr zu Hause seid – ich kann euch hören! Ich werde diese Hütte in Brand stecken, wenn ihr mir keinen Unterschlupf gewährt!",
        dlgIndia24_Story_Loose_Nrityu_1 = "Oh, wie heftig Sterbliche doch am Leben klammern. Nicht ich habe mir diese Arbeit ausgesucht, und ich werde keine giftigen Tränen darüber vergießen... Warum habt ihr mir das angetan?",
        dlgIndia24_Story_Loose_Puppet_2 = "Ihr Herz ist erfüllt von Liebe. Die Götter erschaffen uns rein, aber wir wählen unseren eigenen Weg. Nrityu beginnt das zu verstehen, während sie der Geschichte des Mädchens lauscht.",
        dlgIndia24_Story_Loose_Puppet_3 = "Shadow, deiner Vorstellung fehlt es an Leidenschaft und Hingabe. Ich werde dir noch eine Chance geben. Spiel es nicht – lebe es!",
        dlgIndia24_Story_Puppet_1 = "Klopf, klopf! Hey, alte Freunde! Die Stimme des Schicksals ist über uns gekommen – und sie ist auf dem Weg! Ihr roter Saum glimmt wie das Leben selbst in der Abenddämmerung!",
        dlgIndia24_Story_Puppet_2 = "Ist sie wegen deiner Seele gekommen? Sieh hier eine Geschichte, so alt wie die Welt selbst – die Legende von Nrityu, deren Schicksal es war, Leben zu nehmen.",
        dlgIndia24_Story_Puppet_3 = "Die Geister plappern alle durcheinander. Man kann ihnen nicht trauen. Und außerdem ist es nicht ihre Geschichte, die sie erzählen können. Ich werde euch die Wahrheit durch ihre Augen zeigen. Shadow, du bist der Einzige, der es verstehen kann.",
        dlgIndia24_Story_Sensei_1 = "Diese Stimme... Es scheint, unser alter Widersacher heckt schon wieder etwas aus. Wer wird dieses Mal das Opfer sein? Ich sehe einen Mann, der auf die Pagode zurennt...",
        dlgIndia24_Story_Sensei_2 = "Deine Kleidung ist voller Schmutz und Ruß, Fremder. Und dein Tonfall beunruhigt mich. Erkläre, wer du bist und was du an unserer Türschwelle zu suchen hast!",
        dlgIndia24_Story_Win_Faradeya_1 = "Zurück! Ich wollte das nicht! Meine Familie hatte Angst vor mir und ich dachte, das sei meine Chance... Dandy versprach, mich mitzunehmen, wenn ich nur helfen würde...",
        dlgIndia24_Story_Win_Nrityu_1 = "Da! Du fällst in einen ewigen Schlaf, obwohl du ihn nicht verdienst. Aber es steht mir nicht zu, über dich zu urteilen – das ist die Berufung eines anderen. Ich bin nur die Begleitung.",
        dlgIndia24_Story_Win_Puppet_4 = "Genau wie du, Shadow. Ich möchte, dass du Nrityus Weg folgst. Sie hat eine Ewigkeit gebraucht, um ihren Platz zu verstehen.",
        dlgIndia24_Story_Win_Puppet_6 = "Die Show geht weiter! Du, Shadow, wirst der Star sein, und meine Schauspieler werden deine Nebendarsteller sein. Die Geschichte von Nrityu wird unsere größte Produktion!",
        dlgIndia24_Story_Win_Sensei_1 = "Diese Geschichte geht tief – selbst für dich. Ich bin überrascht! Aber was ist die Moral von der Geschicht’? Warum zeigst du uns das?",
        dlgMegalithGreetings = "Diese Mine ist ein heiliger Ort. Warum bist du hier? Verschwinde und triff auf dein Schicksal mit Ehre. Das Letzte was du hören wirst, wird die bebende Erde unter deinen Füßen sein.",
        dlgMegalithLost = "Verdammt! Muss ich wieder Tausend Jahre warten?! Ich habe Kontinente bewegt! ICH sollte die Erde reinigen!",
        dlgMegalithWin = "Ich mag Menschen. Unter Unsterblichen ist das eine Seltenheit. Es gab Zeiten, da half ich euresgleichen. Darum lauft, so lange ich euch die Möglichkeit gebe, euch von euren Nächsten zu verabschieden.",
        dlgRaidIntro1 = "Willst du deinen Fehler wiedergutmachen? Du öffnetest die Tore, doch nur die Unsterblichen können die Schattenplage eliminieren. Du bist schwach, und somit keiner von uns.",
        dlgRaidIntro2 = "Du sollst sterben, genau wie der Rest. Magma fliesst durch meine Venen, und es wird das gesamte Land bedecken, es reinigen, für neues Leben.",
        dlgRaidStory1 = "Was ist das für ein Keller und was tun wir hier?",
        dlgRaidStory2 = "Hier beginnt der Einflussbereich der Unsterblichen. Ihr Schlaf währte für Tausende von Jahren, doch die Tore der Schatten haben die Welt in Gefahr gebracht. Sie sind nun erwacht.",
        dlgRaidStory3 = "Super - das heisst sie helfen uns, mit den Toren schnell und einfach fertig zu werden!",
        dlgRaidStory4 = "Oh, nein. Sie werden die Tore zerstören, aber sie werden ebenso die Menschheit vernichten. Für sie ist es nur ein weiterer Zyklus von Zerstörung und Aufbau.",
        dlgShurale_Announce = "Von gierigen Banditen erweckt, rächt sich der Waldgeist nun an den Unschuldigen. Die Kreatur sucht nach der gestohlenen Schatulle der Erinnerungen – dem Gefäß ihrer uralten Magie. Nur diejenigen, in deren Herzen wahrer Kummer herrscht, können den Zorn der Kreatur besänftigen. Der Preis wird jedoch hoch sein...",
        dlgStoryBtnFight = "KÄMPFT",
        dlgStoryBtnMore = "MEHR",
        dlgVolcanoGreetings = "Von all den Unsterblichen bin ich als erster erwacht. Viele Kämpfer werden durch meine Hand sterben - ich werde meine Mission beenden.",
        dlgVolcanoLost = "Genug! Ich gebe auf. Aber wisse: Ihr habt meinen Bruder gegen auch aufgebracht. Lasst euch nicht von seinem Äußeren ablenken - er ist schnell und tödlich!",
        dlgVolcanoStory1 = "Ich habe einige zerstörte Häuser und eine riesige Statue gesehen. Wohnen hier Menschen?",
        dlgVolcanoStory2 = "Nur Fanatiker. Sie beten die Unsterblichen an um verschont zu werden. Sie sind blind in ihrem Glauben. Wenn wir scheitern, werden sie bald die Wahrheit spüren.",
        dlgVolcanoWin = "Ich habe meinen Waffenbrüdern schon immer gesagt, dass es meine Pflicht ist, über das Schicksal dieser Welt zu entscheiden. Seht, Ungläubige, wie mein Feuer das ganze Land bedeckt!",
        dlgVortexGreetings = "Dunkle Wasser werden die Erde und die Tore der Schatten verschlingen! Ihr Geheimnis wird in der Versenkung verschwinden. Und an der Oberfläche wird niemand übrig bleiben, um davon zu erzählen!",
        dlgVortexLost = "Zum ersten mal seit einen Jahrtausend gewinnt ein Mensch. Dein Überlebenswille ist stark! Aber was auch immer du tust, das Ende wird dasselbe sein: Du wirst sterben.",
        dlgVortexWin = "Tausende Jahre habe ich eurer Vernichtung zugesehen. Darin verbirgt sich ein wenig Schönheit. Ich glaube, ich lasse dich am Leben. nur so zum Spass.",
        dlgWhisperGreetings = "Scheint so, als könne jemand es nicht abwarten, sein Schicksal zu entdecken. Gib mir deine Hand und blick in den Spiegel!",
        dlgWhisperLost = "Du bist noch am Leben? Dann bist du noch nicht in meiner Macht! Fatum soll dein Schicksal weissagen, und dann werde ich in meine Welt zurückkehren – nachdem ich dich gewarnt habe, vorsichtig mit Spiegeln umzugehen!",
        dlgWhisperWin = "Ich werde dich mitnehmen in das Reich der Asche, der Geister und der ewigen Nacht! Vertrau mir – schau mir in die Augen und sieh nicht weg.",
        dlg_American_25_Loose_1 = "Du weißt nicht, wen du beschützt, Shadow. Sie werden dir nicht danken. Sie werden hinter deinem Rücken nur spotten. Wilde... und ich soll das Monster sein?",
        dlg_American_25_Story_1 = "May ist weg. Von etwas mitgenommen, das kaum menschlich ist. Doch es gab keine Schreie, keine Anzeichen eines Kampfes... als wäre sie aus freien Stücken gegangen.",
        dlg_American_25_Story_2 = "Wir sind damit nicht allein. Andere wie May – jung, stark – sind ebenfalls verschwunden. Sie hat es kommen spüren... und sich die Taschen mit Schießpulver gefüllt.",
        dlg_American_25_Story_3 = "Ihre Spur ist deutlich. Wir müssen sie finden, bevor der Regen kommt, sonst ist sie für immer verloren. Komm, Shadow!",
        dlg_American_25_Story_4 = "Ich habe dich gerochen, als du diesen verfluchten Boden betreten hast. Warum bist du hier? Um auf meiner Trauer herumzutrampeln? Du hast keine Ehre – genau wie sie.",
        dlg_American_25_Story_5 = "Ich wusste, dass du auftauchen würdest, Schamane. Gib die Kinder ihren Familien zurück und unsere Freundin uns. Dann geh und verrotte auf deinem Ascheberg.",
        dlg_American_25_Story_6 = "Asche zu Asche. Und zu Asche wirst du zurückkehren, Sterblicher...",
        dlg_American_25_Win_1 = "Warte! Ich bin freiwillig mit ihm gegangen. Seine Gestalt ist bestialisch, ja – aber sein Herz ist menschlich. Und es leidet... Sie haben sein Kind gestohlen!",
        dlg_CHN_NY25_Announce = "Tauche in die Geschichte eines Helden aus vergangenen Zeiten ein – entwirre Wahrheit und Fabel und hilf dabei, eine neue Legende zu schmieden! Stelle dich einem mysteriösen Kult, der den Namen eines großen Helden als Deckmantel für seine Gräueltaten nutzt! Kehre an den Ort zurück, an dem alles begann, und hilf einem flüchtigen Schurken, sein wahres Heldentum zu entdecken!",
        dlg_CHN_NY25_Loose_1 = "Nein, wir müssen weiterkämpfen! Niemand würde glauben, dass ein einfacher Bauer einen finsteren Kult so leicht besiegen kann. Du musst alles geben!",
        dlg_CHN_NY25_Story_1 = "Der Sonnenkult hat die Tradition, einmal im Jahr den Geburtsort seines großen Helden zu besuchen. Aber jedes Mal endet es in einer Katastrophe...",
        dlg_CHN_NY25_Story_2 = "Er wurde als Mensch geboren? Wie merkwürdig. Mir scheint, dass diese Leute keine Geschenke für das Dorf mitbringen...",
        dlg_CHN_NY25_Story_3 = "Sie lassen nichts unberührt! Sie stehlen den Dorfbewohnern das Vieh, verwüsten im Rausch die Felder, zerschlagen Fenster und fangen Schlägereien an!",
        dlg_CHN_NY25_Story_4 = "Aber warum wehren sich die Dorfbewohner nicht? Das ist ihr Land und ihre Legende!",
        dlg_CHN_NY25_Story_5 = "Sie sind gebrochen. Der Held, der ihnen Hoffnung gab, ist fort, und die Kultisten begehen Böses in seinem Namen. Wir müssen ihnen wieder Hoffnung geben!",
        dlg_CHN_NY25_Story_6 = "Sag, du bist gekommen, um zu überprüfen, ob alles für den ‚Feiertag‘ bereit ist. Und wir werden kämpfen! Die Stadtbewohner werden sehen, dass man sich dem Kult entgegenstellen kann!",
        dlg_CHN_NY25_Story_7 = "Also gut, wie du willst... Lass mich in meine Rolle schlüpfen. ‚He, Junge, wie kannst du es wagen, das Gewand unseres Helden zu tragen! Verschwinde – wir haben ein Festmahl vorzubereiten!‘",
        dlg_CHN_NY25_Story_8 = "Ich bin vielleicht kein legendärer Held, aber sein Geist lebt in diesem Land! Er wird mich in meiner dunkelsten Stunde führen und mir Mut verleihen! Angriff!",
        dlg_CHN_NY25_Win_1 = "Ich hätte von einem einfachen Menschen nicht so eine Geschwindigkeit erwartet... Du hast unseren Champion fast besiegt! Wir müssen ein Exempel an dir statuieren, damit andere nicht auf dumme Gedanken kommen...",
        dlg_NY25_Loose_1 = "Deine Erinnerungen sind lebendig, und der Kummer spricht lauter als die Vernunft. Du wirst hier bei mir bleiben. Ruhe dich ein wenig aus – der Schlaf wird bald kommen.",
        dlg_NY25_Story_1 = "Willkommen! Diese Hütte gehörte einst meiner Familie. So viele Erinnerungen... Bleibt so lange, wie ihr wollt. Hier gibt es alles, was ihr zum Ausruhen braucht.",
        dlg_NY25_Story_2 = "Aber du hast uns schon so oft in Gefahr gebracht, und jetzt bietest du uns einen Aufenthalt in deinem Elternhaus an? Ist das eine Art Trick?",
        dlg_NY25_Story_3 = "Das ist nur die Stimme des Gewissens! Mir ist klar geworden, dass ich die Freundlichkeit anderer zu lange ausgenutzt habe. Aber jetzt möchte ich Gutes tun.",
        dlg_NY25_Story_4 = "Wir sind nicht allein... Vor der Hütte versammeln sich Leute. Was wollen sie zu dieser späten Stunde? Sie rufen uns zu, wir sollen herauskommen.",
        dlg_NY25_Story_5 = "Tut das nicht! Die Phantome werden euch vernichten! Sie sind nur Geister schmerzhafter Erinnerungen. Der Waldgeist ist wegen seiner Truhe gekommen! Lasst sie uns zurückholen!",
        dlg_NY25_Story_6 = "Eine Truhe? Darum sind also Menschen in den Wäldern verschwunden! Warum hast du uns verraten, Sly? Wir hätten dir bei dieser edlen Mission sowieso geholfen!",
        dlg_NY25_Story_7 = "Ihr versteht das nicht. Wenn ich ihre Stimme höre, verliere ich die Kontrolle – und dann bin ich auch weg. Solange ich ein Stück von ihr bei mir trage.",
        dlg_NY25_Story_8 = "Mach die Tür auf, ich friere hier draußen, Papa. Das Haus ist kalt und ich bin nicht drinnen. Ich zeige dir einen Ort, an dem wir wieder zusammen sein können.",
        dlg_NY25_Story_9 = "Halt! Geh nicht in den Wald – du wirst dich verirren! Ich weiß nicht, wessen Stimme du hörst, aber sie ist ganz sicher nicht menschlich!",
        dlg_NY25_Win_1 = "Wach auf, Sly! Gib dem Geist die Truhe zurück, solange er schwach ist. Lass ihn sehen, dass die Menschheit ihre eigene Gier überwinden kann.",
        saturn_enter_saturn_1 = "Ich werde dir deine Worte wieder in den Hals stopfen. Und deine Freunde werden zusehen. Der einzige Weg, mein Gefängnis zu verlassen, führt über das Schafott. Wer will zuerst gehen?",
        saturn_greeting_saimon_1 = "Unser Herrscher, der Patriarch, hat das Portal jahrelang studiert. Dann, eines Tages, zog er sich in sich selbst zurück. Später errichtete er den Obelisken, und er hat etwas mit unserer Welt gemacht...",
        saturn_greeting_saimon_2 = "Shadow ist dem Obelisken auf molekularer Ebene ähnlich. Es gibt jemanden, der uns helfen wird, das gegen den Patriarchen einzusetzen. Deshalb sind wir hier, in der Kammer von Saturn...",
        saturn_greeting_saimon_3 = "Tausendmal um Verzeihung, meine Dame. Dennoch müssen wir Lazarus befreien. Bitte führt uns zu seiner Zelle, und wir werden euch nicht weiter behelligen.",
        saturn_greeting_saturn_1 = "Wollt ihr weit weg, Kinder? Ihr seid aus freiem Willen in mein Gefängnis gekommen! Ich frage mich – ist das Mut oder Dummheit? Du, der Schlaksige – antworte mir!",
        saturn_greetingn_May_1 = "Aber was hat das mit uns zu tun?",
        saturn_lose_saturn_1 = "Das reicht für euch. Wenn Lazarus sich mit Ausschuss wie euch abgibt, besteht keine Gefahr für den Patriarchen. Verschwindet von hier, Gören! Ihr steht nicht auf meiner Liste.",
        saturn_win_saturn_1 = "Ihr werdet Lazarus nie finden. Dieser Schuft ist aus meinem Gefängnis ausgebrochen und in die Sümpfe geflohen. Wollt ihr auch zugrunde gehen? Dann los, hinterher!",
        summerfest25_story2_1 = "Sieh mal an... Du warst so versessen darauf, mich zu finden, da dachte ich, ich tue dir den Gefallen. Außerdem haben sowieso alle auf diesen Moment gewartet.",
        summerfest25_story2_2 = "‚Alle‘? Hör auf mit dem Theater. Wir wissen genau, wer du bist – und wie du andere benutzt, nur um dich an ihrem Elend zu ergötzen.",
        summerfest25_story2_3 = "Nur ein kleiner Gastauftritt und bumm – ich liege voll im Trend! Ehrlich gesagt, hätte ich nicht erwartet, dass ich so beliebt bin.",
        summerfest25_story2_4 = "Dein Witz wird dich nicht retten. Du wirst bezahlen – für meine Augen und für all das Böse, das du getan hast. Dein verdrehtes Spiel, Gott zu spielen, endet hier!",
        summerfest25_story2_5 = "Ernsthaft, Ermine? Solche Sprüche sind zusammen mit Klapphandys aus der Mode gekommen. Wir haben 2026 – versuch, mit der Zeit zu gehen.",
        summerfest25_story2_6 = "Was auch immer der Architekt plant... ihn umgibt eine Dunkelheit. Eine Kraft, die so bösartig ist, dass sie fast greifbar ist.",
        summerfest25_story2_7 = "Mit jedem Wort, das er spricht, ertappe ich mich dabei, dass ich Ermines Geschichte immer mehr glaube. Der Architekt ist gefährlich – und er muss aufgehalten werden.",
        summerfest25_story2_defeat_1 = "Oh nein – wie enttäuschend! Das Publikum hat mehr erwartet. Es scheint, als müsste ich beim nächsten Mal einfach die Einsätze erhöhen.",
        summerfest25_story2_win_1 = "Warum ist die Welt so grausam? Warum müssen wir leiden? Warum musste ich mich selbst blenden? Antworte mir, Architekt – warum tut das Leben so weh!?",
        tutorial_ascention_intro_title = "PUPPENSPIELER",
    },
    hin = {
        ActScreenRaid = "अंडरवर्ल्ड",
        BLACKNESS = "ब्लैकनेस",
        BLACKNESS_TITLE = "ब्लैकनेस",
        BODY_BERSTUUK = "बेरस्टुक का रूप",
        BOSS_BISON_21 = "अदंती",
        BOSS_BISON_Title = "अदंती",
        BOSS_LAMB = "द लैम्ब",
        BOSS_RAVANA = "रावण",
        BOSS_RAVANA_Title = "रावण",
        CharacterIndia24Nrityu = "नृत्य",
        DEMON_RAID = "गॉन्टलेट",
        DEMON_RAID_Title = "गॉन्टलेट",
        EARTHQUAKE = "समय-समय पर भूकंप।",
        EnterPortal_ActScreen = "पोर्टल",
        FRAGILITY = "दिखाए गए क्षेत्र में संवेदनशीलता बढ़ गई।",
        Gatekeeper_greetings_1 = "अजीब हवा? अजीब हवा! अजीईइब हवा!",
        Gatekeeper_greetings_2 = "खुश नहीं, खुश नहीं, खुश नहीं! हमने किया, हमने किया, हमने किया!",
        Gatekeeper_greetings_Assistant_1 = "शैडो! तुम आखिरकार जाग गए!",
        Gatekeeper_greetings_Assistant_2 = "यहाँ बहुत ठंड है! मैं पहले से ही अपनी उंगलियों को महसूस नहीं कर पा रही हूँ… हम कहाँ हैं? यहाँ की हवा बहुत अजीब लग रही है。",
        Gatekeeper_greetings_Assistant_3 = "लेकिन मुझे ऐसा क्यों लग रहा है कि यह हमारी बात समझता है?",
        Gatekeeper_greetings_Sensei = "पीछे हटो, मे! हम नहीं जानते कि इसे क्या चाहिए! अमरों की दुनिया मेरी सोच से कहीं अधिक हिल गई थी। हमने जो किया उसके बाद, वे खुश नहीं हैं कि हम यहाँ हैं।",
        Gatekeeper_greetings_Sensei_2 = "अब शांत हो जाओ—अचानक कोई हरकत मत करो। ऐसा लगता है कि यह जीव बहुत बुद्धिमान नहीं है।",
        Gatekeeper_greetings_Sensei_3 = "यह अभी ज़रूरी नहीं है। पोर्टल से गुजरना हमारी पसंद थी, और हमें इसके लिए जवाब देना होगा। यह लड़ना चाहता है—हमारे पास कोई विकल्प नहीं है, शैडो।",
        Gatekeeper_lost_Saimon = "मुझे पोर्टल से और ज़्यादा की उम्मीद थी… ऐसा लगता है कि यात्रा ने तुम्हारी ताकत चूस ली है, और तुम्हारे आणविक बंधन कमज़ोर हो गए हैं। दिलचस्प है—हमें कुछ और परीक्षण करने होंगे।",
        Gatekeeper_win_Saimon = "सदियों से, इस जर्जर पोर्टल ने हमें याद दिलाया है कि हमारी समझ से परे भी ताकतें मौजूद हैं। फिर तुम आए…",
        HARD_GROUND = "जमीन पर गिरने पर आपको क्षति पहुँचती है।",
        HEAD_BERSTUUK = "बेरस्टुक का मुखौटा",
        HEALTH_DROPS = "समय के साथ स्वास्थ्य घटता है।",
        HOT_GROUND = "गर्म जमीन।",
        HW20Arkhos1 = "मुझे यह देखने के लिए किसी दूरदृष्टि की आवश्यकता नहीं है कि विश्वास की आग कमज़ोर और अंधे दोनों को भस्म कर देगी। मैं काली मोमबत्तियां लाया हूँ, ताकि सभी इस सच्चाई को उतनी ही स्पष्टता से देख सकें जितना कि मैं देखता हूँ!",
        HW20Fatum1 = "दुनिया के बीच की सीमाएं पतली हो रही हैं—भविष्यवाणी के लिए यह सबसे बेहतरीन रात है! हवा में जादू गूंज रहा है, और मेरे हाथों में, भाग्य के धागे लिपटे हुए हैं!",
        HW20Fatum2 = "भविष्य बताना, मेरे लिए, एक खेल है—मैं नश्वरों के भाग्य के साथ जो चाहूँ कर सकता हूँ। लेकिन आप, मेरे दोस्तों, बिल्कुल अलग बात हैं। कृपया, बैठ जाइए!",
        HW20Fatum3 = "तुम अपनी नफरत से अंधे हो गए हो। चलो शुरू करते हैं। बोलो मत, बस सुनो। मुझे एक आकृति दिखाई दे रही है… रात जैसी काली… पंख और राख… मुझे हाथ से पकड़ रही है…",
        HW20Fatum4 = "तुम… तुम यहाँ कैसे आए? इस दुनिया का रास्ता तुम्हारे लिए सील कर दिया गया था!",
        HW20Megalith1 = "तुमने भविष्य बताने और एक छद्मवेशी (masquerade) पार्टी के बारे में बात की थी, इसलिए मैं एक जादुई दर्पण लाया हूँ। हज़ार सालों में पहली बार, मैं अपना अक्स देख सकता हूँ। यह मुखौटा मुझे बहुत प्राचीन दिखा रहा है!",
        HW20Whisper1 = "क्या तुम भविष्यवाणी का खेल खेल रही हो, छोटी बहन? नश्वरों की नियति का प्रभार ले रही हो? ऐसे खिलौने हमेशा से सिर्फ मेरे ही रहे हैं!",
        HW20Whisper2 = "सील तो था! लेकिन तुमने बुलाया, और इस अद्भुत दर्पण के ज़रिए, मैं आ गई। मैं इसे अपने साथ ले जा रही हूँ। ज़रूर आना, और कुछ सच्चे भविष्यवाणियां सुनना!",
        Hunger_AfterLoss = "चूंकि तुम ही चुने गए व्यक्ति हो, मैं तुम्हें मेरे साथ रहने और दावत उड़ाने का एक आखिरी मौका दूँगा। अन्यथा तुम्हारी हड्डियाँ भी धूल में अन्यों के साथ मिल जाएंगी।",
        Hunger_AfterWin = "निर्माता, आपने मेरे लिए आहार भेजा, लेकिन यह पर्याप्त नहीं है। मेरी भूख अनंत है, मुझे मुक्ति दें...",
        Hunger_Greetings1 = "तुम यहाँ पहुँचने के लिए काफी लंबा रास्ता तय करके आए हो। क्यों? उन कृतघ्न नश्वर लोगों को बचाने के लिए? उन्हें तुम्हारी कोई परवाह नहीं है! मैं तुम्हारे अकेलेपन, तुम्हारी भूख और तुम्हारे... डर को महसूस कर सकता हूँ।",
        Hunger_Greetings2 = "शैडो, धोखे में मत आना! वह केवल कमज़ोर दिखता है। तुम उसके दोस्त नहीं हो, तुम बस उसके शिकार हो। यदि तुम थोड़े भी करीब गए तो वह तुम्हें टुकड़ों में फाड़ देगा!",
        Hunger_Greetings3 = "क्या तुम मेरे भाइयों को देख सकते हो? वे प्यासे हैं, लेकिन उनकी प्यास एक अलग तरह की है। वे मनोरंजन के भूखे हैं। लेकिन उनकी भूख मेरी भूख के सामने कुछ भी नहीं है!",
        INVERTED_JOYSTICK = "उल्टा संचलन।",
        MERCENARY_RAID = "मर्सिनरी यूनिट",
        MERCENARY_RAID_Title = "मर्सिनरी यूनिट",
        MiniEventAnnounce = "प्राचीन काल से ही, एक पंथ पृथ्वी के गर्भ में निवास कर रहा है, जो पाताल लोक के देवताओं की गहरी नींद की रखवाली कर रहा है और उन्हें जागने से रोक रहा है। लेकिन इसकी कीमत एक क्रूर अनुष्ठान की लड़ाई है, जो खून की आखिरी बूंद तक लड़ी जाती है।",
        MiniEventHungerFight_Enter_1 = "यहाँ पृथ्वी के नीचे, सब कुछ अलग है। हम जीने के लिए लड़ते हैं, और भोजन ही जीवन है! अपने लोगों को—या मेरे लोगों को—इस महान आनंद से वंचित मत करो!",
        MiniEventHungerStory_1 = "लोग आत्माओं की सनक की परवाह तभी करते हैं जब उनके घरों पर मुसीबत आती है। उनकी फसलें मुरझा जाती हैं, उनके बच्चे भूखे रह जाते हैं… और अब उनका विश्वास कहाँ है?",
        MiniEventHungerStory_2 = "भूख का एक रूप होता है। इसकी निगलने की प्यास भयानक होती है। लेकिन वह कार्सर (Karcer) की भूमिका है, जबकि तुम्हारा और मेरा काम उसे उसकी सदियों पुरानी नींद से जागने से रोकना है।",
        MiniEventHunger_Loss_1 = "क्या तुम्हारी माँ ने तुम्हें अपनी प्लेट में कुछ भी न छोड़ना नहीं सिखाया था? यह दिखता है—तुम्हारी आँखों में भूख है! या… तुम्हारे साथ बात क्या है?",
        MiniEventHunger_Win_1 = "हाँ, तुम अच्छा प्रहार करते हो, शैडो… चलो तुम्हारी जीत का जश्न कुछ स्वादिष्ट खाने के साथ मनाते हैं! मेरी तरफ से दावत!",
        MiniEventStory_1 = "मैं देख रहा हूँ कि तुम, शैडो, मजबूत और दृढ़ आत्मा वाले हो। तुम्हारे कामों की किंवदंतियां दूर-दूर तक फैली हुई हैं। क्या तुम एक और का हिस्सा बनना चाहोगे?",
        MiniEventStory_2 = "पाताल लोक की आत्माएं मनमौजी हैं। हम उनके गुस्से को शांत करने के लिए एक अनुष्ठान करते हैं—अनुष्ठानिक लड़ाइयाँ! तुम्हारी भागीदारी हमारे लिए सम्मान की बात होगी।",
        MiniEventStory_EnterBattle = "क्या तुम ऐसे रहस्यमय तमाशे के लिए थोड़े बीमार नहीं हो? और तुमने सचमुच इसे चुना है? यह किंवदंतियों का आदमी है? ओह, आत्माएं तो क्रोधित हो जाएंगी…",
        MiniEventStory_Loss_1 = "हाँ, खैर… मैं यह मानना चाहता हूँ कि आत्माओं में भी हास्य की भावना होती है, और वे अपना क्रोध हम पर उतारने के बजाय, अखाड़े में हमारी इस बेतुकी लड़ाई पर केवल हंसेंगी…",
        MiniEventStory_Win_1 = "खैर… कोई भी इस अखाड़े में संयोग से नहीं आता। तुम सच में किंवदंतियों के आदमी हो, शैडो।",
        MiniEventVulkanFight_Enter_1 = "डायन तुम्हें बिना वजह डराती है। यह उससे कहीं अधिक सरल है: स्टील आग में ही मजबूत होता है! देवता केवल शक्ति को समझते हैं और कुछ नहीं। केवल शक्ति ही उन्हें उनकी नींद में वापस भेज सकती है! हमला करो!",
        MiniEventVulkanStory_1 = "पवित्र करने वाली अग्नि ही न्यायसंगत है—हमारे पूर्वज ऐसा कहते हैं। लेकिन वे नहीं जानते थे कि अमरों को मानवीय नैतिकता की कोई परवाह नहीं है। यह बस उनका स्वभाव है।",
        MiniEventVulkanStory_2 = "क्या तुम धरती के नीचे से उठती गर्मी को महसूस कर रहे हो? तुम्हें एक बात जान लेनी चाहिए: आग किसी को नहीं बख्शती, चाहे वह दोस्त हो या अजनबी। और हम सीधे उसके रास्ते में खड़े हैं。",
        MiniEventVulkan_Loss_1 = "तुम्हें फिर से खड़ा होना होगा, शैडो! क्या तुम ज़मीन को कांपते हुए महसूस नहीं कर सकते?! देवता हमारी इस धूल-मिट्टी की लड़ाई से परेशान हो रहे हैं…",
        MiniEventVulkan_Win_1 = "यहाँ नर्क की आग जैसी गर्मी है… अग्नि आत्मा अपनी तिजोरी में संतुष्टि से गुर्रा रही है! वास्तव में एक बेहतरीन लड़ाई, शैडो! हमने एक और दिन कमा लिया है!",
