        DEMON_RAID_Title = "Próbatétel",
        EARTHQUAKE = "Időszakos földrengések.",
        EnterPortal_ActScreen = "Portál",
        FRAGILITY = "Megnövekedett sebezhetőség a jelzett területen belül.",
        Gatekeeper_greetings_1 = "Furcsa levegő? Furcsa levegő! Furrrcsa levegő!",
        Gatekeeper_greetings_2 = "Nem örülnek, nem örülnek, nem örülnek! Amit tettünk, amit tettünk, amit tettünk!",
        Gatekeeper_greetings_Assistant_1 = "Árnyék! Végre felébredtél!",
        Gatekeeper_greetings_Assistant_2 = "Milyen hideg van itt! Már nem érzem az ujjaimat… Hol vagyunk? A levegő olyan furcsa.",
        Gatekeeper_greetings_Assistant_3 = "De miért érzem úgy, mintha megértene minket?",
        Gatekeeper_greetings_Sensei = "Hátra, May! Nem tudjuk, mit akar! A Halhatatlanok világát jobban megrázta, mint gondoltam. Amit tettünk, azután nem örülnek neki, hogy itt vagyunk.",
        Gatekeeper_greetings_Sensei_2 = "Nyugi – ne tegyetek hirtelen mozdulatokat. Úgy tűnik, ez a lény nem túl intelligens.",
        Gatekeeper_greetings_Sensei_3 = "Ez most nem fontos. A portálon való áthaladás a mi döntésünk volt, és felelnünk kell érte. Harcot akar – nincs más választásunk, Árnyék.",
        Gatekeeper_lost_Saimon = "Többet vártam a portáltól… Úgy tűnik, az utazás elszívta az erődet, és a molekuláris kötéseid meggyengültek. Érdekes – el kell végeznünk még néhány tesztet.",
        Gatekeeper_win_Saimon = "Évszázadok óta ez a rozoga portál emlékeztetett minket arra, hogy vannak erők, melyek meghaladják a megértésünket. Aztán jöttél te…",
