        HEAD_BERSTUUK = "Berstuuk maszkja",
        HEALTH_DROPS = "Az életerő idővel csökken.",
        HOT_GROUND = "Forró talaj.",
        HW20Arkhos1 = "Nincs szükségem jövőbelátásra ahhoz, hogy lássam: a hit tüze megemészti a gyengéket és a vakokat egyaránt. Fekete gyertyákat hoztam, hogy mindenki olyan tisztán lássa ezt az igazságot, mint én!",
        HW20Fatum1 = "A világok közötti határok elvékonyodnak – ez a legkiválóbb éjszaka a jóslatokra! A levegő zümmög a mágiától, és a kezemben a sors fonalai tekerednek!",
        HW20Fatum2 = "A jóslás számomra egy játék – azt tehetem a halandók sorsával, amit csak akarok. De ti, barátaim, teljesen más tészta vagytok. Kérlek, foglaljatok helyet!",
        HW20Fatum3 = "A gyűlöleted megvakított téged. Kezdjük. Ne beszélj, csak figyelj! Látok egy alakot… fekete, mint az éjszaka… tollak és hamu… és kézen fog engem…",
        HW20Fatum4 = "Hogy… hogy kerültél ide? Az e világba vezető út le volt zárva előtted!",
        HW20Megalith1 = "Jóslásról és álarcosbálról beszéltél, így hoztam egy varázstükröt. Ezer év után először látom a tükörképemet. Ettől a maszktól ősinek tűnök!",
        HW20Whisper1 = "Jóslásosdit játszottál, húgocskám? Halandó sorsokat vettél a kezedbe? Az ilyen játékszerek mindig is csak az enyémek voltak!",
        HW20Whisper2 = "Le volt zárva, az igaz! De te hívtál, és ezen a csodálatos tükrön keresztül megérkeztem. Magammal viszem. Mindenképp látogass meg, és hallgass meg néhány igaz jóslatot!",
        Hunger_AfterLoss = "Mivel te vagy a kiválasztott, adok még egy utolsó esélyt, hogy velem maradj és lakmározz. Különben a csontjaid csatlakoznak a többiekhez a porban.",
        Hunger_AfterWin = "Teremtő, küldtél nekem táplálékot, de nem elég. Az éhségem örökkévaló, adj nekem feloldozást...",
        Hunger_Greetings1 = "Hosszú utat tettél meg idáig. Miért? Hogy megmentsd a hálátlan halandókat? Fittyet hánynak rád! Érzem a magányodat, az éhségedet, és a... félelmedet.",
        Hunger_Greetings2 = "Árny, ne hagyd magad átverni! Csak gyengének tűnik. Nem a barátja vagy, csak a prédája. Darabokra tép, ha közelebb mész!",
        Hunger_Greetings3 = "Látod a fivéreimet? Szomjaznak, de az ő szomjúságuk másfajta. Ők a szórakozásra vágynak. De az ő éhségük semmi az enyémhez képest!",
        INVERTED_JOYSTICK = "Megfordított mozgásirányítás.",
        MERCENARY_RAID = "ZSOLDOSEGYSÉG",
        MERCENARY_RAID_Title = "Zsoldosegység",
        MiniEventAnnounce = "Időtlen idők óta egy szekta lakozik a föld gyomrában, őrködve az alvilági istenek törékeny álma felett, megakadályozva az ébredésüket. De az ár egy kegyetlen rituális csata, amelyet az utolsó csepp vérig vívnak.",
        MiniEventHungerFight_Enter_1 = "Itt a föld alatt minden más. Azért harcolunk, hogy éljünk, és a kaja az élet! Ne foszd meg a te népedet – vagy az enyémet – ettől a hatalmas örömtől!",
        MiniEventHungerStory_1 = "Az emberek csak akkor törődnek a szellemek szeszélyeivel, amikor a baj lesújt az otthonukra. A termésük elhervad, a gyermekeik éheznek… És hol van most a hitük?",
        MiniEventHungerStory_2 = "Az éhségnek van formája. A fogyasztás iránti szomja rettenetes. De ez Karcer szerepe, míg a tiéd és az enyém az, hogy megakadályozzuk, hogy felébredjen évszázados álmából.",
        MiniEventHunger_Loss_1 = "Nem tanította meg az anyád, hogy ne hagyj semmit a tányérodon? Meg is látszik – éhség van a szemedben! Vagy… mi a baj veled?",
        MiniEventHunger_Win_1 = "Igen, jól ütsz, Árnyék… Ünnepeljük meg a győzelmedet egy kis kiadós kajával! Én fizetek!",
        MiniEventStory_1 = "Látom, Árnyék, hogy erős és állhatatos a szellemed. A tetteidről szóló legendák széles körben elterjedtek. Szeretnél egy újabbnak a részévé válni?",
        MiniEventStory_2 = "Az alvilág szellemei önfejűek. Szertartást végzünk, hogy lecsillapítsuk a kedélyeiket – rituális csatákat! A te részvételed megtiszteltetés lenne számunkra.",
        MiniEventStory_EnterBattle = "Nem vagy egy kicsit beteges egy ilyen rejtélyes látványossághoz? És tényleg őt választottad? Ő lenne a legenda embere? Ó, a szellemek felháborodnak majd…",
        MiniEventStory_Loss_1 = "Igen, nos… Hinni akarom, hogy a szellemeknek is van humorérzéke, és csupán nevetnek majd az arénában való csetlés-botlásunkon, ahelyett, hogy ránk zúdítanák a dühüket…",
        MiniEventStory_Win_1 = "Nos… Senki sem jön ebbe az arénába véletlenül. Te valóban a legendák embere vagy, Árnyék.",
        MiniEventVulkanFight_Enter_1 = "A boszorkány ok nélkül ijesztget téged. Ez sokkal egyszerűbb ennél: az acélt tűzben edzik! Az istenek csakis az erőt értik meg, mást nem. Csak az erő térítheti vissza őket álmukba! Támadás!",
        MiniEventVulkanStory_1 = "A tisztító tűz igazságos – legalábbis ezt mondják őseink. De ők nem tudták, hogy a Halhatatlanok mit sem törődnek az emberi erkölccsel. Ez egyszerűen az ő természetük.",
        MiniEventVulkanStory_2 = "Érzed a hőt felemelkedni a föld alól? Egy dolgot tudnod kell: a láng senkit sem kímél, legyen az barát vagy idegen. És mi pont az útjában állunk.",
        MiniEventVulkan_Loss_1 = "Talpra kell állnod, Árnyék! Nem érzed, hogy reng a föld?! Az istent undorítja a mi porban való csetlés-botlásunk…",
        MiniEventVulkan_Win_1 = "Pokoli forróság van itt… A tűzszellem elégedetten morog a boltozatában! Szép harc volt, Árnyék! Újabb napot nyertünk magunknak!",
