        RANDOM_AREA_HEALTH_DEGENERATION = "Életerőt veszítesz a jelzett területen.",
        TRANSIENT_BLEEDING = "Múló égési effektus.",
        Tenebris_greetings_1 = "A valóság peremén állsz, utazó. Ez a végső határ. Ezen a vonalon túl van az az üresség, amelyben a világok születnek. És én voltam az, aki kovácsolta a fényüket és sötétségüket!",
        Tenebris_greetings_2 = "Árnyék, a mögötte lévő portál lehet az esélyünk a megváltásra. Az Örökkévalók azt mondták, elpusztítják a világunkat. Talán az ő segítségével?",
        Tenebris_greetings_3 = "Nem fogod túlélni a portált! Ez terra incognita. A sötétség, amelyben világok teremthetők. De te nem tudsz teremteni, csak pusztítani. A portál egészben fog elnyelni téged!",
        Tenebris_greetings_4 = "Kockázatos, de van más választásunk? Megállíthatjuk az Örökkévalókat, ha belépünk a portálba. De akár hatalmas katasztrófát is okozhatunk.",
        Tenebris_loses = "Félsz a sötétségben ólálkodó ismeretlentől? Most magadra maradsz, hogy egyedül nézz szembe vele! A világ porrá omlik, és újjászületik. A spirált követve.",
        Tenebris_wins = "Makacs bolond! Ti, emberek, csak nyers erővel tudjátok megoldani a problémákat. De az univerzum nem így működik. Ennyi év után sem tanultál semmit...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "Kelj fel, báb! És harcolj! Nem számít, hogy nyersz vagy veszítesz. Amikor harcolsz, engem szolgálsz!",
        War_AfterWin = "Imposztor! Hol van a dühöd? Hogyan harcolhatnál nélküle? Harcolj velem! Kezdjünk egy újabb pengetáncot! Tudom, hogy a háború benned él!",
        War_Greetings1 = "Milyen csodás nap! Érzem, hogy közeleg a csata, mint egy vihar. Mennydörgés. A lépést tartó légiók elmondhatatlan dühe. Mind ajándékok az oltáromon!",
        War_Greetings2 = "Düh és vérszomj forr benne. Kedvét leli a végtelen csatában, de miért? Mit fog találni a koponyákból emelt hegye tetején?",
        War_Greetings3 = "Hát ennyire idegen tőled a véres csata izgalma? Tűz, szenvedély, viharos erő! Mutasd meg, mit tudsz! Szórakoztass egy párbajjal, vagy halj meg!",
        ZONE_RAID = "Alvilág: 1. szint",
        ZONE_RAID1 = "Alvilág: 2. szint",
        ZONE_RAID2 = "Alvilág: 3. szint",
        ZONE_RAID3 = "Alvilág: 4. szint",
        ZONE_RAID4 = "Alvilág: 5. szint",
        ZONE_RAID5 = "Alvilág: 6. szint",
        ZONE_RAID6 = "Alvilág: 7. szint",
        ZONE_RAID7 = "Alvilág: 8. szint",
        blackness_enter_blackness_1 = "Ivadék. Egy nagy áldozat. Egy gömb. Az elme. Mészárlás. Érzem. Vért fogsz ontani. Fájdalmat látok. Látom a jövőt. Megmutatom neked.",
        blackness_greeting_blackness_1 = "Mi a baj, Árnyék? Nem érzed jól magad?",
        blackness_greeting_lazarus_2 = "Simon? Micsoda szemétláda vagy! Miért hoztál ide embereket? Megérzi a gondolataitok szagát! Tűnjetek innen, mielőtt a Feketeség megízleli az elméteket!",
        blackness_greeting_may_1 = "Hallod ezt? Semmi! Csend. Madárdal nélkül olyan, mintha ez a hely borostyánba fagyott volna. Helyesen cselekszünk? Nagyon rossz érzésem van…",
        blackness_greeting_saimon_2 = "Ezek a derék emberek a belépőid a szabadságba, kedvesem. A nagy fekete ruhás valahogy kapcsolatban áll az Obeliszkkel és a Kapukkal. Ő segít neked, te pedig segítesz neki.",
        blackness_greetingn_saimon_1 = "Nem csoda. Mióta az ősi Kapuk egy darabja idezuhant, az élet ezen a helyen statisztikai anomália. Tartsátok nyitva a szemeteket – meg kell találnunk Lázárt.",
        blackness_lose_blackness_1 = "Itt maradsz. Örökké. Egy vér. Mindörökké. Olvasni fogok benned. Táplálkozni fogok.",
        blackness_win_sensei = "Hazudtál nekünk, a tudomány embere! Kit szabadítottunk ki? Mire ítéltük ezt a világot? Felfogod egyáltalán, mit tettél?!",
        characterMay = "MAY",
        characterMiniEventPriestess = "A Papnő",
        characterSensei = "SENSEI",
        characterThief = "RAVASZ",
        character_Blind = "HERMELIN",
