        descSonOfHeaven = "Az Ég fia elfogadta a kihívásodat.{br}({0}. szint)",
        descSonOfTheSun = "A Nap fia elfogadta a kihívásodat.{br}({0}. szint)",
        descStalker = "Stalker elfogadta a kihívásodat.{br}({0}. szint)",
        descTenebris = "Tenebris elfogadta a kihívásodat.{br}({0}. szint)",
        descVolcano = "Vulkán elfogadta a kihívásodat.{br}({0}. szint)",
        descVortex = "Vortex elfogadta a kihívásodat.{br}({0}. szint)",
        descWhisper = "Whisper elfogadta a kihívásodat.{br}({0}. szint)",
        descWolfWind = "Farkasszél elfogadta a kihívásodat.{br}({0}. szint)",
        dlgAmericanEvent22Story_May_1 = "Teljesen átfagyott, Sensei! Nem dobhatjuk ki, amikor odakint ilyen szelek tombolnak az ajtó előtt…",
        dlgAmericanEvent22Story_Puma_1 = "Bajban vannak, öreg… Sosem gondoltam volna, hogy a népem múltja követni fog, de így lett. Így hát elmenekültem, hogy megvédjem őket. Kérlek, hallgass végig!",
        dlgAmericanEvent22Story_Puma_2 = "Ti is halljátok? Amikor gyerek voltam, egy sámán mesélt nekem egy szellemről, akinek az üvöltése felkorbácsolta a hullámokat és letépte a leveleket. Sosem gondoltam volna, hogy ez a régi mese igaznak bizonyul!",
        dlgAmericanEvent22Story_Puma_3 = "Erre jön, hogy az üvöltésével üldözzön minket, amíg össze nem esünk kifulladva… Csak szórakozásból! Nem tudok más helyet, ahol elrejtőzhetnénk…",
        dlgAmericanEvent22Story_Sensei_1 = "Hajlékom ajtaja nyitva áll minden szenvedő előtt. De váratlan egy kalózt látni ezek között a falak között… És hol van a te torokmetsző-bandád, Puma?",
        dlgAmericanEvent22Story_Sensei_2 = "A sámánok mítoszai allegóriák. Az emberek feltalálták a vitorlákat, hogy megszelídítsék a szelet, és azóta is jól szolgálja őket. Te csak egy buta tündérmese vagy, és Árnyék be fogja bizonyítani!",
        dlgAmericanEvent22Story_Wind_Wolf_1 = "Én vagyok a Farkasszél! Bárki is jön elém, úgy alszik ki, mint egy gyertya! És előbb-utóbb rátok töröm az ajtót. Ez csak idő kérdése!",
        dlgAmericanEvent22Story_Wind_Wolf_Lose = "Üvö-üvö-üvölteni fogok, amíg a levelek be nem borítják a roncsokat. Soha senki nem találja meg ide az utat! Merész és ostoba… Hogy harcolhatnál az elemek ellen, halandó?",
        dlgAmericanEvent22Story_Wind_Wolf_Win_1 = "Micsoda szégyen… Elvetted a hatalmas hangomat! De a te hited, lány, újra életre fog kelteni engem… És nem leszek egyedül! Mert mi sokan vagyunk!",
        dlgArkhosGreetings = "Vak fanatikusok! Emlékeztek rám, és az Atyába vetett hitetekkel tápláltok engem. Egy szülő lehet szigorú, ti pedig hálával fogjátok fogadni a büntetésemet...",
        dlgArkhosLost = "Kihez fohászkodjam utolsó órámban? Ó, Teremtőm, miért hagytál el engem? Erőt adtál, hogy isteni utat mutassak nekik, de én cserbenhagytalak... ismét.",
        dlgArkhosStory1 = "Ismerem a fajtáját. Adeptusokat gyűjtenek maguk köré, akiket hazugságokkal etetnek. Ne hallgass a tüzet szító prédikációjára, mert az a legfőbb fegyvere.",
        dlgArkhosStory2 = "Tévedsz, öreg. Tartogatok még kemény vasat is a makacs gyermekeknek. Imádkozni fogsz hozzám, hogy befogadjalak a családba... de én kérlelhetetlen leszek.",
        dlgArkhosWin = "Fekete bárány, méltatlan vagy a mellettem lévő helyre. Távozz! Megviszem a hírt a Teremtőnek, hogy ti, emberek, miként buktatok el újra, ő pedig táplálni fogja gyermekeimet.",
        dlgBerstuuk_Announce = "Tiltott tudást keresve egy tehetséges tudós ötvözte a tudományt és a mágiát annak érdekében, hogy istenné váljon. És az átalakulás elkerülhetetlen! Most az erdő a rémálomszerű laboratóriuma, az emberek pedig a zsákmányai. Csak te állíthatod meg ezt a rémisztő metamorfózist! Űzd el a félelmed, és merészkedj a sűrű bozót szívébe a hamis bálvány nyomában!",
        dlgBerstuuk_Loose_1 = "Amikor az ajtómhoz jöttél, szavak nélkül is mindent elmondtál! Addig húzom ezt a tudást, mint egy vékony fonalat, amíg nem marad belőle semmi!",
        dlgBerstuuk_Story_1 = "Sly van odakint, és az istálló ajtaján kopog… Sokat láttam már az erdőben éjszaka, de ez valami új! Mi a baj vele?",
        dlgBerstuuk_Story_10 = "Nem eleget. A tudomány kiszámíthatatlan – csak nézz rám! Fokozatosan elfogadtam az erdőt, de az folyton visszautasított engem. Egészen mostanáig.",
        dlgBerstuuk_Story_2 = "A segítséget kérők számára az út a megfelelő ajtóhoz vezet. De úgy tűnik, Sly eltévedt… Te vén zsivány, vigyázz a kezeidre! Mi történt?",
        dlgBerstuuk_Story_3 = "A zsivány segítséget keresett, és meg is találta. Irány az erdő, mielőtt elveszik azt, ami jogosan az övék. Az emberek életét!",
        dlgBerstuuk_Story_4 = "»Emberek«? Szegény pára sokkot kapott – nincs is arca! Mi ijesztette meg ennyire, hogy hirtelen lelkiismereti válságba került?",
        dlgBerstuuk_Story_5 = "Hallod a madarak énekét? Ilyenkor már csiripelniük kellene, de itt nincs más, csak síri csend… Mi más leselkedik még ebben az erdőben?",
        dlgBerstuuk_Story_6 = "Síri csend. Síri csend. Az embereknek segítségre van szükségük. Se-e-gítened kell. Segíts most!",
        dlgBerstuuk_Story_7 = "Az istenekre! Az emberek normális esetben nem változnak száraz gallyakká és mohává, akármennyire is félnek! Mi ez a dolog, és hol van az igazi Sly?!",
        dlgBerstuuk_Story_8 = "Valahol itt van a közelben. Sly kis elméje nagyon segítőkész volt. Mesélt nekem rólad, Árnyék – a különleges erődről. És hirtelen megvilágosodtam!",
        dlgBerstuuk_Story_9 = "Szóval te vagy az, akiről a lény beszélt? Az erdő eljön és mindent elragad. És hány ilyen »jogos« életet vettél már el, őrült?",
        dlgBerstuuk_Win_1 = "A természet utat tör magának! A harcunk többet elárult nekem, mint gondolnád, Árnyék. Az erdő emlékezni fog. Fel fog emészteni, hogy újra életre keljen…",
        dlgFatumGreetings = "A bátorságodnak csak a balgaságod mérhető. De tudtam, hogy eljössz, mert te vagy a végzetem, és én a tiéd. Örökre átírom a sorsotokat.",
        dlgFatumLost = "Ismerem az emberiséget. Ugyanazon a spirálon jártok fel s alá. Láttam már ezt többször is. Önpusztítás és elsorvadás. Semmi sem változtathat ezen. Ez a sorsotok.",
        dlgFatumStory1 = "Légy óvatos, hős. Ilyen mélyen a számodra megszokott egyetemes törvények már nem működnek...",
        dlgFatumStory2 = "Úgy bizony! Tartsd pórázon a fiút. Mindent tudok a sorsotokról: kik vagytok és merre tartotok. Eláruljam, ki hal meg a végén?",
        dlgFatumWin = "A sorsod beteljesedett. Már abban a pillanatban veszítettél, mikor átlépted lakhelyem küszöbét. Lesz elég bátorságod újraírni a történeted?",
        dlgFungusGreetings = "Megmérgeztétek a földet, és most a gombáim haldokolnak. El fogják nyelni az elmédet, és mindannyian eggyé válunk, ember. Ez lesz a történeted vége!",
        dlgFungusLost = "A testvéreim megfeledkeztek magukról az istenesdi játék közben. Az imádat lággyá teszi őket. De a pusztítás az emberiség természetében van; a világ jobb lesz nélkületek.",
        dlgFungusWin = "Távozz! És gyönyörködj törékeny életetek utolsó perceiben!",
        dlgHW21LosePuppeteer_1 = "Még egy néma szerepet sem bíznék rád, Árnyék. A színpad nem a te helyed – ne hozd szégyent a mesterségemre!",
        dlgHW21StoryArkhos_1 = "A pestis eléri a városotokat, halandók! Hajoljatok meg istenetek hatalma előtt! És gyönyörködtessétek szemeteket az arany ragyogásában, különben…",
        dlgHW21StoryPuppeteer_1 = "Mit is tudnátok ti a művészetről! Tönkretettétek a legnagyobb vállalkozásomat! Mindazonáltal… jön a harmadik felvonás. És abban a hős kileheli a lelkét!",
        dlgHW21StorySensei_1 = "Mióta jönnek fel ide az alvilág istenei, hogy pénzt zsaroljanak ki hétköznapi emberektől? Dobd el a maszkodat, csaló, mielőtt fegyvert fogunk!",
        dlgHW21StorySensei_2 = "A színháznak inspirálnia kell, nem megrémisztenie. Te pedig eltorzítottad a művészet leglényegét. Megállítunk, mielőtt a »színészeidnek« bántódása esne.",
        dlgHW21StoryThief_1 = "Várjatok! Én vagyok az… Sly! Ne üssetek meg! Azt ígérte, hogy mindenki félni fog tőlem… És senki sem fog felismerni. Hogy buktattam le magam?",
        dlgHW21StoryThief_2 = "A vándorszínház tulajdonosa – a Bábmester. Azt mondta, ez lesz a legjobb előadása. Istenek az emberek között! Számomra ez semmit sem jelentett. De a pénz, az már más kérdés…",
        dlgHW21WinPuppeteer_1 = "Ez egy fiaskó! Tönkretettétek a csodálatos cselekményemet, és összetörtétek a maszkjaimat! Hogyan állítsak most színpadra egy darabot kellékek nélkül…",
        dlgHW22EnterArchitect = "Ez a sok fantasy narratívátok teljesen kimerített… Mostantól az én szabályaim szerint játszunk. És a te érdeked, hogy meglepj engem, Árnyék…",
        dlgHW22LooseArchitect_1 = "Erre lehetett számítani. Minden mozdulatodat ismerem, Árnyék. Végül is én találtalak ki. Talán akkoriban nem voltam a formámban… De az új életed tetszeni fog.",
        dlgHW22StoryArchitect_1 = "Ezt hívják »klisének«, Bábmester. Miért fizetik a drámaírókat? A szimbólumok számáért? A gügyögő, őrült zseni alakja éppúgy elcsépelt lett, mint a hősé…",
        dlgHW22StoryArchitect_2 = "Ennyi. A nulláról fogjuk újraírni a világotokat! Kortárs, kreatív, releváns! Mit szeretnek mostanában a tinédzserek? Miért nem mondasz semmit, Árnyék? Ó, igen…",
        dlgHW22StoryPuppeteer_1 = "Kopogtatnak – váratlan kopogtatás az ajtódon! Egy utazó jött látogatóba, vagy valami több? Érdekfeszítő, nemde?",
        dlgHW22StoryPuppeteer_2 = "Tudtam, hogy ezt fogod mondani, öregem. Mi mást is várhatna az ember kitalált karakterektől? A papír mindent elbír… De a közönség soha!",
        dlgHW22StoryPuppeteer_3 = "Csupán a színpad rabszolgája vagyok, ez minden. Új mesterművem pedig a teremtővel való találkozásról fog mesélni – a predesztináció és a szabad akarat gyötrelmeiről…",
        dlgHW22StorySensei_1 = "Bármit is álmodtál meg, Bábmester, nem játsszuk tovább a játékaidat. A művészet okozhat fájdalmat, de nem úgy, ahogy te műveled.",
        dlgHW22StorySensei_2 = "Túl sokat színészkedtél, és már nem tudod megkülönböztetni a valóságot a fantáziáidtól, előadóművész… Őrült vagy.",
        dlgHW22StorySensei_3 = "A szavaid különösek és aggasztóak, idegen… Nem tudom, milyen őrültség folyik a fejedben, de Árnyék majd kiveri belőled.",
        dlgHW22WinArchitect_1 = "Talán a teremtmény már nem tartozik a teremtőjéhez, és önálló életre kelt… Meglepettél. Látni akarom, merre folytatódik a történet.",
        dlgHoaxenGreetings = "Az egész életed csupán illúzió. És mi vagyunk a teremtői. Megőrjítünk téged, míg mások a nyers erőre támaszkodnak. Tűz, víz, betegségek – hah!",
        dlgHoaxenLost = "Hol vagy, testvérem? Nem hallom többé a hangodat! Valóban, teljesen egyedül bezárva lenni rosszabb, mint a tűz vagy a penge... Menjetek, ostobák. Az Atya vár rátok.",
        dlgHoaxenStory1 = "„Mi”? Árny, úgy tűnik, az ellenfelünk elment az eszétől. Elnézést, de melyik személyiségeddel beszélgetünk éppen? Talán a „testvéred” ésszerűbb lenne?",
        dlgHoaxenStory2 = "Nevetsz rajtunk, ember? A testvérem azt javasolja, hogy a lelketeket küldjük az örök gyötrelem szakadékába... Akkor a világotok behódol, egyetlen csepp vér nélkül.",
        dlgHoaxenWin = "Megöltelek volna, mert a kegyelmem valóban határtalan. De a testvérem kevésbé toleráns; szabadon távozhatsz, feltéve, ha nem veszíted el a józan eszed a kifelé vezető úton.",
        dlgHunter_enter_hunter_1 = "Te! Hé, teeeee! Azért jöttél, hogy befejezd, amit elkeeazdtél, mi? Te? Van benned egy erő. Beszééél hozzám. Pszt! Különben rákééényszerítelek!",
        dlgHunter_greeting_may_1 = "Nézzétek! Van valami a kristály belsejében… Ennek ilyennek kell lennie?",
        dlgHunter_greeting_saimon_1 = "Milyen furcsa… Arra számítottam, hogy Lázár porrá zúzza az Obeliszket. Féltem a mészárlástól, de úgy tűnik, csak te és én maradtunk. Felkeltetted az érdeklődésemet.",
        dlgHunter_greeting_saimon_2 = "A Koncentrációs Csarnok. Látod azt a kristályt középen? Az Obeliszk így halmozza fel az árnyékenergiát – hogy úgy mondjam, a sötétség szívében.",
        dlgHunter_greeting_sensei_1 = "A csend rossz ómen, racionális barátom. Hangosabban beszélhet a legsiketítőbb szavaknál is. Hmm… Hol vagyunk? Milyen bizarr hely ez?",
        dlgHunter_greeting_sensei_2 = "Kétlem, kedvesem… Ez a hely másképp néz ki, mint ahogy utoljára láttam. Kezdem azt hinni, hogy az öregnek igaza volt…",
        dlgHunter_loose_hunter_1 = "Feküdj leeee. Itt hagylaaaaak örökkéééé. Ne okozz tööööbb kárt.",
        dlgHunter_win_hunter_1 = "Állj meg, Árnyék-ember! Ne hagyd, hogy elterjedjeeeeen! Olyaaaan leszel, mint őőőő. Be fognak csapaaaaani! De még van esélyeeeeeed.",
        dlgIE21AnnounceAssistant_1 = "Ki a csuda ez? Mit keresel a mi világunkban, és miért kellene egyáltalán meghallgatnunk téged?",
        dlgIE21AnnounceAssistant_2 = "Ha! Nem tudom, honnan jöttél, de nem maradsz itt sokáig!",
        dlgIE21AnnounceAssistant_3 = "Hé, Árnyék, ez a zsarnok túl messzire ment! Tanítsuk meg a jó modorra!",
        dlgIE21AnnounceBoss_1 = "Ti szánalmas halandók! Hajoljatok meg az akaratom és dicsőségem előtt, különben én kényszerítelek térdre benneteket!",
        dlgIE21AnnounceBoss_2 = "Hogy merészelsz így beszélni velem – én vagyok Rávana, a három világ meghódítója!",
        dlgIE21AnnounceBoss_3 = "Ez az utolsó esélyed, hogy letérdelj. Ha visszautasítod, veszem a fejed!",
        dlgIE21AnnounceSensei_1 = "Árnyék, egy titokzatos fenyegetés közeledtét érzékelem. Valami gonosz dolog ismét utat talált a világunkba.",
        dlgIE21Boss_After_Loose = "Ha ezen a világon minden ember ilyen gyenge, akkor a meghódítása csak idő kérdése!",
        dlgIE21Boss_After_Win = "BOLONDOK! Egyelőre visszavonulok, de nem fogtok ilyen könnyen legyőzni. Még visszatérek!",
        dlgIndia22Story_May_1 = "És így éhezni kezdtetek… Mit akarhatott ez a démon a ti vidám ünnepléseteken? Hogyan vonzhattak szerény parasztok egy ilyen ragadozót?",
        dlgIndia22Story_Rakshasa_1 = "Érdekes illatod van, ember. Kétségtelenül pont olyan jóízű is lennél! Hallod, hogy korog a gyomrom? Egy válogatott hússzelet a rizsem mellé nagyon is jól jönne!",
        dlgIndia22Story_Rakshasa_Lose = "Szerencsédre a harcunk kimerített. Ráadásul az éhségem is csillapodott… egyelőre. Újra étvágyat csinálok magamnak, és újra vadászni fogok!",
        dlgIndia22Story_Sensei_1 = "Mesélj róla, utazó. A ruháidból látom, hogy messziről jöttél. Milyen baj sújtja az otthonodat?",
        dlgIndia22Story_Sensei_2 = "Fékezd meg az étvágyad, démon! Nem kap meghívást az élet fesztiváljára az, aki magát az életet veszi el!",
        dlgIndia22Story_Sensei_Win = "Nem a varázslat teszi virágzóvá a kertet, hanem a kemény munka. És ezt te magad fogod bebizonyítani: segíts a szomszédaidnak helyreállítani a farmjukat, különben…",
        dlgIndia22Story_Sitaram_1 = "Hallottam életed történetét. Jutalmazzanak meg az istenek érdemeid szerint! Rossz hírrel érkezem: egy gonosz szellem jelent meg a földjeimen…",
        dlgIndia22Story_Sitaram_2 = "Ennek a démonnak a gonoszságával csak az éhsége ér fel! Épp arra készültünk, hogy megünnepeljük a Bohag Bihut, amikor hirtelen ez a… lény megjelent, és felfalta az összes palántánkat!",
        dlgIndia22Story_Sitaram_3 = "Agni a tanúm, hölgyem, én is ugyanezt kérdezem magamtól! Most rettegve várjuk a naplementét… Jöjjön velem, könyörgöm!",
        dlgIndia24_Enter_Puppet_1 = "Megvan benned a sors irányításához szükséges szellem? Döntsd el az enyémet, hisz a művészetek alázatos szolgája vagyok. Csak a harcban érted meg igazán, mi micsoda. Légy bátor, Árnyék – támadj!",
        dlgIndia24_Story_Dandy_1 = "Nyissátok ki, különben betöröm ezt az átkozott ajtót! Tudom, hogy itthon vagytok – hallom! Felgyújtom ezt a viskót, ha nem adtok menedéket!",
        dlgIndia24_Story_Loose_Nrityu_1 = "Ó, milyen hevesen ragaszkodnak a halandók az élethez. Nem én választottam ezt a munkát, és nem fogok mérges könnyeket hullatni miatta… Miért tettétek ezt velem?",
        dlgIndia24_Story_Loose_Puppet_2 = "A szíve tele van szeretettel. Az istenek tisztának teremtenek minket, de mi magunk választjuk meg az utunkat. Nrityu kezdi ezt megérteni, ahogy hallgatja a lány történetét.",
        dlgIndia24_Story_Loose_Puppet_3 = "Árnyék, az előadásodból hiányzik a szenvedély és az elkötelezettség. Adok még egy esélyt. Ne csak eljátszd – éld is át!",
        dlgIndia24_Story_Puppet_1 = "Kopp-kopp! Hé, régi barátaim! A sors hangja utolért minket – és már úton is van! Vörös szegélye úgy parázslik, mint maga az élet a naplementében!",
        dlgIndia24_Story_Puppet_2 = "Vajon a lelkedért jött? Íme egy olyan ősi mese, mint maga a világ – Nrityu legendája, kinek sorsa az volt, hogy életek elvevője legyen.",
        dlgIndia24_Story_Puppet_3 = "A szellemek mind csak fecsegnek. Nem bízhatsz bennük. Ráadásul nem az ő történetük. Megmutatom az igazságot az ő szemein keresztül. Árnyék, te vagy az egyetlen, aki megértheti.",
        dlgIndia24_Story_Sensei_1 = "Ez a hang… Úgy tűnik, régi ellenfelünk ismét sántikál valamiben. Ki lesz ezúttal az áldozat? Látok egy férfit futni a pagoda felé…",
        dlgIndia24_Story_Sensei_2 = "A ruhádat mocsok és korom borítja, idegen. A hangnemed pedig nyugtalanít. Magyarázd meg, ki vagy, és mi járatban vagy a küszöbünkön!",
        dlgIndia24_Story_Win_Faradeya_1 = "Hátraarc! Én nem akartam ezt! A családom félt tőlem, és azt hittem, ez az én esélyem… Dandy megígérte, hogy magával visz, ha segítek…",
        dlgIndia24_Story_Win_Nrityu_1 = "Így ni! Örök álomba szenderülsz, bár nem érdemled meg. De nem az én tisztem megítélni téged – az másnak a hivatása. Én csak kísérő vagyok.",
        dlgIndia24_Story_Win_Puppet_4 = "Pont mint te, Árnyék. Azt akarom, hogy kövesd Nrityu útját. Neki egy örökkévalóságba telt, mire megértette a helyét.",
        dlgIndia24_Story_Win_Puppet_6 = "Az előadás folytatódik! Te, Árnyék, leszel a sztár, az én színészeim pedig a mellékszereplőid. Nrityu története lesz a mi legnagyobb produkciónk!",
        dlgIndia24_Story_Win_Sensei_1 = "Ez a történet nagyon mélyre hatol – még hozzád képest is. Meg vagyok lepve! De mi itt a tanulság? Miért mutatod ezt nekünk?",
        dlgMegalithGreetings = "Ez a bánya szent hely. Miért vagy itt? Távozz, és nézz szembe a végzeteddel emelt fővel! Az utolsó dolog, amit hallani fogsz, a lábad alatt megremegő föld lesz.",
        dlgMegalithLost = "Kárhozat! Újra évezredekig kell várnom? Kontinenseket mozgattam meg! A föld megtisztítása az én feladatom volt!",
        dlgMegalithWin = "Kedvesen bántam az emberekkel, ami ritka tulajdonság az Örökkévalók között. Sokszor segítettem a fajotoknak. Úgyhogy fussatok, és mondjatok utolsó búcsút a szeretteiteknek!",
        dlgRaidIntro1 = "Úgy próbálod kijavítani a hibádat? Megnyitottad a Kapukat, de az Árnyékfertőzést csak az Örökkévalók képesek felszámolni. Mivel nem vagy közénk való, gyenge vagy.",
        dlgRaidIntro2 = "Meghalsz, mint a többiek. Magma folyik az ereimben, és beborítja majd az egész földet, megtisztítva azt egy új élet számára.",
        dlgRaidStory1 = "Milyen pince ez, és mit keresünk itt?",
        dlgRaidStory2 = "Ez az Örökkévalók birodalmának előszobája. Évezredekig szunnyadtak, de az Árnyak Kapuja veszélybe sodorta a világot. Felébredtek.",
        dlgRaidStory3 = "Szuper – ez azt jelenti, hogy gyorsan és egyszerűen segítenek majd elintézni a Kapukat!",
        dlgRaidStory4 = "Ó, nem. El fogják pusztítani a Kapukat, de velük együtt a teljes emberiséget is. Számukra ez csupán a pusztítás és teremtés egy újabb ciklusa.",
        dlgShurale_Announce = "A kapzsi banditák által felébresztett erdei szellem most az ártatlanokon áll bosszút. A lény az ellopott emlékek ládáját keresi – ősi mágiájának hordozóját. Csak azok csillapíthatják le a lény dühét, akiknek a szívében igaz bánat lakozik. Az ár azonban borsos lesz…",
        dlgStoryBtnFight = "HARC!",
        dlgStoryBtnMore = "TÖBB",
        dlgVolcanoGreetings = "Az Örökkévalók közül én ébredtem fel elsőként. Sok harcos jön majd, hogy elessen a kezem által, én pedig beteljesítem a küldetésem.",
        dlgVolcanoLost = "Elég! Megadom magam. De tudd meg: felébresztetted a testvéremet. Ne tévesszen meg a külseje, mert gyors és halálos!",
        dlgVolcanoStory1 = "Félig lerombolt lakóhelyeket és egy hatalmas szobrot láttam. Élnek itt emberek?",
        dlgVolcanoStory2 = "Csak fanatikusok. Imádják az Örökkévalókat abban a reményben, hogy megkímélik őket. Valóban vakok a hitükben. Ha elbukunk, hamarosan megtanulják az igazságot.",
        dlgVolcanoWin = "Mindig is mondtam a testvéreimnek, hogy az én kötelességem eldönteni a bolygó sorsát. Nézzétek, hitetlenek, ahogy a lángom beborítja a földet!",
        dlgVortexGreetings = "A sötét vizek elnyelik a földet és az Árnyak Kapuját! Titkuk elvész a mélységben. És nem marad senki a felszínen, aki elmesélhetné!",
        dlgVortexLost = "Ezer év óta először győz egy ember. Oly erős benned az élni akarás! De bármit is teszel, a vég ugyanaz lesz: meg fogsz halni.",
        dlgVortexWin = "Évezredek óta figyelem a fajtádat elsorvadását. Van benne némi szépség. Úgy gondolom, életben tartalak – csak a móka kedvéért.",
        dlgWhisperGreetings = "Úgy tűnik, valaki alig várja, hogy felfedezze a sorsát. Add a kezed, és nézz a tükörbe!",
        dlgWhisperLost = "Még mindig élsz? Akkor még nem állsz a hatalmamban! Fatum megjósolja a sorsodat, én pedig visszatérek a világomba – miután figyelmeztettelek, hogy óvatosan bánj a tükrökkel!",
        dlgWhisperWin = "Magammal viszlek a hamu, a szellemek és az örök éjszaka birodalmába! Bízz bennem – nézz a szemembe, és ne kapd el a tekintetedet.",
        dlg_American_25_Loose_1 = "Nem tudod, kit védelmezel, Árnyék. Nem fognak köszönetet mondani. Csak gúnyolódni fognak a hátad mögött. Vadállatok… és én lennék a szörnyeteg?",
        dlg_American_25_Story_1 = "May eltűnt. Valami alig emberi lény vitte el. Mégsem voltak sikolyok, sem küzdelemre utaló nyomok… mintha jószántából ment volna el.",
        dlg_American_25_Story_2 = "Nem vagyunk egyedül ebben. Mások is eltűntek, akik olyanok, mint May – fiatalok, erősek. Érezte, hogy közeleg… és teletömte a zsebeit puskaporral.",
        dlg_American_25_Story_3 = "A nyoma világos. Meg kell találnunk, mielőtt megérkeznek az esők, különben örökre elvész. Gyere, Árnyék!",
        dlg_American_25_Story_4 = "Megéreztem a szagodat abban a pillanatban, ahogy a lábadat erre az elátkozott földre tetted. Miért jöttél? Hogy sárba tipord a gyászomat? Nincs benned becsület – ahogy bennük sem volt.",
        dlg_American_25_Story_5 = "Tudtam, hogy feltűnsz, sámán. Add vissza a gyerekeket a rokonaiknak, a barátunkat pedig nekünk. Aztán menj, és rohadj meg a hamuhegyeden.",
        dlg_American_25_Story_6 = "Porból lettél. És porrá is leszel, halandó…",
        dlg_American_25_Win_1 = "Várj! Önszántamból mentem vele. A külseje valóban bestiális – de a szíve emberi. És szenved… Ellopták a gyermekét!",
        dlg_CHN_NY25_Announce = "Merülj el egy letűnt kor hősének történetében – bogozd ki az igazságot a meséből, és segíts egy új legenda kovácsolásában! Szállj szembe egy titokzatos szektával, amely egy nagy hős nevét használja álcaként atrocitásaihoz! Térj vissza oda, ahol minden elkezdődött, és segíts egy szökevény csibésznek felfedezni valódi hősiességét!",
        dlg_CHN_NY25_Loose_1 = "Nem, tovább kell harcolnunk! Senki sem hinné el, hogy egy egyszerű földműves ilyen könnyedén legyőzhet egy baljós szektát. Mindent bele kell adnod!",
        dlg_CHN_NY25_Story_1 = "A Nap Szekta hagyománya, hogy évente egyszer ellátogat nagy hősük szülőhelyére. De minden alkalommal katasztrófának bizonyul…",
        dlg_CHN_NY25_Story_2 = "Embernek született? Milyen különös. Nekem úgy tűnik, ezek az emberek nem ajándékokat hoznak a faluba…",
        dlg_CHN_NY25_Story_3 = "Semmit sem hagynak érintetlenül! Jószágot lopnak a falusiaktól, részeg őrjöngésükben letarolják a termést, ablakokat zúznak be és kötekednek!",
        dlg_CHN_NY25_Story_4 = "De miért nem vágnak vissza a falusiak? Ez az ő földjük és az ő legendájuk!",
        dlg_CHN_NY25_Story_5 = "Megtörtek. A hős, aki reményt adott nekik, eltűnt, a szektások pedig az ő nevében követnek el gonoszságokat. Újra reményt kell adnunk nekik!",
        dlg_CHN_NY25_Story_6 = "Mondd, hogy azért jöttél, hogy ellenőrizd, minden készen áll-e az »ünnepre«. És mi harcolni fogunk! A városlakók látni fogják, hogy a szektával szembe lehet szállni!",
        dlg_CHN_NY25_Story_7 = "Nagyon jól van, legyen a te akaratod szerint… Hadd bújjak szerepbe. »Hé, fiú, hogy merészeled hősünk öltözékét viselni! Takarodj – lakomát kell készítenünk!«",
        dlg_CHN_NY25_Story_8 = "Lehet, hogy nem vagyok legendás hős, de a szelleme ezen a földön él! Ő fog vezetni a legsötétebb órámon, és bátorságot ad nekem! Támadás!",
        dlg_CHN_NY25_Win_1 = "Nem vártam ekkora gyorsaságot egy puszta embertől… Majdnem legyőzted a bajnokunkat! Példát kell statuálnunk veled, nehogy másoknak is ötletei támadjanak…",
        dlg_NY25_Loose_1 = "Az emlékeid élénkek, és a gyász hangosabban beszél, mint az ész. Itt maradsz velem. Pihenj egy kicsit – az álom hamarosan eljön.",
        dlg_NY25_Story_1 = "Üdvözöllek! Ez a kunyhó egykor a családomé volt. Annyi emlék… Maradjatok, ameddig csak akartok. Itt minden megvan, amire a pihenéshez szükségetek lehet.",
        dlg_NY25_Story_2 = "De már annyiszor sodortál minket veszélybe, és most felajánlod, hogy szálljunk meg a családi házadban? Ez valami csel?",
        dlg_NY25_Story_3 = "Csak a lelkiismeret hangja beszél belőlem! Ráébredtem, hogy túl sokáig használtam ki mások kedvességét. De most jót akarok tenni.",
        dlg_NY25_Story_4 = "Nem vagyunk egyedül… Emberek gyülekeznek a kunyhó előtt. Mit akarnak ilyen későn? Hívnak minket, hogy menjünk ki.",
        dlg_NY25_Story_5 = "Ne tegyétek! A fantomok elpusztítanak titeket! Ők csak a fájdalmas emlékek szellemei. Az erdei szellem eljött a ládájáért! Szerezzük vissza!",
        dlg_NY25_Story_6 = "Egy ládáért? Szóval ezért tűnnek el emberek az erdőben! Miért árultál el minket, Sly? Mindenképpen segítettünk volna ebben a nemes küldetésben!",
        dlg_NY25_Story_7 = "Nem érted. Ha meghallom a hangját, elveszítem az irányítást – és én is el fogok tűnni. Mindaddig, amíg egy darabot hordozok belőle magammal.",
        dlg_NY25_Story_8 = "Nyisd ki az ajtót, nagyon fázom idekint, Apa. A ház hideg, és én nem vagyok bent. Mutatok neked egy helyet, ahol újra együtt lehetünk.",
        dlg_NY25_Story_9 = "Állj! Ne menj az erdőbe – eltévedsz! Nem tudom, kinek a hangját hallod, de az biztosan nem emberi!",
        dlg_NY25_Win_1 = "Ébredj, Sly! Add vissza a ládát a szellemnek, amíg gyenge. Hadd lássa, hogy az emberiség képes felülkerekedni a saját kapzsiságán.",
        saturn_enter_saturn_1 = "Visszanyomom a szavakat a torkodon. A barátaid pedig végignézik. A börtönömből az egyetlen út a vérpadon át vezet. Ki akar kezdeni?",
        saturn_greeting_saimon_1 = "Uralkodónk, a Pátriárka, éveken át tanulmányozta a portált. Aztán egy nap magába fordult. Később felállította az Obeliszket, és ez tett valamit a világunkkal…",
        saturn_greeting_saimon_2 = "Árnyék molekuláris szinten hasonló az Obeliszkhez. Van valaki, aki segít majd ezt felhasználni a Pátriárka ellen. Ezért vagyunk itt, a Szaturnusz kamrájában…",
        saturn_greeting_saimon_3 = "Ezer bocsánat, hölgyem. Mindazonáltal ki kell szabadítanunk Lázárt. Kérem, mutassa meg nekünk a celláját, és nem zavarjuk tovább.",
        saturn_greeting_saturn_1 = "Messzire mentek, gyerekek? Szabad akaratotokból jöttetek a börtönömbe! Kíváncsi vagyok – ez bátorság vagy ostobaság? Te, az a langaléta – felelj!",
        saturn_greetingn_May_1 = "De mi köze ennek hozzánk?",
        saturn_lose_saturn_1 = "Ez elég lesz nektek. Ha Lázár ilyen selejtekkel barátkozik, mint ti, akkor nem jelent veszélyt a Pátriárkára. Tűnjetek innen, kölykök! Nem vagytok a listámon.",
        saturn_win_saturn_1 = "Soha nem találjátok meg Lázárt. Az a zsivány megszökött a börtönömből, és a mocsarakba menekült. Ti is el akartok pusztulni? Akkor menjetek csak utána!",
        summerfest25_story2_1 = "Nos, nos… Olyannyira alig vártad, hogy megtalálj, úgy gondoltam, megteszem neked ezt a szívességet. Különben is, már mindenki erre a pillanatra várt.",
        summerfest25_story2_2 = "»Mindenki«? Fejezd be a színészkedést. Pontosan tudjuk, ki vagy – és hogy hogyan használsz ki másokat, csak hogy a nyomorúságukon mulass.",
        summerfest25_story2_3 = "Csak egy kis cameoszerep, és bumm – trendi vagyok! Őszintén szólva, nem számítottam ekkora népszerűségre.",
        summerfest25_story2_4 = "A szellemességed nem fog megmenteni. Fizetni fogsz – a szemeimért, és minden gonoszságért, amit elkövettél. Itt véget ér a kifacsart istenjátszmád!",
        summerfest25_story2_5 = "Komolyan, Hermelin? Ez a fajta beszéd a kinyitható telefonokkal együtt kiment a divatból. 2026-ot írunk – próbálj haladni a korral.",
        summerfest25_story2_6 = "Bármit is tervez az Építész… sötétség veszi körül. Egy olyan rosszindulatú erő, ami szinte tapintható.",
        summerfest25_story2_7 = "Minden egyes szavával egyre jobban elhiszem Hermelin történetét. Az Építész veszélyes – és meg kell állítani.",
        summerfest25_story2_defeat_1 = "Ó, nem – milyen kiábrándító! A közönség többet várt. Úgy tűnik, legközelebb egyszerűen emelnem kell a tétet.",
        summerfest25_story2_win_1 = "Miért olyan kegyetlen a világ? Miért kell szenvednünk? Miért kellett megvakítanom magam? Válaszolj, Építész – miért fáj élni!?",
        tutorial_ascention_intro_title = "BÁBMESTER",
    },
    ita = {
        ActScreenRaid = "Il{br}Mondo Sotterraneo",
        BLACKNESS = "L'OSCURITÀ",
        BLACKNESS_TITLE = "L'Oscurità",
        BODY_BERSTUUK = "Forma di Berstuuk",
        BOSS_BISON_21 = "ADANTI",
        BOSS_BISON_Title = "Adanti",
        BOSS_LAMB = "L'AGNELLO",
        BOSS_RAVANA = "RAVANA",
        BOSS_RAVANA_Title = "Ravana",
        CharacterIndia24Nrityu = "NRITYU",
        DEMON_RAID = "GUANTO DI SFIDA",
        DEMON_RAID_Title = "Guanto di Sfida",
        EARTHQUAKE = "Scosse periodiche",
        EnterPortal_ActScreen = "Portale",
        FRAGILITY = "Maggiore vulnerabilità nell'area indicata",
        Gatekeeper_greetings_1 = "Aria strana? Aria strana! Arrria strrrana!",
        Gatekeeper_greetings_2 = "Non felici, non felici, non felici! Fatto, fatto, fatto!",
        Gatekeeper_greetings_Assistant_1 = "Shadow! Ti sei finalmente svegliato!",
        Gatekeeper_greetings_Assistant_2 = "Fa così freddo qui! Non mi sento già più le dita... Dove siamo? L'aria è così strana.",
        Gatekeeper_greetings_Assistant_3 = "Ma perché ho la sensazione che ci capisca?",
        Gatekeeper_greetings_Sensei = "Indietro, May! Non sappiamo cosa voglia! Il mondo degli Immortali è stato scosso più di quanto pensassi. Dopo quello che abbiamo fatto, non sono felici che noi siamo qui.",
        Gatekeeper_greetings_Sensei_2 = "Calma, ora. Non fare movimenti bruschi. Sembra che questa creatura non sia molto intelligente.",
        Gatekeeper_greetings_Sensei_3 = "Non è importante ora. Attraversare il portale è stata una nostra scelta e dobbiamo risponderne. Vuole combattere, non abbiamo scelta, Shadow.",
        Gatekeeper_lost_Saimon = "Mi aspettavo di più dal portale... Sembra che il viaggio abbia prosciugato le tue forze e i tuoi legami molecolari si siano indeboliti. Interessante... dovremo condurre qualche altro test.",
        Gatekeeper_win_Saimon = "Per secoli, questo portale traballante ci ha ricordato che ci sono forze oltre la nostra comprensione. Poi sei arrivato tu...",
        HARD_GROUND = "Quando cadi a terra, subisci danni.",
        HEAD_BERSTUUK = "Maschera di Berstuuk",
        HEALTH_DROPS = "La vita cala col passare del tempo",
        HOT_GROUND = "Terreno bollente",
        HW20Arkhos1 = "Non mi serve la preveggenza per capire che il fuoco della fede consumerà sia i deboli che i ciechi. Ho portato delle candele nere, in modo che tutti possano vedere questa verità chiaramente quanto me!",
        HW20Fatum1 = "I confini tra i mondi si assottigliano: questa è la notte migliore per le profezie! L'aria freme di magia, e tra le mie mani sono avvolti i fili stessi del destino!",
        HW20Fatum2 = "Per me la divinazione è un gioco: posso disporre del destino dei mortali come mi pare. Ma voi, amici miei, siete un'altra faccenda. Prego, sedetevi!",
        HW20Fatum3 = "Sei stato accecato dal tuo odio. Iniziamo. Non parlate, ma ascoltate. Vedo una figura... nera come la notte... piume e ceneri... che mi prende per mano...",
        HW20Fatum4 = "Come... come sei arrivata fin qui? Il passaggio per questo mondo ti era stato sigillato!",
        HW20Megalith1 = "Parlavi di divinazione e di un ballo in maschera, così ho portato uno specchio magico. Per la prima volta in mille anni riesco a vedere il mio riflesso. Questa maschera mi fa sembrare antico!",
        HW20Whisper1 = "Hai giocato a fare profezie, sorellina? Ti sei presa carico dei destini mortali? Certi giocattoli sono sempre stati solo miei!",
        HW20Whisper2 = "Sigillato, sì! Ma tu hai chiamato e, attraverso questo meraviglioso specchio, io sono venuta. Lo porto con me. Assicurati di farmi visita per ascoltare delle vere predizioni sul tuo futuro!",
        Hunger_AfterLoss = "Visto che sei il prrrescelto, ti darò un'ultima possibilità di restare con me e banchettare. Altrrrimenti, le tue ossa cadranno insieme alle altre nella polvere.",
        Hunger_AfterWin = "Creatore, mi mandi il sostentamento, ma non è sufficiente. La mia fame è eterna, liberami...",
        Hunger_Greetings1 = "Hai fatto molta strada per arrivare qui. Per quale ragione? Per salvare i morrrtali? A loro non importa nulla di te! Sento la tua solitudine, la tua fame, la tua... paurrra.",
        Hunger_Greetings2 = "Non farti ingannare, Ombra! Sembra debole, ma non lo è. Non sei un amico, ma la sua preda. Ti farà a pezzi se ti avvicinerai ulteriormente!",
        Hunger_Greetings3 = "Vedi i miei fratelli? Hanno sete, ma la loro sete è diversa. Hanno sete di diverrrtimento. Ma la loro fame non è paragonabile alla mia!",
        INVERTED_JOYSTICK = "Movimenti invertiti",
        MERCENARY_RAID = "UNITÀ{br}MERCENARIA",
        MERCENARY_RAID_Title = "Unità Mercenaria",
        MiniEventAnnounce = "Da tempo immemorabile, un culto dimora nelle viscere della terra, vegliando sul delicato sonno degli dèi del sottosuolo per impedirne il risveglio. Ma il prezzo è una crudele battaglia rituale, combattuta fino all'ultima goccia di sangue.",
        MiniEventHungerFight_Enter_1 = "Qui, sotto la terra, tutto è diverso. Combattiamo per vivere e la pappa è vita! Non privare la tua gente, o la mia, di questa grande gioia!",
        MiniEventHungerStory_1 = "La gente si preoccupa dei capricci degli spiriti solo quando i guai si abbattono sulle loro case. I loro raccolti appassiscono, i loro figli soffrono la fame... E dov'è finita la loro fede, ora?",
        MiniEventHungerStory_2 = "La fame ha una forma. La sua sete di consumare è terribile. Ma questo è il ruolo di Karcer, mentre il tuo e il mio è impedirgli di svegliarsi dal suo sonno plurisecolare.",
        MiniEventHunger_Loss_1 = "Tua madre non ti ha insegnato a non lasciare nulla nel piatto? Si vede: c'è fame nei tuoi occhi! O... che cos'hai che non va?",
        MiniEventHunger_Win_1 = "Sì, colpisci bene, Shadow... Celebriamo la tua vittoria con del cibo abbondante! Offro io!",
        MiniEventStory_1 = "Vedo che tu, Shadow, sei forte e saldo di spirito. Le leggende sulle tue imprese sono molto diffuse. Ti piacerebbe diventare parte di un'altra?",
        MiniEventStory_2 = "Gli spiriti del sottosuolo sono imprevedibili. Noi eseguiamo una cerimonia per placare i loro animi: delle battaglie rituali! La tua partecipazione sarebbe un onore per noi.",
        MiniEventStory_EnterBattle = "Non sei un po' troppo gracile per uno spettacolo così arcano? E hai scelto proprio questo, sul serio? Sarebbe questo un uomo leggendario? Oh, gli spiriti saranno indignati...",
        MiniEventStory_Loss_1 = "Sì, beh... Voglio credere che anche gli spiriti abbiano un po' di senso dell'umorismo e che rideranno dei nostri pasticci nell'arena, invece di scatenare la loro furia su di noi...",
        MiniEventStory_Win_1 = "Beh... Nessuno arriva in questa arena per caso. Sei davvero un uomo leggendario, Shadow.",
        MiniEventVulkanFight_Enter_1 = "La strega ti spaventa senza motivo. È molto più semplice di così: l'acciaio si tempra nel fuoco! Gli dèi capiscono la forza e nient'altro. Solo la forza può farli tornare al loro sonno! All'attacco!",
        MiniEventVulkanStory_1 = "Il fuoco purificatore è giusto: così dicono i nostri antenati. Ma non sapevano che agli Immortali non importa nulla della morale umana. Questa è semplicemente la loro natura.",
        MiniEventVulkanStory_2 = "Senti il calore salire dalle profondità della terra? C'è una cosa che devi sapere: la fiamma non risparmia nessuno, che sia amico o sconosciuto. E noi ci troviamo proprio sulla sua strada.",
        MiniEventVulkan_Loss_1 = "Devi rimetterti in piedi, Shadow! Non senti la terra tremare?! Il dio è disgustato dal nostro ruzzolare nella polvere...",
        MiniEventVulkan_Win_1 = "Fa caldo come il fuoco dell'inferno qui... Lo spirito del fuoco ringhia soddisfatto nella sua cripta! Davvero un bel combattimento, Shadow! Ci siamo guadagnati un altro giorno!",
