        RANDOM_AREA_HEALTH_DEGENERATION = "Perdi vita nell'area contrassegnata",
        TRANSIENT_BLEEDING = "Fiamme contagiose",
        Tenebris_greetings_1 = "Viaggiatore, ti trovi al confine della realtà. Questa è l'ultima frontiera. Oltre questa linea c'è il vuoto in cui nascono i mondi. Sono stato io a generare le loro luci e le loro tenebre!",
        Tenebris_greetings_2 = "Ombra, il portale alle sue spalle potrebbe essere la nostra unica possibilità di salvezza. Gli Immortali hanno detto che avrebbero distrutto il nostro mondo. Forse hanno intenzione di usare il portale?",
        Tenebris_greetings_3 = "Non sopravvivrai al portale! È un territorio inesplorato, l'oscurità dove vengono creati i mondi. Ma tu non puoi creare, solo distruggere. Il portale ti inghiottirà per sempre!",
        Tenebris_greetings_4 = "È un rischio, ma che altro possiamo fare? Potremmo impedire agli Immortali di attraversare il portale... oppure potremmo causare una grande catastrofe.",
        Tenebris_loses = "Hai paura dell'ignoto che si nasconde nell'oscurità? Ora dovrai affrontarlo da solo! Il mondo finirà in cenere e da essa nascerà di nuovo, seguendo la spirale della storia.",
        Tenebris_wins = "Sciocco ostinato! Vuoi umani sapete risolvere i problemi solo con la forza bruta. Ma l'universo non funziona così. In tutti questi anni, non avete imparato nulla...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "Alzati, fantoccio! Combatti! Non importa se vinci o perdi. Mentre combatti, mi servi!",
        War_AfterWin = "Impostore! Dov'è la tua furia? Come fai a combattere senza? Combatti con me! Iniziamo un'altra danza delle lame! So che in te c'è voglia di lottare!",
        War_Greetings1 = "Che bella giornata! Sento che è in arrivo un combattimento, come una tempesta. Tuoni. L'incredibile furia delle legioni. Tutte offerte sul mio altare!",
        War_Greetings2 = "In lei ribollono rabbia e sete di sangue. Adora combattere senza fine, ma a che scopo? Cosa troverà in cima alla sua montagna di teschi?",
        War_Greetings3 = "Non senti il brivido della battaglia? Fuoco, passione, potenza! Mostrami cosa sei in grado di fare! Dimostra di essere alla mia altezza o muori!",
        ZONE_RAID = "Mondo Sotterraneo: Livello 1",
        ZONE_RAID1 = "Mondo Sotterraneo: Livello 2",
        ZONE_RAID2 = "Mondo Sotterraneo: Livello 3",
        ZONE_RAID3 = "Mondo Sotterraneo: Livello 4",
        ZONE_RAID4 = "Mondo Sotterraneo: Livello 5",
        ZONE_RAID5 = "Mondo Sotterraneo: Livello 6",
        ZONE_RAID6 = "Mondo Sotterraneo: Livello 7",
        ZONE_RAID7 = "Mondo Sotterraneo: Livello 8",
        blackness_enter_blackness_1 = "Progenie. Un grande sacrificio. Una sfera. La mente. Massacro. Io sento. Verserai sangue. Vedo dolore. Vedo il futuro. Ti mostrerò.",
        blackness_greeting_blackness_1 = "Qual è il problema, Shadow? Non ti senti bene?",
        blackness_greeting_lazarus_2 = "Simon? Che bastardo che sei! Perché hai portato delle persone qui? Coglierà il profumo dei vostri pensieri! Andatevene da qui prima che l'Oscurità assapori la vostra mente!",
        blackness_greeting_may_1 = "Lo senti? Niente! Silenzio. Senza il canto degli uccelli, è come se questo posto fosse congelato nell'ambra. Stiamo facendo la cosa giusta? Ho un bruttissimo presentimento...",
        blackness_greeting_saimon_2 = "Questi gentiluomini sono il tuo biglietto per la libertà, mio caro. Quello grosso vestito di nero è in qualche modo connesso all'Obelisco e alle Porte. Lui aiuta te, e tu aiuti lui.",
        blackness_greetingn_saimon_1 = "Non c'è da stupirsi. Da quando un frammento delle antiche Porte si è schiantato qui, la vita in questo luogo è un'anomalia statistica. Tieni gli occhi aperti, dobbiamo trovare Lazarus.",
        blackness_lose_blackness_1 = "Tu resti qui. In eterno. Un solo sangue. Per sempre. Ti leggerò. Mi nutrirò.",
        blackness_win_sensei = "Ci hai mentito, uomo di scienza! Chi abbiamo liberato? A cosa abbiamo condannato questo mondo? Ti rendi conto di quello che hai fatto?!",
        characterMay = "MAY",
        characterMiniEventPriestess = "Sacerdotessa",
        characterSensei = "SENSEI",
        characterThief = "DRITTONE",
        character_Blind = "ERMELLINO",
