        descFatum = "Fatum ha accettato la tua sfida.{br}(Liv. {0})",
        descFungus = "Fungus ha accettato la tua sfida.{br}(Liv. {0})",
        descGatekeeper = "Custode ha accettato la tua sfida.{br}(Liv. {0})",
        descHauntedPrince = "Principe Infestato ha accettato la tua sfida.{br}(Liv. {0})",
        descHoaxen = "Hoaxen ha accettato la tua sfida.{br}(Liv. {0})",
        descInvisible = "Invisibile ha accettato la tua sfida.{br}(Liv. {0})",
        descKarcer = "Karcer ha accettato la tua sfida.{br}(Liv. {0})",
        descLamb = "Agnello ha accettato la tua sfida.{br}(Liv. {0})",
        descMegalith = "Megalite ha accettato la tua sfida.{br}(Liv. {0})",
        descMorgana = "Morgana ha accettato la tua sfida.{br}(Liv. {0})",
        descPowerMode = "<color=#CC0101>MODALITÀ POTENZA</color>{br}(Liv. {0})",
        descPuppeteer = "Il Burattinaio ha accettato la tua sfida.{br}(Liv. {0})",
        descRakshasa = "Rakshasa ha accettato la tua sfida.{br}(Liv. {0})",
        descRavana = "Ravana ha accettato la tua sfida.{br}(Liv. {0})",
        descSaturn = "Saturno ha accettato la tua sfida.{br}(Liv. {0})",
        descShurale = "Shurale ha accettato la tua sfida.{br}(Liv. {0})",
        descSonOfHeaven = "Figlio del Cielo ha accettato la tua sfida.{br}(Liv. {0})",
        descSonOfTheSun = "Figlio del Sole ha accettato la tua sfida.{br}(Liv. {0})",
        descStalker = "Stalker ha accettato la tua sfida.{br}(Liv. {0})",
        descTenebris = "Tenebris ha accettato la tua sfida.{br}(Liv. {0})",
        descVolcano = "Vulcano ha accettato la tua sfida.{br}(Liv. {0})",
        descVortex = "Vortice ha accettato la tua sfida.{br}(Liv. {0})",
        descWhisper = "Whisper ha accettato la tua sfida.{br}(Liv. {0})",
        descWolfWind = "Lupo di Vento ha accettato la tua sfida.{br}(Liv. {0})",
        dlgAmericanEvent22Story_May_1 = "È completamente congelata, Sensei! Non possiamo buttarla fuori con questi venti che infuriano alla porta...",
        dlgAmericanEvent22Story_Puma_1 = "Nei guai, vecchio... Non avrei mai pensato che il passato del mio popolo mi avrebbe perseguitato, ma è così. Quindi sono scappata per proteggerli. Ti prego, ascoltami!",
        dlgAmericanEvent22Story_Puma_2 = "Lo sentite anche voi? Quando ero bambina, uno sciamano mi raccontò di uno spirito il cui ululato sollevava le onde e strappava le foglie. Non avrei mai pensato che quella vecchia fiaba si sarebbe rivelata vera!",
        dlgAmericanEvent22Story_Puma_3 = "Sta venendo da questa parte per perseguitarci con il suo richiamo finché non crolleremo, senza fiato... Solo per divertimento! Non conosco nessun altro posto dove nascondermi...",
        dlgAmericanEvent22Story_Sensei_1 = "Le porte della mia dimora sono aperte a chiunque soffra. Ma è inaspettato vedere un pirata tra queste mura... E dov'è la tua banda di tagliagole, Puma?",
        dlgAmericanEvent22Story_Sensei_2 = "I miti degli sciamani sono allegorie. Le persone hanno inventato le vele per domare il vento, e da allora è servito loro bene. Sei solo una sciocca fiaba e Shadow lo dimostrerà!",
        dlgAmericanEvent22Story_Wind_Wolf_1 = "Io sono il Vento del Lupo! Chiunque mi venga incontro verrà spento come una candela! E prima o poi butterò giù la vostra porta. È solo questione di tempo!",
        dlgAmericanEvent22Story_Wind_Wolf_Lose = "Ululerò finché le foglie non copriranno i detriti. Nessuno troverà mai la strada per arrivare qui! Audace e sciocco... Come puoi combattere contro gli elementi, mortale?",
        dlgAmericanEvent22Story_Wind_Wolf_Win_1 = "Che vergogna... Mi hai privato della mia voce possente! Ma la tua fede, ragazza, mi riporterà in vita... E non tornerò da solo! Perché noi siamo molti!",
        dlgArkhosGreetings = "Ciechi fanatici! Vi ricordate di me e mi nutrite con la vostra fede nel Padre. Un genitore ha il diritto di essere severo. Vi punirò e accetterete la punizione con riconoscenza.",
        dlgArkhosLost = "Chi dovrei venerare in questa mia ultima ora? O Creatore, perché mi hai abbandonato? Mi hai dato il potere di guidarli, ma ho fallito. Di nuovo.",
        dlgArkhosStory1 = "Conosco quelli come lui. Nutrono i loro adepti con la menzogna. Non ascoltare le sue prediche sobillatrici: sono la sua arma.",
        dlgArkhosStory2 = "Sbagli, vecchio. So essere molto duro con i figli più refrattari. Mi pregherai di permetterti di entrare a far parte della famiglia, ma sarò implacabile.",
        dlgArkhosWin = "Pecora nera, non sei degno di un posto al mio fianco. Vattene! Dirò al Creatore che i tuoi uomini hanno fallito di nuovo e lui sfamerà i miei figli.",
        dlgBerstuuk_Announce = "In cerca di conoscenza proibita, un brillante scienziato ha unito scienza e magia nel tentativo di diventare un dio. E la trasformazione è inevitabile! Ora la foresta è il suo laboratorio da incubo e gli umani sono le sue prede. Solo tu puoi fermare questa terrificante metamorfosi! Bandisci la paura e avventurati nel cuore della boscaglia in cerca del falso idolo!",
        dlgBerstuuk_Loose_1 = "Quando sei arrivato alla mia porta, mi hai detto tutto senza parole! Tirerò questa conoscenza come un filo sottile finché non resterà nulla!",
        dlgBerstuuk_Story_1 = "C'è Sly là fuori, che bussa alla porta del fienile... Ne ho viste tante nella foresta di notte, ma questa è nuova! Cosa c'è che non va in lui?",
        dlgBerstuuk_Story_10 = "Non abbastanza. La scienza è imprevedibile: guardami! Gradualmente ho accettato la foresta, ma lei continuava a rifiutare di accettare me. Fino a ora.",
        dlgBerstuuk_Story_2 = "Per coloro che cercano aiuto, il sentiero conduce alla porta giusta. Ma Sly sembra aver smarrito la strada... Vecchio furfante, attento alle mani! Cos'è successo?",
        dlgBerstuuk_Story_3 = "Il furfante cercava aiuto, e l'ha trovato. Andiamo nel bosco, prima che si prenda ciò che le spetta di diritto. Le vite degli uomini!",
        dlgBerstuuk_Story_4 = "\"Uomini\"? Il poveretto è sotto shock: non ha il volto! Cosa l'ha spaventato così tanto da fargli venire un'improvvisa crisi di coscienza?",
        dlgBerstuuk_Story_5 = "Senti gli uccelli cantare? A quest'ora dovrebbero già cinguettare, ma qui non c'è altro che un silenzio di tomba... Cos'altro si nasconde in questa foresta?",
        dlgBerstuuk_Story_6 = "Silenzio di tomba. Silenzio di tomba. La gente ha bisogno di aiuto. Devi a-a-iutare. Aiuta ora!",
        dlgBerstuuk_Story_7 = "Per gli dèi! Normalmente le persone non si trasformano in ramoscelli secchi e muschio, non importa quanto siano spaventate! Cos'è quella roba, e dov'è il vero Sly?!",
        dlgBerstuuk_Story_8 = "È qui in giro da qualche parte. La piccola mente di Sly è stata molto utile. Mi ha parlato di te, Shadow, e del tuo potere speciale. E mi ha folgorato!",
        dlgBerstuuk_Story_9 = "Quindi sei tu colui di cui parlava la creatura? Il bosco verrà e porterà via. E quante di queste vite \"di diritto\" hai preso, pazzo?",
        dlgBerstuuk_Win_1 = "La natura troverà un modo! Il nostro scontro mi ha detto più di quanto tu creda, Shadow. La foresta ricorderà. Mi consumerà per rinascere di nuovo...",
        dlgFatumGreetings = "Il tuo coraggio è pari solo alla tua follia. Sapevo che saresti venuto: sei il mio destino e io il tuo. Riscriverò la tua sorte, una volta per tutte.",
        dlgFatumLost = "Conosco gli esseri umani. Continuano a salire e scendere la stessa spirale. L'ho visto molte volte. Autodistruzione e declino. È il vostro destino, nulla può cambiarlo.",
        dlgFatumStory1 = "Fa' attenzione, eroe. A questa profondità, le leggi universali che conoscevi non sono più valide...",
        dlgFatumStory2 = "Proprio così! Tieni al guinzaglio il ragazzo. So tutto sulle vostre sorti: chi siete e dove andrete. Volete sapere chi morrà, alla fine?",
        dlgFatumWin = "Il tuo destino è segnato. Hai già perso non appena hai varcato la soglia della mia dimora. Avrai coraggio a sufficienza per riscrivere la tua storia?",
        dlgFungusGreetings = "Avete avvelenato la terra, ora i miei funghi stanno morendo. Assorbiranno le vostre menti e diventerete tutti uno solo. Sarà la fine della vostra storia!",
        dlgFungusLost = "I miei fratelli hanno giocato agli dèi. Farsi adorare li ha resi deboli. Ma la distruzione fa parte della vostra natura. Il mondo sarà migliore senza di voi.",
        dlgFungusWin = "Andatevene! Godetevi gli ultimi minuti delle vostre fragili vite!",
        dlgHW21LosePuppeteer_1 = "Non ti affiderei nemmeno un ruolo da comparsa, Shadow. Il palcoscenico non fa per te: non disonorare la mia arte!",
        dlgHW21StoryArkhos_1 = "La piaga sta arrivando nella vostra città, mortali! Inchinatevi di fronte alla potenza del vostro dio! E deliziate i vostri occhi con lo splendore dell'oro, altrimenti...",
        dlgHW21StoryPuppeteer_1 = "Cosa ne sapete voi di arte! Avete rovinato la mia impresa più grande! Tuttavia... il terzo atto è in arrivo. E in esso, l'eroe esala l'ultimo respiro!",
        dlgHW21StorySensei_1 = "Da quando gli dèi del sottosuolo vengono quassù a estorcere denaro alla gente comune? Getta la maschera, ingannatore, prima che prendiamo le armi!",
        dlgHW21StorySensei_2 = "Il teatro dovrebbe ispirare, non inorridire. E tu hai distorto l'essenza stessa dell'arte. Ti fermeremo prima che i tuoi \"attori\" si facciano male.",
        dlgHW21StoryThief_1 = "Aspettate! Sono io... Sly! Non colpitemi! Mi aveva promesso che tutti mi avrebbero temuto... E che nessuno mi avrebbe riconosciuto. Come mi sono tradito?",
        dlgHW21StoryThief_2 = "Il proprietario del teatro itinerante: il Burattinaio. Ha detto che sarebbe stata la sua performance migliore. Dèi tra gli uomini! Per me non significava nulla. Ma i soldi, d'altra parte...",
        dlgHW21WinPuppeteer_1 = "È un fiasco! Avete rovinato la mia splendida trama e rotto le mie maschere! Come farò a mettere in scena un'opera teatrale senza oggetti di scena...",
        dlgHW22EnterArchitect = "Tutta questa tua narrativa fantasy mi ha sfiancato... Ora giocheremo secondo le mie regole. Ed è nel tuo interesse sorprendermi, Shadow...",
        dlgHW22LooseArchitect_1 = "C'era da aspettarselo. Conosco tutte le tue mosse, Shadow. Dopotutto, sono stato io a inventarti. Forse in quel periodo non ero in forma... Ma ora la tua nuova vita ti piacerà.",
        dlgHW22StoryArchitect_1 = "Questo è quello che si definisce un \"cliché\", Burattinaio. Per cosa vengono pagati i drammaturghi? Per il numero di simboli? La figura del folle genio balbettante è diventata stantia, un po' come la figura dell'eroe...",
        dlgHW22StoryArchitect_2 = "Ecco fatto. Riscriveremo il tuo mondo da zero! Contemporaneo, creativo, rilevante! Cosa va di moda tra i giovani oggigiorno? Perché non dici niente, Shadow? Oh, già...",
        dlgHW22StoryPuppeteer_1 = "Si sente bussare, qualcuno bussa inaspettatamente alla tua porta! È un viaggiatore venuto in visita, o qualcosa di più? Intrigante, vero?",
        dlgHW22StoryPuppeteer_2 = "Sapevo che l'avresti detto, vecchio. Cos'altro ci si può aspettare da personaggi inventati? La carta sopporta tutto... Ma il pubblico non lo farà mai!",
        dlgHW22StoryPuppeteer_3 = "Sono solo uno schiavo del palcoscenico, tutto qui. E il mio nuovo capolavoro racconterà di un incontro con il creatore: dei tormenti della predestinazione e del libero arbitrio...",
        dlgHW22StorySensei_1 = "Qualsiasi cosa tu ti sia inventato, Burattinaio, non giocheremo più ai tuoi giochi. L'arte può causare dolore, ma non nel modo in cui la pratichi tu.",
        dlgHW22StorySensei_2 = "Hai recitato troppo e non riesci più a distinguere la realtà dalle tue fantasie, teatrante... Sei pazzo.",
        dlgHW22StorySensei_3 = "Le tue parole sono strane e preoccupanti, straniero... Non so quale follia ti frulli in testa, ma Shadow te la farà passare a suon di botte.",
        dlgHW22WinArchitect_1 = "Forse la creazione non appartiene più al suo creatore e ha preso vita propria... Mi hai sorpreso. Voglio vedere dove andrà a parare la storia.",
        dlgHoaxenGreetings = "Tutta la tua vita è solo un'illusione. Noi siamo i suoi creatori. Vi faremo impazzire senza nemmeno usare la forza. Fuoco, acqua, malattie? Pfui!",
        dlgHoaxenLost = "Dove sei, fratello? Non sento più la tua voce! Restare soli è peggio delle fiamme e delle lame. Andatevene, sciocchi. Il Padre vi attende.",
        dlgHoaxenStory1 = "“Noi”? Ombra, sembra che il nostro nemico sia impazzito. Perdonami, con quale delle tue personalità stiamo parlando? Forse tuo “fratello” potrebbe essere più razionale?",
        dlgHoaxenStory2 = "Ridi di noi, umano? Mio fratello suggerisce di inviare le vostre anime nell'abisso del dolore eterno. Il vostro mondo cederà senza spargere una sola goccia di sangue.",
        dlgHoaxenWin = "Ti avrei ucciso, perché la mia pietà non ha limiti, ma mio fratello è meno tollerante. Se non impazzirai cercando l'uscita, puoi andare liberamente.",
        dlgHunter_enter_hunter_1 = "Tu! Ehi, tuuu! Sei venuto a finire ciò che hai iniziaaato, non è vero? Tu? C'è un potere in te. Mi ppparla. Zitto! O ti cccostringerò a farlo!",
        dlgHunter_greeting_may_1 = "Guardate! C'è qualcosa all'interno del cristallo... Dovrebbe essere così?",
        dlgHunter_greeting_saimon_1 = "Che strano... Mi aspettavo che Lazarus riducesse l'Obelisco in polvere. Temevo una carneficina, ma sembra che siamo rimasti solo io e te. Sono intrigato.",
        dlgHunter_greeting_saimon_2 = "La Sala di Concentrazione. Vedi quel cristallo al centro? È così che l'Obelisco accumula l'energia dell'ombra: il cuore di tenebra, per così dire.",
        dlgHunter_greeting_sensei_1 = "Il silenzio è un cattivo presagio, mio razionale amico. Può parlare più forte della parola più assordante. Hmm... Dove siamo? Che cos'è questo posto bizzarro?",
        dlgHunter_greeting_sensei_2 = "Ne dubito, mia cara... Questo posto sembra diverso dall'ultima volta che l'ho visto. Comincio a credere che il vecchio avesse ragione...",
        dlgHunter_loose_hunter_1 = "Stenditiii. Ti lasceròòò qui per sempreee. Non causare aaaaltro male.",
        dlgHunter_win_hunter_1 = "Fermati, Shadow-umano! Non lasciare che si ddiiiffondaaa! Ssssarai come luuuiiii. Sarai ingaaaannato! Ma hai ancora un'occcasioneee.",
        dlgIE21AnnounceAssistant_1 = "Chi diavolo è questo? Cosa ci fai nel nostro mondo e perché mai dovremmo ascoltarti?",
        dlgIE21AnnounceAssistant_2 = "Ah! Non so da dove tu sia venuto, ma non resterai qui a lungo!",
        dlgIE21AnnounceAssistant_3 = "Ehi, Shadow, questo prepotente si è spinto oltre! Insegniamogli un po' di buone maniere!",
        dlgIE21AnnounceBoss_1 = "Voi, patetici mortali! Inchinatevi di fronte alla mia volontà e alla mia gloria, o vi costringerò io in ginocchio!",
        dlgIE21AnnounceBoss_2 = "Come osi parlarmi in questo modo? Io sono Ravana, conquistatore di tutti e tre i mondi!",
        dlgIE21AnnounceBoss_3 = "Questa è la vostra ultima occasione per inginocchiarvi. Rifiutate e vi taglierò la testa!",
        dlgIE21AnnounceSensei_1 = "Shadow, percepisco una minaccia misteriosa in avvicinamento. Qualcosa di malvagio si è fatto strada nel nostro mondo ancora una volta.",
        dlgIE21Boss_After_Loose = "Se tutte le persone di questo mondo sono così deboli, allora la sua conquista è solo questione di tempo!",
        dlgIE21Boss_After_Win = "STOLTI! Mi ritiro per ora, ma non mi sconfiggerete così facilmente. Ritornerò!",
        dlgIndia22Story_May_1 = "E così avete iniziato a patire la fame... Cosa poteva volere questo demone alla vostra gioiosa celebrazione? Come hanno potuto degli umili contadini attirare un simile predatore?",
        dlgIndia22Story_Rakshasa_1 = "Hai un profumo interessante, umano. Senza dubbio avresti anche un ottimo sapore! Senti il mio stomaco che brontola? Un bel pezzo di carne scelta da accompagnare al mio riso sarebbe molto gradito!",
        dlgIndia22Story_Rakshasa_Lose = "Fortunatamente per te, il nostro scontro mi ha sfiancato. Inoltre, la mia fame è placata... per ora. Mi farò tornare l'appetito e caccerò di nuovo!",
        dlgIndia22Story_Sensei_1 = "Parlami di lui, viaggiatore. Dai tuoi abiti vedo che hai viaggiato a lungo. Quale guaio affligge la tua casa?",
        dlgIndia22Story_Sensei_2 = "Frena il tuo appetito, demone! Non ci sarà alcun invito al festival della vita per chi ruba la vita stessa!",
        dlgIndia22Story_Sensei_Win = "Non è la magia a far fiorire un giardino, è il duro lavoro. E lo dimostrerai tu stesso: aiuta i tuoi vicini a ripristinare la loro fattoria, altrimenti...",
        dlgIndia22Story_Sitaram_1 = "Ho sentito la storia della tua vita. Che gli dèi ti ricompensino secondo i tuoi meriti! Porto cattive notizie: uno spirito maligno è apparso nelle mie terre...",
        dlgIndia22Story_Sitaram_2 = "La malvagità di questo demone è pari solo alla sua fame! Ci stavamo preparando a celebrare il Bohag Bihu quando, all'improvviso, questa... creatura è apparsa e ha divorato tutte le nostre piantine!",
        dlgIndia22Story_Sitaram_3 = "Come Agni mi è testimone, mia signora, mi faccio la stessa domanda! Ora aspettiamo con terrore il tramonto... Venite con me, vi supplico!",
        dlgIndia24_Enter_Puppet_1 = "Hai lo spirito necessario per dirigere il destino? Decidi il mio, umile servitore delle arti quale sono. Solo in combattimento si capisce veramente come stanno le cose. Sii audace, Shadow, all'attacco!",
        dlgIndia24_Story_Dandy_1 = "Aprite, o sfonderò questa maledetta porta! So che siete a casa, vi sento! Darò fuoco a questa baracca se non mi concedete rifugio!",
        dlgIndia24_Story_Loose_Nrityu_1 = "Oh, con quanta ferocia i mortali si aggrappano alla vita. Non sono stata io a scegliere questo compito e non verserò lacrime avvelenate per questo... Perché mi avete fatto questo?",
        dlgIndia24_Story_Loose_Puppet_2 = "Il suo cuore è pieno d'amore. Gli dèi ci creano puri, ma siamo noi a scegliere la nostra strada. Nrityu inizia a capirlo ascoltando la storia della ragazza.",
        dlgIndia24_Story_Loose_Puppet_3 = "Shadow, la tua interpretazione manca di passione e impegno. Ti darò un'altra possibilità. Non recitare, vivilo!",
        dlgIndia24_Story_Puppet_1 = "Toc, toc! Ehi, vecchi amici! La voce del destino è su di noi ed è in arrivo! Il suo orlo rosso brucia come la vita stessa sul finire del giorno!",
        dlgIndia24_Story_Puppet_2 = "È venuta per la tua anima? Ammira una storia antica quanto il mondo stesso: la leggenda di Nrityu, il cui destino era quello di essere una portatrice di morte.",
        dlgIndia24_Story_Puppet_3 = "I fantasmi chiacchierano tutti quanti. Non puoi fidarti di loro. E poi, non spetta a loro raccontare la storia. Ti mostrerò la verità attraverso i suoi occhi. Shadow, tu sei l'unico che può capire.",
        dlgIndia24_Story_Sensei_1 = "Quella voce... Sembra che il nostro vecchio avversario stia tramando di nuovo qualcosa. Chi sarà la vittima stavolta? Vedo un uomo correre verso la pagoda...",
        dlgIndia24_Story_Sensei_2 = "I tuoi abiti sono coperti di sporcizia e fuliggine, straniero. E il tuo tono mi inquieta. Spiega chi sei e che affari hai sulla nostra soglia!",
        dlgIndia24_Story_Win_Faradeya_1 = "Indietro! Non volevo questo! La mia famiglia aveva paura di me e pensavo che questa fosse la mia occasione... Dandy aveva promesso di portarmi con sé, se solo l'avessi aiutato...",
        dlgIndia24_Story_Win_Nrityu_1 = "Ecco! Cadi in un sonno eterno, anche se non te lo meriti. Ma non spetta a me giudicarti, è compito di qualcun altro. Io sono solo la scorta.",
        dlgIndia24_Story_Win_Puppet_4 = "Proprio come te, Shadow. Voglio che tu segua il percorso di Nrityu. Ci ha messo un'eternità per capire quale fosse il suo posto.",
        dlgIndia24_Story_Win_Puppet_6 = "Lo spettacolo continua! Tu, Shadow, sarai la star e i miei attori saranno i tuoi non protagonisti. La storia di Nrityu sarà la nostra più grande produzione!",
        dlgIndia24_Story_Win_Sensei_1 = "Questa storia è profonda, persino per te. Sono sorpreso! Ma qual è la morale, qui? Perché ci stai mostrando questo?",
        dlgMegalithGreetings = "Questa miniera è un luogo sacro. Perché siete qui? Andatevene a incontrare il vostro destino con onore. L'ultima cosa che sentirete sarà la terra che trema sotto i vostri piedi.",
        dlgMegalithLost = "Dannazione! Dovrò attendere di nuovo per migliaia di anni? Ho persino spostato i continenti! Spettava a me purificare la Terra!",
        dlgMegalithWin = "Ho trattato con gentilezza gli esseri umani, un comportamento non comune fra gli Eterni. Ho aiutato spesso la vostra specie. Quindi vattene e dì addio ai tuoi cari!",
        dlgRaidIntro1 = "Stai cercando di correggere il tuo errore? Hai aperto il Portale, ma solo gli Eterni possono eliminare l'Ombra. Non sei uno di noi, quindi sei debole.",
        dlgRaidIntro2 = "Morirai, come tutti gli altri. Nelle mie vene scorre la lava. Coprirà tutta la terra, purificandola per lasciare spazio a nuove forme di vita.",
        dlgRaidStory1 = "Che sotterraneo è questo e cosa stiamo facendo qui sotto?",
        dlgRaidStory2 = "Questa è l'anticamera dei territori degli Eterni. Il loro sonno è durato per millenni, ma l'apertura del Portale minaccia il mondo. Ora si sono ridestati.",
        dlgRaidStory3 = "Splendido, quindi ci aiuteranno a occuparci del Portale!",
        dlgRaidStory4 = "No. Distruggeranno il Portale, ma faranno fare la stessa fine all'intera umanità. Per loro non è che un altro ciclo di distruzione e creazione.",
        dlgShurale_Announce = "Risvegliato da avidi banditi, lo spirito della foresta ora sfoga la sua vendetta sugli innocenti. La creatura cerca lo scrigno dei ricordi rubato, il contenitore della sua antica magia. Solo coloro i cui cuori celano vera tristezza possono placare la furia della creatura. Il prezzo, tuttavia, sarà alto...",
        dlgStoryBtnFight = "COMBATTI",
        dlgStoryBtnMore = "ANCORA",
        dlgVolcanoGreetings = "Io sono stato il primo eterno a destarmi. Molti combattenti verranno a sfidarmi e morire, ma porterò a compimento la mia missione.",
        dlgVolcanoLost = "Basta! Mi arrendo. Ma sappi che hai svegliato mio fratello. Non farti ingannare dal suo aspetto, è rapido e letale!",
        dlgVolcanoStory1 = "Ho visto dei villaggi in rovina e una statua enorme. Qui vivono altri esseri umani?",
        dlgVolcanoStory2 = "Solo dei fanatici. Adorano gli Eterni nella speranza di essere risparmiati. Ma la loro fede li acceca. Se falliremo, scopriranno la verità.",
        dlgVolcanoWin = "Ho detto ai miei fratelli che sta a me decidere il destino del pianeta. Osservate, non credenti, mentre le mie fiamme ricoprono tutte le terre!",
        dlgVortexGreetings = "Acque oscure avvolgeranno la Terra e il Portale dell'Ombra! Il loro segreto andrà perduto nell'abisso. Non resterà nessuno sulla superficie per raccontare ciò che è successo!",
        dlgVortexLost = "Per la prima volta in migliaia di anni un uomo ha vinto. La vostra voglia di vivere è troppo forte! Ma qualsiasi cosa facciate, la vostra fine sarà sempre la stessa: morirete tutti.",
        dlgVortexWin = "Per migliaia di anni ho osservato la decadenza della vostra razza. È stato divertente, penso che vi manterrò in vita.",
        dlgWhisperGreetings = "A quanto pare qualcuno non vede l'ora di scoprire il proprio destino. Dammi la mano e fissa lo specchio!",
        dlgWhisperLost = "Sei ancora vivo? Allora non sei ancora in mio potere! Fatum divinerà il tuo destino e poi tornerò al mio mondo... dopo averti avvertito di procedere con cautela con gli specchi!",
        dlgWhisperWin = "Ti porterò con me nel regno di cenere, spiriti e notte eterna! Fidati di me, guardami negli occhi e non distogliere lo sguardo.",
        dlg_American_25_Loose_1 = "Non sai chi stai proteggendo, Shadow. Non ti ringrazieranno. Sogghigneranno solo alle tue spalle. Selvaggi... e il mostro sarei io?",
        dlg_American_25_Story_1 = "May se n'è andata. Presa da qualcosa di a malapena umano. Eppure non ci sono state urla, nessun segno di lotta... come se se ne fosse andata di sua spontanea volontà.",
        dlg_American_25_Story_2 = "Non siamo soli in questo. Anche altri come May — giovani, forti — sono svaniti. Sentiva che stava per succedere... e si è riempita le tasche di polvere da sparo.",
        dlg_American_25_Story_3 = "La sua pista è chiara. Dobbiamo trovarla prima che arrivino le piogge, o la perderemo per sempre. Vieni, Shadow!",
        dlg_American_25_Story_4 = "Ti ho fiutato nel momento in cui hai messo piede su questa terra maledetta. Perché sei venuto? Per calpestare il mio dolore? Non hai onore, proprio come non ne avevano loro.",
        dlg_American_25_Story_5 = "Sapevo che saresti apparso, sciamano. Restituisci i bambini ai loro cari, e la nostra amica a noi. Poi vai a marcire sulla tua montagna di cenere.",
        dlg_American_25_Story_6 = "Cenere alla cenere. E cenere ritornerai, mortale...",
        dlg_American_25_Win_1 = "Aspetta! Sono andata con lui di mia spontanea volontà. Il suo aspetto è bestiale, sì... ma il suo cuore è umano. E soffre... Hanno rapito suo figlio!",
        dlg_CHN_NY25_Announce = "Immergiti nella storia di un eroe di tempi antichi: districa la verità dalla leggenda e contribuisci a forgiare un nuovo mito! Affronta un misterioso culto che usa il nome di un grande eroe come mantello per le proprie atrocità! Torna nel luogo in cui tutto è iniziato e aiuta un furfante fuggiasco a scoprire il suo vero eroismo!",
        dlg_CHN_NY25_Loose_1 = "No, dobbiamo continuare a combattere! Nessuno crederebbe che un semplice contadino possa sconfiggere un culto sinistro così facilmente. Devi dare il massimo!",
        dlg_CHN_NY25_Story_1 = "Il Culto del Sole ha la tradizione di visitare il luogo di nascita del suo grande eroe una volta all'anno. Ma ogni volta si rivela un disastro...",
        dlg_CHN_NY25_Story_2 = "Era nato umano? Che curiosità. Mi sembra che queste persone non stiano portando doni al villaggio...",
        dlg_CHN_NY25_Story_3 = "Non lasciano nulla di intatto! Rubano il bestiame agli abitanti del villaggio, devastano i raccolti in preda a un delirio da ubriachi, frantumano finestre e attaccano briga!",
        dlg_CHN_NY25_Story_4 = "Ma perché gli abitanti del villaggio non si ribellano? Questa è la loro terra e la loro leggenda!",
        dlg_CHN_NY25_Story_5 = "Sono a pezzi. L'eroe che ha dato loro speranza se n'è andato e i cultisti commettono atrocità in suo nome. Dobbiamo ridare loro speranza!",
        dlg_CHN_NY25_Story_6 = "Di' che sei venuto a controllare che sia tutto pronto per la \"festa\". E noi combatteremo! I cittadini vedranno che il culto può essere affrontato!",
        dlg_CHN_NY25_Story_7 = "Molto bene, come vuoi... Fammi entrare nella parte. \"Ehi, ragazzo, come osi indossare le vesti del nostro eroe! Vattene, abbiamo un banchetto da preparare!\"",
        dlg_CHN_NY25_Story_8 = "Non sarò un eroe leggendario, ma il suo spirito vive in questa terra! Mi guiderà nella mia ora più buia e mi infonderà coraggio! All'attacco!",
        dlg_CHN_NY25_Win_1 = "Non mi aspettavo una simile velocità da un semplice uomo... Hai quasi sconfitto il nostro campione! Dobbiamo fare di te un esempio, per evitare che altri si facciano strane idee...",
        dlg_NY25_Loose_1 = "I tuoi ricordi sono vividi e il dolore parla più forte della ragione. Resterai qui con me. Riposa un po'... il sonno arriverà presto.",
        dlg_NY25_Story_1 = "Benvenuti! Questa capanna un tempo apparteneva alla mia famiglia. Quanti ricordi... Restate quanto volete. Qui c'è tutto ciò che vi serve per riposare.",
        dlg_NY25_Story_2 = "Ma ci hai messo in pericolo così tante volte, e ora ci offri un soggiorno nella tua casa di famiglia? È una specie di trucco?",
        dlg_NY25_Story_3 = "È solo la voce della coscienza che parla! Mi sono reso conto di aver approfittato della gentilezza altrui per troppo tempo. Ma ora desidero fare del bene.",
        dlg_NY25_Story_4 = "Non siamo soli... C'è gente che si raduna davanti al rifugio. Cosa vogliono a quest'ora tarda? Ci stanno chiamando per farci uscire.",
        dlg_NY25_Story_5 = "Non fatelo! I fantasmi vi distruggeranno! Non sono altro che spettri di ricordi dolorosi. Lo spirito della foresta è venuto per il suo scrigno! Recuperiamolo!",
        dlg_NY25_Story_6 = "Uno scrigno? Ecco perché la gente scompare nei boschi! Perché ci hai traditi, Sly? Ti avremmo aiutato comunque in questa nobile ricerca!",
        dlg_NY25_Story_7 = "Non capite. Se sento la sua voce, perderò il controllo... e sparirò anch'io. Finché porterò un pezzo di lei con me.",
        dlg_NY25_Story_8 = "Apri la porta, sto congelando qua fuori, papà. La casa è fredda e io non sono dentro. Ti mostrerò un posto dove potremo stare di nuovo insieme.",
        dlg_NY25_Story_9 = "Fermo! Non andare nella foresta, ti perderai! Non so di chi sia la voce che senti, ma non è di certo umana!",
        dlg_NY25_Win_1 = "Svegliati, Sly! Restituisci lo scrigno allo spirito mentre è debole. Fagli vedere che l'umanità può superare la propria avidità.",
        saturn_enter_saturn_1 = "Ti ricaccerò in gola quelle tue parole. E i tuoi amici guarderanno. L'unico modo per uscire dalla mia prigione è tramite il patibolo. Chi vuole essere il primo?",
        saturn_greeting_saimon_1 = "Il nostro sovrano, il Patriarca, ha studiato il portale per anni. Poi, un giorno, si è chiuso in se stesso. Più tardi, ha eretto l'Obelisco, e ha fatto qualcosa al nostro mondo...",
        saturn_greeting_saimon_2 = "Shadow è simile all'Obelisco a livello molecolare. C'è qualcuno che ci aiuterà a usarlo contro il Patriarca. Ecco perché siamo qui, nella camera di Saturn...",
        saturn_greeting_saimon_3 = "Mille scuse, mia signora. Tuttavia, dobbiamo liberare Lazarus. Vi prego di mostrarci la sua cella, e non vi disturberemo oltre.",
        saturn_greeting_saturn_1 = "Andate lontano, bambini? Siete venuti nella mia prigione di vostra spontanea volontà! Mi chiedo: è coraggio o stupidità? Tu, quello allampanato: rispondimi!",
        saturn_greetingn_May_1 = "Ma cosa c'entra con noi?",
        saturn_lose_saturn_1 = "Questo ti basta. Se Lazarus si associa a scarti come voi, non c'è alcun pericolo per il Patriarca. Fuori di qui, mocciosi! Non siete sulla mia lista.",
        saturn_win_saturn_1 = "Non troverete mai Lazarus. Quel mascalzone è fuggito dalla mia prigione ed è scappato verso le paludi. Volete perire anche voi? Allora andategli dietro!",
        summerfest25_story2_1 = "Bene, bene... Eri così ansioso di trovarmi, ho pensato di farti un favore. D'altronde, tutti stavano aspettando questo momento.",
        summerfest25_story2_2 = "\"Tutti\"? Smettila di recitare. Sappiamo esattamente chi sei e come usi gli altri solo per crogiolarti nella loro miseria.",
        summerfest25_story2_3 = "Solo un piccolo cameo e boom, sono in tendenza! Sinceramente, non mi aspettavo di essere così popolare.",
        summerfest25_story2_4 = "La tua arguzia non ti salverà. Pagherai per i miei occhi e per tutto il male che hai fatto. Il tuo perverso gioco di fare il dio finisce qui!",
        summerfest25_story2_5 = "Sul serio, Ermine? Quel tipo di discorsi è passato di moda con i telefoni a conchiglia. Siamo nel 2026, cerca di stare al passo coi tempi.",
        summerfest25_story2_6 = "Qualunque cosa l'Architetto stia progettando... c'è un'oscurità attorno a lui. Una forza così malevola che è quasi tangibile.",
        summerfest25_story2_7 = "Con ogni parola che pronuncia, mi ritrovo a credere sempre di più alla storia di Ermine. L'Architetto è pericoloso e deve essere fermato.",
        summerfest25_story2_defeat_1 = "Oh no... che delusione! Il pubblico si aspettava di più. Sembra che dovrò semplicemente alzare la posta in gioco la prossima volta.",
        summerfest25_story2_win_1 = "Perché il mondo è così crudele? Perché dobbiamo soffrire? Perché ho dovuto accecarmi? Rispondimi, Architetto: perché fa così male vivere!?",
        tutorial_ascention_intro_title = "BURATTINAIO",
    },
    kor = {
        ActScreenRaid = "지하세계",
        BLACKNESS = "암흑",
        BLACKNESS_TITLE = "암흑",
        BODY_BERSTUUK = "베르스투크의 형상",
        BOSS_BISON_21 = "아단티",
        BOSS_BISON_Title = "아단티",
        BOSS_LAMB = "어린 양",
        BOSS_RAVANA = "라바나",
        BOSS_RAVANA_Title = "라바나",
        CharacterIndia24Nrityu = "느리티유",
        DEMON_RAID = "건틀릿",
        DEMON_RAID_Title = "건틀릿",
        EARTHQUAKE = "주기적 지진",
        EnterPortal_ActScreen = "포탈",
        FRAGILITY = "나타난 지역에서 취약성 증가",
        Gatekeeper_greetings_1 = "이상한 공기? 이상한 공기! 이-상-한-공-기!",
        Gatekeeper_greetings_2 = "달가워하지 않아, 달가워하지 않아, 달가워하지 않아! 우리가 한 짓, 우리가 한 짓, 우리가 한 짓!",
        Gatekeeper_greetings_Assistant_1 = "섀도우! 드디어 깨어났구나!",
        Gatekeeper_greetings_Assistant_2 = "여긴 너무 추워! 벌써 손가락 감각이 없어… 우리 어디 있는 거지? 공기가 너무 이상해.",
        Gatekeeper_greetings_Assistant_3 = "하지만 왜 우리 말을 이해하고 있다는 기분이 드는 걸까요?",
        Gatekeeper_greetings_Sensei = "물러서라, 메이! 저 녀석이 뭘 원하는지 모른다! 불멸자들의 세계가 내 생각보다 더 크게 흔들렸어. 우리가 한 짓 때문에 그들은 우리가 여기 있는 걸 달가워하지 않아.",
        Gatekeeper_greetings_Sensei_2 = "진정해라, 갑작스러운 움직임은 삼가고. 이 피조물은 그다지 지능이 높아 보이지 않는구나.",
        Gatekeeper_greetings_Sensei_3 = "그건 지금 중요하지 않다. 포탈을 통과한 건 우리의 선택이었고, 그에 대한 책임을 져야 해. 녀석은 싸움을 원한다. 선택의 여지가 없군, 섀도우.",
        Gatekeeper_lost_Saimon = "포탈에 더 많은 기대를 걸었는데… 이 여정으로 자네 체력이 고갈되었고 분자 결합이 약해진 것 같군. 흥미로워… 몇 가지 테스트를 더 해봐야겠어.",
        Gatekeeper_win_Saimon = "수 세기 동안 이 낡은 포탈은 우리의 이해를 넘어서는 힘이 존재한다는 걸 상기시켜 줬지. 그리고 자네가 나타난 거야…",
        HARD_GROUND = "땅에 쓰러질 때 피해를 받습니다.",
        HEAD_BERSTUUK = "베르스투크의 마스크",
        HEALTH_DROPS = "시간에 따라 체력 감소",
        HOT_GROUND = "뜨거운 지면",
        HW20Arkhos1 = "연약한 자와 눈먼 자 모두 신앙의 불꽃에 휩싸이게 될 거라는 사실은 예지력 없이도 알 수 있지. 모두가 이 진실을 나처럼 선명하게 볼 수 있도록 검은 양초를 가져왔소!",
        HW20Fatum1 = "세계 간의 경계가 옅어지고 있어… 오늘은 예언을 위한 최고의 밤이야! 대기에 마법의 기운이 윙윙거리고, 내 손안에 운명의 실타래가 감겨 있지!",
        HW20Fatum2 = "나에게 점술은 게임과 같아. 필멸자들의 운명을 내 맘대로 주무를 수 있으니까. 하지만 내 친구들, 너희들은 완전히 다른 문제야. 자, 어서 앉아!",
        HW20Fatum3 = "당신은 증오에 눈이 멀었어. 시작하자. 말하지 말고, 들어. 어떤 형상이 보여… 밤처럼 까맣고… 깃털과 재… 내 손을 잡고…",
        HW20Fatum4 = "어떻게… 어떻게 여기에 온 거야? 이 세계로 통하는 길은 네게 닫혀있을 텐데!",
        HW20Megalith1 = "네가 점술과 가장무도회를 이야기하길래, 마법의 거울을 가져왔어. 천 년 만에 처음으로 내 모습을 볼 수 있게 되었지. 이 가면을 쓰니 정말 늙어 보이는군!",
        HW20Whisper1 = "예언 놀이를 하고 있었니, 여동생아? 필멸자의 운명을 짊어지고서? 그런 장난감은 항상 내 차지였는데 말이야!",
        HW20Whisper2 = "닫혀있었지! 하지만 네가 불렀고, 이 경이로운 거울을 통해 내가 온 거야. 이건 내가 가져가마. 꼭 날 찾아오렴, 진짜 운명을 들려줄 테니!",
        Hunger_AfterLoss = "네가선택 된자라고 하니, 마지막으 로한번의 기회를 더주겠다. 나와함께 연회를즐기자. 그러지 않으면네 뼈또한가루가 된다른자 들과같은 운명을 맞으리라.",
        Hunger_AfterWin = "창조주여, 내게 자양물을 보내 주었구나. 하지만 이걸로는 부족하다. 내 굶주림은 영원하니, 날 구원해 다오...",
        Hunger_Greetings1 = "아주먼길 을돌아여 기까지 왔구나. 왜지? 감사할 줄모르는 필멸자들을 구하려고? 그것들은네게 아무런관 심도없다! 네외로움과 굶주림, 그리고... 공포가 아주 잘 느껴지는구나.",
        Hunger_Greetings2 = "섀도우, 속지마라! 그는 약해보일뿐이다. 넌그의 친구가아니야. 그저 먹잇감일뿐. 더 가까이 다가가면 조각조각 찢어발길것이다!",
        Hunger_Greetings3 = "내 형제들이 보이나? 그들은지 금목이마 르다. 그리고그 들이느끼는갈 증은조금 다른종류의 것이다. 여흥을갈 망하고있지. 하지만내굶주림과 비교하면 아무것도 아니야!",
        INVERTED_JOYSTICK = "반대 움직임",
        MERCENARY_RAID = "용병{br}부대",
        MERCENARY_RAID_Title = "용병 부대",
        MiniEventAnnounce = "아주 먼 옛날부터 지구 깊숙한 곳에 이교도가 거주하며, 지하 세계 신들의 조심스러운 잠을 지켜보고 그들이 깨어나지 않도록 막아왔습니다. 하지만 그 대가는 마지막 피 한 방울까지 흘려야 하는 잔혹한 의식의 전투입니다.",
        MiniEventHungerFight_Enter_1 = "여기 지하에서는 모든 것이 달라. 우리는 살기 위해 싸우고, 밥버러지는 생명 그 자체지! 네 사람들에게서, 아니 내 사람들에게서 이 큰 기쁨을 앗아가지 말라고!",
        MiniEventHungerStory_1 = "사람들은 집에 우환이 닥쳐야만 정령들의 변덕에 신경을 쓰지. 농작물은 시들고, 아이들은 굶주리고… 그런데 지금 그들의 신앙은 어디로 간 거지?",
        MiniEventHungerStory_2 = "굶주림에는 형체가 있어. 먹어 치우려는 그 갈증은 끔찍할 정도지. 하지만 그건 카르서의 역할이고, 자네와 내 역할은 그가 수백 년의 깊은 잠에서 깨어나지 못하게 막는 거라네.",
        MiniEventHunger_Loss_1 = "접시에 음식을 남기지 말라고 어머니께 배우지 못했나 보군? 다 티가 나지. 네 눈에 굶주림이 서려 있잖아! 아니면… 대체 뭐가 문제인 거냐?",
        MiniEventHunger_Win_1 = "그래, 타격이 아주 좋군, 섀도우… 든든한 식사로 자네의 승리를 축하하세! 내가 쏘지!",
        MiniEventStory_1 = "섀도우, 자네가 강인하고 흔들림 없는 정신을 가졌다는 걸 알겠네. 자네의 업적에 대한 전설 널리 퍼져있지. 또 다른 전설의 일부가 되어 보지 않겠나?",
        MiniEventStory_2 = "지하 세계의 정령들은 제멋대로라네. 우리는 그들의 성미를 달래기 위해 의식을 치르지. 바로 의식의 전투 말일세! 자네가 참여해 준다면 우리에겐 큰 영광이 될 거야.",
        MiniEventStory_EnterBattle = "이런 신비로운 구경거리 치고는 네가 너무 병약한 거 아니냐? 정말 이 녀석을 선택한 거야? 이게 그 전설적인 사내라고? 오, 정령들이 분노하겠군…",
        MiniEventStory_Loss_1 = "그래, 뭐… 정령들에게도 유머 감각이라는 게 있어서, 우리에게 분노를 쏟아내기보다는 투기장에서 벌어지는 우리의 어설픈 짓을 보고 그저 웃어넘겨 주기를 바랄 뿐이네…",
        MiniEventStory_Win_1 = "흠… 우연히 이 투기장에 오게 되는 자는 아무도 없다네. 자네는 진정 전설 속의 사내가 맞군, 섀도우.",
        MiniEventVulkanFight_Enter_1 = "저 마녀가 아무 이유 없이 널 겁주고 있구나. 사실은 훨씬 더 단순해. 강철은 불 속에서 단련되는 법이지! 신들은 오직 힘만을 이해할 뿐이야. 오직 힘만이 그들을 다시 잠재울 수 있어! 공격!",
        MiniEventVulkanStory_1 = "정화의 불꽃은 정의롭다… 우리 조상들은 그렇게 말했지. 하지만 그들은 불멸자들이 인간의 도덕 따위엔 신경 쓰지 않는다는 사실을 몰랐어. 그저 그들의 본성일 뿐이지.",
        MiniEventVulkanStory_2 = "땅 밑에서 열기가 피어오르는 게 느껴지나? 네가 알아야 할 것이 하나 있어. 불꽃은 친구든 이방인이든 아무도 살려두지 않는다는 사실. 그리고 우리는 지금 정확히 그 길목에 서 있지.",
        MiniEventVulkan_Loss_1 = "다시 일어나야 해, 섀도우! 땅이 흔들리는 게 느껴지지 않아?! 신은 우리가 먼지투성이가 되어 허우적대는 꼴에 넌더리를 내고 있어…",
        MiniEventVulkan_Win_1 = "여긴 지옥불처럼 뜨겁군… 불의 정령이 자기 금고 안에서 만족스러운 듯 으르렁거리고 있어! 정말 훌륭한 전투였네, 섀도우! 우리가 또 하루를 벌었어!",
