        Tenebris_greetings_1 = "Você está no limiar da realidade, viajante. Está é a fronteira final. A partir desta linha, reside o vazio onde os mundos nascem. E fui eu quem forjou sua luz e escuridão!",
        Tenebris_greetings_2 = "Sombra, o portal atrás dele pode ser nossa chance de salvação. Os Imortais disseram que destruiriam nosso mundo. Talvez com a ajuda do portal.",
        Tenebris_greetings_3 = "Você não sobreviverá ao portal! São terras desconhecidas! A escuridão na qual os mundos podem ser criados. Mas você não pode criar, somente destruir. O portal vai lhe engolir inteiro!",
        Tenebris_greetings_4 = "É um risco, mas não temos outra opção. Talvez a gente consiga deter os Imortais ao entrar no portal. Mas também podemos causar uma grande catástrofe.",
        Tenebris_loses = "Você tem medo do desconhecido que se esgueira pela escuridão? Agora você será deixado para enfrentá-lo sozinho! O mundo se transforma em pó e renasce como novo. Seguindo a espiral.",
        Tenebris_wins = "Seu tolo teimoso! Vocês, humanos, só conseguem resolver seus problemas com a força bruta. Mas o Universo não funciona assim. Todos esses anos e você não aprendeu nada...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "Levante, marionete! E lute! Não importa se vai ganhar ou perder. Quando você luta, serve a mim!",
        War_AfterWin = "Impostor! Onde está sua fúria? Como é possível lutar sem isso? Lute comigo! Vamos começar outra dança de lâminas! Eu sei há guerra dentro de você!",
        War_Greetings1 = "Que dia lindo! Sinto a batalha se aproximar, como uma tempestade. Trovão. A incontável fúria de legiões marchando. Todos presentes para meu altar!",
        War_Greetings2 = "A fúria e a sede por sangue fervem dentro dela, que se deleita com a batalha infinita, mas pelo quê? O que há no topo daquela montanha de crânios?",
        War_Greetings3 = "Será que você desconhece a emoção de uma batalha sangrenta? Fogo, paixão, poder! Mostre o que sabe fazer! Venha me entreter em combate ou morra!",
        ZONE_RAID = "Submundo: Nível 1",
        ZONE_RAID1 = "Submundo: Nível 2",
        ZONE_RAID2 = "Submundo: Nível 3",
        ZONE_RAID3 = "Submundo: Nível 4",
        ZONE_RAID4 = "Submundo: Nível 5",
        ZONE_RAID5 = "Submundo: Nível 6",
        ZONE_RAID6 = "Submundo: Nível 7",
        ZONE_RAID7 = "Submundo: Nível 8",
        blackness_enter_blackness_1 = "Descendência. Um grande sacrifício. Uma esfera. A mente. Carnificina. Eu sinto. Você vai derramar sangue. Vejo dor. Vejo o futuro. Eu lhe mostrarei.",
        blackness_greeting_blackness_1 = "Qual é o problema, Shadow? Você está passando mal?",
        blackness_greeting_lazarus_2 = "Simon? Que canalha você é! Por que trouxe pessoas para cá? Ela vai sentir o cheiro dos seus pensamentos! Saiam daqui antes que a Escuridão experimente a sua mente!",
        blackness_greeting_may_1 = "Você ouve isso? Nada! Silêncio. Sem o canto dos pássaros, é como se este lugar estivesse congelado em âmbar. Estamos fazendo a coisa certa? Estou com um pressentimento muito ruim…",
        blackness_greeting_saimon_2 = "Estes nobres cavalheiros são o seu passaporte para a liberdade, meu caro. O grandalhão de preto está, de alguma forma, conectado ao Obelisco e aos Portões. Ele ajuda você, e você ajuda ele.",
        blackness_greetingn_saimon_1 = "Não é de se admirar. Desde que um fragmento dos antigos Portões caiu aqui, a vida neste lugar tem sido uma anomalia estatística. Fiquem de olhos abertos — precisamos encontrar Lazarus.",
        blackness_lose_blackness_1 = "Você fica aqui. Eternamente. Um só sangue. Para sempre. Eu lerei você. Eu me alimentarei.",
        blackness_win_sensei = "Você mentiu para nós, homem da ciência! Quem nós libertamos? A que nós condenamos este mundo? Você tem noção do que fez?!",
        characterMay = "MAY",
