        RANDOM_AREA_HEALTH_DEGENERATION = "Pierzi viaţă în zona indicată.",
        TRANSIENT_BLEEDING = "Efect de arsură trecător.",
        Tenebris_greetings_1 = "Ești la marginea realităţii, călătorule. Aceasta este ultima frontieră. Dincolo de această linie se află vidul din care se nasc lumile. Și eu am fost cel care le-a făurit lumina și întunericul!",
        Tenebris_greetings_2 = "Shadow, portalul din spatele lui ar putea fi șansa noastră de salvare. Eternii au spus că ne vor distruge lumea. Poate cu ajutorul lui?",
        Tenebris_greetings_3 = "Nu vei supravieţui portalului! Este terra incognita. Întunericul în care pot fi create lumi. Dar tu nu poţi crea, doar distruge. Portalul te va înghiţi cu totul!",
        Tenebris_greetings_4 = "E un risc, dar avem altă variantă? Am putea opri Eternii intrând în portal. Dar am putea, de asemenea, să provocăm o mare catastrofă.",
        Tenebris_loses = "Te înspăimântă necunoscutul care pândește din întuneric? Acum vei fi lăsat să-l înfrunţi de unul singur! Lumea se preface în pulbere și renaște din nou. Urmând spirala.",
        Tenebris_wins = "Nesăbuit încăpăţânat! Voi, oamenii, puteţi rezolva problemele doar prin forţă brută. Dar universul nu funcţionează așa. După toţi acești ani, nu ai învăţat nimic...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "Ridică-te, marionetă! Și luptă! Nu contează dacă învingi sau pierzi. Când lupţi, mă slujești pe mine!",
        War_AfterWin = "Impostorule! Unde îţi e furia? Cum poţi lupta fără ea? Luptă cu mine! Să începem un nou dans al tăișurilor! Știu că războiul trăiește în tine!",
        War_Greetings1 = "Ce zi minunată! Simt cum se apropie o bătălie, asemeni unei furtuni. Tunetul. Furia de nedescris a legiunilor ţinând pasul. Toate acestea sunt ofrande pe altarul meu!",
        War_Greetings2 = "Furia și setea de sânge fierb în ea. Se delectează în bătălii nesfârșite, dar pentru ce? Ce va găsi în vârful muntelui ei de cranii?",
        War_Greetings3 = "E fiorul unei bătălii sângeroase atât de străin ţie? Foc, pasiune, putere furtunoasă! Arată-mi ce poţi! Distrează-mă într-o luptă corp la corp sau mori!",
        ZONE_RAID = "Lumea de Dincolo: Nivelul 1",
        ZONE_RAID1 = "Lumea de Dincolo: Nivelul 2",
        ZONE_RAID2 = "Lumea de Dincolo: Nivelul 3",
        ZONE_RAID3 = "Lumea de Dincolo: Nivelul 4",
        ZONE_RAID4 = "Lumea de Dincolo: Nivelul 5",
        ZONE_RAID5 = "Lumea de Dincolo: Nivelul 6",
        ZONE_RAID6 = "Lumea de Dincolo: Nivelul 7",
        ZONE_RAID7 = "Lumea de Dincolo: Nivelul 8",
        blackness_enter_blackness_1 = "Urmași. Un mare sacrificiu. O sferă. Mintea. Măcel. Simt. Vei vărsa sânge. Văd durere. Văd viitorul. Îți voi arăta.",
        blackness_greeting_blackness_1 = "Ce s-a întâmplat, Shadow? Îți este rău?",
        blackness_greeting_lazarus_2 = "Simon? Ce ticălos ești! De ce ai adus oameni aici? Le va simți mirosul gândurilor! Plecați de aici înainte ca Întunecimea să vă guste mintea!",
        blackness_greeting_may_1 = "Auzi asta? Nimic! Tăcere. Fără cântecul păsărilor, e ca și cum locul ăsta ar fi încremenit în chihlimbar. Oare facem ce trebuie? Am o presimțire foarte rea…",
        blackness_greeting_saimon_2 = "Acești domni distinși sunt biletul tău spre libertate, dragul meu. Cel mare în negru are cumva legătură cu Obeliscul și cu Porțile. El te ajută pe tine, iar tu îl ajuți pe el.",
        blackness_greetingn_saimon_1 = "Nici nu-i de mirare. De când un fragment din vechile Porți s-a prăbușit aici, viața în acest loc a fost o anomalie statistică. Fiți cu ochii în patru — trebuie să-l găsim pe Lazarus.",
        blackness_lose_blackness_1 = "Tu rămâi aici. Etern. Un singur sânge. Pentru totdeauna. Te voi citi. Mă voi hrăni.",
        blackness_win_sensei = "Ne-ai mințit, om al științei! Pe cine am eliberat? La ce am condamnat această lume? Îți dai seama ce ai făcut?!",
        characterMay = "MAY",
        characterMiniEventPriestess = "Preoteasa",
