        Gatekeeper_greetings_1 = "Странный воздух? Странный воздух! Стррранный воздух!",
        Gatekeeper_greetings_2 = "Не рады, не рады, не рады! Натворили, натворили, натворили!",
        Gatekeeper_greetings_Assistant_1 = "Тень! Ты наконец-то очнулся!",
        Gatekeeper_greetings_Assistant_2 = "Как же здесь холодно! Я уже пальцев не чувствую… Где мы? Воздух какой-то странный.",
        Gatekeeper_greetings_Assistant_3 = "Но почему мне кажется, что оно нас понимает?",
        Gatekeeper_greetings_Sensei = "Назад, Мэй! Мы не знаем, чего оно хочет! Мир Бессмертных потрясло сильнее, чем я думал. После того, что мы натворили, они не рады нашему присутствию.",
        Gatekeeper_greetings_Sensei_2 = "Спокойно, не делай резких движений. Кажется, это существо не блещет умом.",
        Gatekeeper_greetings_Sensei_3 = "Сейчас это неважно. Пройти через портал было нашим выбором, и нам за него отвечать. Оно жаждет боя — у нас нет выбора, Тень.",
        Gatekeeper_lost_Saimon = "Я ожидал большего от портала… Похоже, путешествие истощило твои силы, а молекулярные связи ослабли. Интересно… надо провести ещё несколько тестов.",
        Gatekeeper_win_Saimon = "Веками этот хлипкий портал напоминал нам о существовании сил, неподвластных нашему пониманию. А потом появился ты…",
        HARD_GROUND = "При падении на землю вы получите урон.",
        HEAD_BERSTUUK = "Маска Берстуука",
        HEALTH_DROPS = "Убывающее здоровье.",
        HOT_GROUND = "Раскаленная земля.",
        HW20Arkhos1 = "Мне не нужно предвидение, чтобы знать: огонь веры поглотит и слабых, и слепых. Я принёс чёрные свечи, чтобы каждый узрел эту истину так же ясно, как я!",
        HW20Fatum1 = "Границы между мирами истончаются — это лучшая ночь для пророчеств! Воздух гудит от магии, а в моих руках сплетаются сами нити судьбы!",
        HW20Fatum2 = "Гадание для меня — лишь игра, я могу распоряжаться судьбами смертных как мне угодно. Но вы, друзья мои, — совсем другое дело. Пожалуйста, присаживайтесь!",
        HW20Fatum3 = "Твоя ненависть ослепила тебя. Давайте начнём. Ни слова, просто слушайте. Я вижу фигуру… чёрную как ночь… перья и пепел… она берёт меня за руку…",
        HW20Fatum4 = "Как… как ты здесь оказалась? Путь в этот мир был закрыт для тебя!",
        HW20Megalith1 = "Вы говорили о гаданиях и маскараде, поэтому я принёс волшебное зеркало. Впервые за тысячу лет я вижу своё отражение. В этой маске я выгляжу древним!",
        HW20Whisper1 = "Заигралась в пророчества, сестрёнка? Решила распоряжаться судьбами смертных? Такие игрушки всегда принадлежали только мне!",
        HW20Whisper2 = "Закрыт, это верно! Но ты позвала, и через это чудесное зеркало пришла я. Я забираю его с собой. Заглядывай в гости, если хочешь услышать настоящее пророчество!",
        Hunger_AfterLoss = "Ты ведь избррранный! Я даю тебе последний шанс остаться со мной и пиррровать. Иначе твои кости будут валяться в пыли среди остальных.",
        Hunger_AfterWin = "Создатель, ты прислал мне пищу, но я не могу насытиться. Мой голод длится целую вечность, подари мне избавление...",
        Hunger_Greetings1 = "Ты так долго шел сюда. Зачем? Чтобы спасти неблагодарных смеррртных? Им нет дела до тебя! А я чувствую твое одиночество, голод и стрррах.",
        Hunger_Greetings2 = "Не обманывайся, Тень! Он только кажется слабым. Ты для него не друг, а добыча. Он разорвет тебя на куски, если приблизишься хоть на шаг!",
        Hunger_Greetings3 = "Видишь моих братьев? Их терррзает жажда, но иного рода. Они хотят зрррелищ. Но их голод — лишь жалкое подобие моего!",
        INVERTED_JOYSTICK = "Инвертированное управление.",
        MERCENARY_RAID = "ОТРЯД{br}НАЕМНИКОВ",
        MERCENARY_RAID_Title = "Отряд наемников",
        MiniEventAnnounce = "С незапамятных времён в недрах земли обитает культ, охраняющий чуткий сон богов подземного мира и не позволяющий им проснуться. Но плата за это — жестокая ритуальная битва до последней капли крови.",
        MiniEventHungerFight_Enter_1 = "Здесь, под землёй, всё иначе. Мы сражаемся за жизнь, а еда — это жизнь! Не лишай свой народ — и мой — этой великой радости!",
        MiniEventHungerStory_1 = "Людям есть дело до прихотей духов лишь тогда, когда в их дома приходит беда. Их урожай вянет, дети голодают… И где теперь их вера?",
        MiniEventHungerStory_2 = "У голода есть облик. Его жажда поглощения ужасна. Но такова роль Карцера, а наша с тобой задача — не дать ему пробудиться от многовекового сна.",
        MiniEventHunger_Loss_1 = "Тебя мама не учила доедать всё до конца? Это заметно — в твоих глазах голод! Или… что вообще с тобой такое?",
        MiniEventHunger_Win_1 = "Да, бьёшь ты знатно, Тень… Давай отпразднуем твою победу сытной едой! Я угощаю!",
        MiniEventStory_1 = "Я вижу, что ты, Тень, силён и непоколебим духом. Легенды о твоих подвигах разошлись повсюду. Хочешь стать частью ещё одной?",
        MiniEventStory_2 = "Духи подземного мира капризны. Мы проводим церемонию, чтобы усмирить их нрав, — ритуальные бои! Твоё участие было бы для нас большой честью.",
        MiniEventStory_EnterBattle = "А ты не слишком ли хлипок для столь тайного зрелища? И вы правда выбрали его? Это и есть человек-легенда? О, духи будут в ярости…",
        MiniEventStory_Loss_1 = "Да, ну что ж… Хочется верить, что у духов есть чувство юмора и они лишь посмеются над нашей неуклюжестью на арене, вместо того чтобы обрушить на нас свой гнев…",
        MiniEventStory_Win_1 = "Что ж… На эту арену никто не попадает случайно. Ты и правда человек из легенд, Тень.",
        MiniEventVulkanFight_Enter_1 = "Ведьма пугает тебя без причины. Всё гораздо проще: сталь закаляется в огне! Боги признают только силу и ничего больше. Лишь сила способна вернуть их в вечный сон! В атаку!",
        MiniEventVulkanStory_1 = "Очищающий огонь праведен — так говорили наши предки. Но они не знали, что Бессмертным нет дела до человеческой морали. Такова уж их природа.",
        MiniEventVulkanStory_2 = "Чувствуешь, как жар поднимается из-под земли? Ты должен знать одно: пламя не щадит никого, будь то друг или чужак. И мы стоим прямо на его пути.",
        MiniEventVulkan_Loss_1 = "Ты должен подняться на ноги, Тень! Разве ты не чувствуешь, как дрожит земля?! Бога утомляет наша возня в пыли…",
        MiniEventVulkan_Win_1 = "Здесь жарко, как в адском пламени… Дух огня довольно урчит в своём святилище! Славный бой, Тень! Мы отвоевали себе ещё один день!",
