        RANDOM_AREA_HEALTH_DEGENERATION = "Убывающее в указанной области здоровье.",
        TRANSIENT_BLEEDING = "Переходящий эффект горения.",
        Tenebris_greetings_1 = "Ты на границе реальности, путник. Это последний рубеж. Дальше лишь пустота, в которой рождаются миры. И я выковал для них свет и тьму!",
        Tenebris_greetings_2 = "Тень, портал за его спиной может быть нашим шансом на спасение. Бессмертные говорили, что разрушат наш мир — не с его ли помощью? ",
        Tenebris_greetings_3 = "Тебе не выжить в портале! Там неизвестность. Тьма, в которой можно творить миры. Но ты не умеешь творить — лишь разрушать. Портал поглотит тебя!",
        Tenebris_greetings_4 = "Мы рискуем, но есть ли другой выход? Войдем в портал и остановим Бессмертных. Или же станем причиной катастрофы?",
        Tenebris_loses = "Ты боишься неизвестности, скрытой во тьме? Теперь ты останешься с ней один на один! Мир рассыплется в прах и возродится вновь. По спирали.",
        Tenebris_wins = "Упертый глупец! Вы, люди, решаете свои проблемы лишь грубой силой. Но вселенная работает не так. За все эти годы ты так ничего и не понял...",
        Title_Sitaram = "СИТАРАМ",
        War_AfterLoss = "Вставай, марионетка! Дерись! Не важно, выиграешь ты или проиграешь. Сражаясь, ты уже служишь мне!",
        War_AfterWin = "Притворщик! Где твоя злость? Как ты можешь биться без нее?! Дерись со мной! Начнем еще один танец лезвий! Я знаю, что война живет в тебе!",
        War_Greetings1 = "Какой чудесный день! Я чую битву, она приближается, как буря. Гром — несметные яростные легионы, идущие в ногу. Все они — дары на моем алтаре!",
        War_Greetings2 = "Гнев и жажда крови клокочут в ней. Она упивается нескончаемым сражением, но ради чего? Что она найдет на вершине горы из черепов?",
        War_Greetings3 = "Разве тебе чужд азарт кровавой бойни? Огонь, страсть, бушующая мощь! Покажи на что ты способен, развлеки меня поединком или умри!",
        ZONE_RAID = "Подземелье: Уровень 1",
        ZONE_RAID1 = "Подземелье: Уровень 2",
        ZONE_RAID2 = "Подземелье: Уровень 3",
        ZONE_RAID3 = "Подземелье: Уровень 4",
        ZONE_RAID4 = "Подземелье: Уровень 5",
        ZONE_RAID5 = "Подземелье: Уровень 6",
        ZONE_RAID6 = "Подземелье: Уровень 7",
        ZONE_RAID7 = "Подземелье: Уровень 8",
        blackness_enter_blackness_1 = "Потомство. Великая жертва. Сфера. Разум. Бойня. Я чувствую. Ты прольёшь кровь. Я вижу боль. Я вижу будущее. Я покажу тебе.",
        blackness_greeting_blackness_1 = "Что случилось, Тень? Тебе нехорошо?",
        blackness_greeting_lazarus_2 = "Саймон? Ну ты и сволочь! Зачем ты привёл сюда людей? Оно учует шлейф твоих мыслей! Убирайтесь отсюда, пока Чернота не добралась до вашего разума!",
        blackness_greeting_may_1 = "Слышишь? Ничего! Тишина. Без птичьего пения это место словно застыло в янтаре. Правильно ли мы поступаем? У меня очень плохое предчувствие…",
        blackness_greeting_saimon_2 = "Эти достопочтенные господа — твой билет на свободу, дорогой мой. Тот, что покрупнее и в чёрном, как-то связан с Обелиском и Вратами. Он поможет тебе, а ты поможешь ему.",
        blackness_greetingn_saimon_1 = "Немудрено. С тех пор как обломок древних Врат рухнул сюда, жизнь в этом месте превратилась в статистическую аномалию. Смотрите в оба — нам нужно отыскать Лазаря.",
        blackness_lose_blackness_1 = "Ты останешься здесь. На веки вечные. Одна кровь. Навсегда. Я прочту тебя. Я буду насыщаться.",
        blackness_win_sensei = "Ты солгал нам, учёный муж! Кого мы освободили? На что мы обрекли этот мир? Ты хоть понимаешь, что натворил?!",
        characterMay = "МЭЙ",
        characterMiniEventPriestess = "Жрица",
        characterSensei = "СЭНСЕЙ",
        characterThief = "ПРОНЫРА",
        character_Blind = "ГОРНОСТАЙ",
        descAdanti = "Аданти принимает твой вызов.{br}(Ур. {0})",
