        RANDOM_AREA_HEALTH_DEGENERATION = "Pierdes vida en la zona indicada",
        TRANSIENT_BLEEDING = "Transmite efecto Quemadura",
        Tenebris_greetings_1 = "Estás al límite de la realidad, viajero. Esta es la frontera final. Más allá de esta línea hallarás el vacío del que nacen los mundos. ¡Y fui yo quien forjó su luz y su oscuridad!",
        Tenebris_greetings_2 = "Sombra, el portal detrás de él podría ser nuestra única oportunidad de salvación. Los inmortales dijeron que destruirían nuestro mundo. ¿Tal vez pretendan usar ese portal?",
        Tenebris_greetings_3 = "¡No sobrevivirás al portal! Es una terra incognita. La oscuridad en la que se crean los mundos; pero tú no eres capaz de crear, solo de destruir. ¡El portal te engullirá por completo!",
        Tenebris_greetings_4 = "Es arriesgado, pero ¿acaso tenemos elección? Tal vez logremos detener a los inmortales si entramos en el portal. Aunque también podríamos causar una gran catástrofe.",
        Tenebris_loses = "¿Tienes miedo de lo desconocido que acecha en la oscuridad? ¡Ahora tendrás que hacerle frente por tu cuenta! El mundo se convierte en polvo y renace de nuevo. La espiral continúa.",
        Tenebris_wins = "¡Necio testarudo! Los humanos solo sabéis resolver los problemas con la fuerza bruta, pero el universo no funciona así. Tantos años y no habéis aprendido nada...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "¡Levántate, fantoche, y lucha! No importa si ganas o pierdes. Siempre que luchas, me estás sirviendo.",
        War_AfterWin = "¡Farsante! ¿Y tu furia? ¿Cómo puedes luchar sin ella? ¡Enfréntate a mí; comencemos otra danza de espadas! ¡Sé que llevas la guerra en la sangre!",
        War_Greetings1 = "¡Es un día magnífico! Siento que la batalla se acerca, cual tormenta. Truenos. La furia inaudita de las legiones. ¡Todo ello es un regalo en mi altar!",
        War_Greetings2 = "La ira y la sed de sangre hierven en sus venas. Se deleita con batallas eternas, pero ¿con qué fin? ¿Qué encontrará bajo la montaña de calaveras?",
        War_Greetings3 = "¿Tan extraña te resulta la emoción de una sangrienta batalla? ¡El fuego, la pasión, el poder de la tempestad! ¡Demuestra lo que vales! ¡Lucha o muere!",
        ZONE_RAID = "Inframundo: Nivel 1",
        ZONE_RAID1 = "Inframundo: Nivel 2",
        ZONE_RAID2 = "Inframundo: Nivel 3",
        ZONE_RAID3 = "Inframundo: Nivel 4",
        ZONE_RAID4 = "Inframundo: Nivel 5",
        ZONE_RAID5 = "Inframundo: Nivel 6",
        ZONE_RAID6 = "Inframundo: Nivel 7",
        ZONE_RAID7 = "Inframundo: Nivel 8",
        blackness_enter_blackness_1 = "Descendencia. Un gran sacrificio. Una esfera. La mente. Carnicería. Siento. Derramarás sangre. Veo dolor. Veo el futuro. Te lo mostraré.",
        blackness_greeting_blackness_1 = "¿Qué te pasa, Shadow? ¿Te encuentras mal?",
        blackness_greeting_lazarus_2 = "¿Simon? ¡Qué desgraciado eres! ¿Por qué trajiste gente aquí? ¡Olerá el rastro de tus pensamientos! ¡Aléjate de aquí antes de que la Oscuridad pruebe tu mente!",
        blackness_greeting_may_1 = "¿Oyes eso? ¡Nada! Silencio. Sin el canto de los pájaros, es como si este lugar estuviera congelado en ámbar. ¿Estamos haciendo lo correcto? Tengo un muy mal presentimiento…",
        blackness_greeting_saimon_2 = "Estos distinguidos caballeros son tu boleto a la libertad, querido. El grandullón de negro está conectado de alguna manera con el Obelisco y las Puertas. Él te ayuda y tú lo ayudas a él.",
        blackness_greetingn_saimon_1 = "No me sorprende. Desde que un fragmento de las antiguas Puertas se estrelló aquí, la vida en este lugar ha sido una anomalía estadística. Mantén los ojos abiertos, tenemos que encontrar a Lázaro.",
        blackness_lose_blackness_1 = "Te quedas aquí. Eternamente. Una sola sangre. Para siempre. Te leeré. Me alimentaré.",
        blackness_win_sensei = "¡Nos mentiste, hombre de ciencia! ¿A quién hemos liberado? ¿A qué hemos condenado a este mundo? ¡¿Te das cuenta de lo que has hecho?!",
