        RAIDBOSS_Witch_young_Title = "Morgana",
        RANDOM_AREA_HEALTH_DEGENERATION = "Du förlorar hälsa i det visade området.",
        TRANSIENT_BLEEDING = "Överför brinnande effekt.",
        Tenebris_greetings_1 = "Du befinner dig på verklighetens rand, resenär. Detta är den sista utposten. Bortom denna linje finns tomheten i vilken världar föds. Och det var jag som smidde deras ljus och mörker!",
        Tenebris_greetings_2 = "Shadow, portalen bakom honom kan vara vår chans till räddning. De eviga sa am de skulle förgöra vår värld. Kanske med hans hjälp?",
        Tenebris_greetings_3 = "Du kommer inte att överleva portalen! Det är terra incognita. Mörkret i vilket världar kan skapas. Men du kan inte skapa, bara förgöra. Portalen kommer att sluka dig hel!",
        Tenebris_greetings_4 = "Det är en risk, maen har vi något annat val? Vi kanske kan stoppa de eviga genom att gå in i portalen. Men vi kan också orsaka en stor katastrof.",
        Tenebris_loses = "Är du rädd för det okända som lurar i mörkret? Nu lämnas du att möta det helt själv! Världen faller till damm och föds på nytt. Den följer spiralen.",
        Tenebris_wins = "Envise dåre! Ni människor kan bara lösa problem med råstyrka. Men universum fungerar inte så. Alla dessa år, och du har ingenting lärt dig...",
        Title_Sitaram = "SITARAM",
        War_AfterLoss = "Res dig, marionett! Och strid! Det spelar ingen roll om du vinner eller förlorar. När du strider tjänar du mig!",
        War_AfterWin = "Bedragare! Var är ditt raseri? Hur kan du strida utan det? Kämpa mot mig! Låt oss börja ännu en klingornas dans! Jag vet att kriget lever inom dig!",
        War_Greetings1 = "Vilken underbar dag! Jag kan känna en strid nalkas, likt en storm. Åska. Legionernas obeskrivliga raseri som håller jämna steg. De är alla gåvor på mitt altare!",
        War_Greetings2 = "Raseri och blodstörst sjuder inom henne. Hon njuter av ändlösa strider, men till vilken nytta? Vad kommer hon att finna på toppen av sitt berg av dödsskallar?",
        War_Greetings3 = "Är spänningen i en blodig strid så främmande för dig? Eld, passion, stormig kraft! Visa vad du går för! Underhåll mig i tvekamp eller dö!",
        ZONE_RAID = "Undervärlden: Nivå 1",
        ZONE_RAID1 = "Undervärlden: Nivå 2",
        ZONE_RAID2 = "Undervärlden: Nivå 3",
        ZONE_RAID3 = "Undervärlden: Nivå 4",
        ZONE_RAID4 = "Undervärlden: Nivå 5",
        ZONE_RAID5 = "Undervärlden: Nivå 6",
        ZONE_RAID6 = "Undervärlden: Nivå 7",
        ZONE_RAID7 = "Undervärlden: Nivå 8",
        blackness_enter_blackness_1 = "Avkomma. Ett stort offer. En sfär. Sinnet. Slakt. Jag känner. Du kommer att spilla blod. Jag ser smärta. Jag ser framtiden. Jag ska visa dig.",
        blackness_greeting_blackness_1 = "Vad är det, Shadow? Mår du inte bra?",
        blackness_greeting_lazarus_2 = "Simon? Vilken jävel du är! Varför tog du hit folk? Den kommer att fånga doften av era tankar! Försvinn härifrån innan Mörkret smakar på ert medvetande!",
        blackness_greeting_may_1 = "Hör du det? Ingenting! Tystnad. Utan fågelsång är det som om den här platsen är frusen i bärnsten. Gör vi rätt? Jag har en väldigt dålig magkänsla...",
        blackness_greeting_saimon_2 = "Dessa fina herrar är din biljett till frihet, min käre. Den stora i svart är på något sätt kopplad till Obelisken och Portarna. Han hjälper dig, och du hjälper honom.",
        blackness_greetingn_saimon_1 = "Inte konstigt. Ända sedan ett fragment av de uråldriga Portarna kraschade här, har livet på denna plats varit en statistisk anomali. Håll ögonen öppna – vi måste hitta Lazarus.",
        blackness_lose_blackness_1 = "Du stannar här. I evighet. Ett blod. För alltid. Jag ska läsa dig. Jag ska äta.",
        blackness_win_sensei = "Du ljög för oss, vetenskapsman! Vem har vi släppt fri? Vad har vi dömt den här världen till? Inser du vad du har gjort?!",
        characterMay = "MAY",
        characterMiniEventPriestess = "Prästinnan",
        characterSensei = "SENSEI",
        characterThief = "SLY",
        character_Blind = "HERMELIN",
        descAdanti = "Adanti accepterade din utmaning.{br}(Nivå {0})",
