        descGatekeeper = "Portvakten accepterade din utmaning.{br}(Nivå {0})",
        descHauntedPrince = "Hemsökt prins accepterade din utmaning.{br}(Nivå {0})",
        descHoaxen = "Hoaxen accepterade din utmaning.{br}(Nivå {0})",
        descInvisible = "Osynlig accepterade din utmaning.{br}(Nivå {0})",
        descKarcer = "Karcer accepterade din utmaning.{br}(Nivå {0})",
        descLamb = "Lammet accepterade din utmaning.{br}(Nivå {0})",
