        descMorgana = "Morgana accepterade din utmaning.{br}(Nivå {0})",
        descPowerMode = "<color=#CC0101>KRAFTLÄGE</color>{br}(Nivå {0})",
        descPuppeteer = "Dockmästaren accepterade din utmaning.{br}(Nivå {0})",
        descRakshasa = "Rakshasa accepterade din utmaning.{br}(Nivå {0})",
        descRavana = "Ravana accepterade din utmaning.{br}(Nivå {0})",
