        RANDOM_AREA_HEALTH_DEGENERATION = "Belirtilen bölgede canın zamanla azalır.",
        TRANSIENT_BLEEDING = "Geçen yanma etkisi",
        Tenebris_greetings_1 = "Gerçekliğin sınırındasın yolcu. Burası sınır. Bu hattın ötesinde dünyaların doğduğu boşluk var. Ve o dünyaların ışığını ve karanlığını ben işledim!",
        Tenebris_greetings_2 = "Gölge, onun arkasındaki geçit kurtuluşumuz için şans olabilir. Ölümsüzler dünyamıza kıyamet getireceğini söyledi. Belki onlar bu geçiti kullanmayı düşünüyordur?",
        Tenebris_greetings_3 = "Geçitte hayatta kalamazsın! Orası hiçlik. Dünyaların yaratıldığı karanlık. Ancak sen yaratamazsın, yalnızca yok edersin. Kapı seni tamamen yutar!",
        Tenebris_greetings_4 = "Bu bir risk ancak başka bir seçeneğimiz var mı? Belki ölümsüzlerin geçidi aşmasını durdurabiliriz. Aynı zamanda büyük bir felakete yol açabiliriz.",
        Tenebris_loses = "Karanlıkta gizlenen bilinmezden korkuyor musun? Şimdi tek başına yüzleşmek için kalacaksın! Dünya kül olmaya başlayacak ve küllerinden doğacak. Döngüyü devam ettirecek.",
        Tenebris_wins = "İnatçı ahmak! Siz insanlar problemleri yalnızca kaba kuvvetle çözersiniz. Ama evren böyle çalışmıyor. Sayısız yıl geçti ve siz hiçbir şey öğrenmediniz...",
        Title_Sitaram = "SİTARAM",
        War_AfterLoss = "Kukla, ayağa kalk! Ve dövüş! Kazanman ya da kaybetmen bir şey ifade etmez. Dövüştüğünde, bana hizmet edersin!",
        War_AfterWin = "Sahtekar! Nerede senin öfken? Onsuz nasıl dövüşebilirsin? Dövüş benimle! Hadi başka bir bıçak dansına başlayalım! İçinde savaş yaşıyor, biliyorum!",
        War_Greetings1 = "Ne mükemmel bir gün! Savaşın fırtına gibi yaklaştığını hissediyorum. Gök gürültüsü. Lejyonların muazzam öfkesi ayak uyduruyor. Hepsi sunağıma hediye!",
        War_Greetings2 = "Hiddet ve kana susamışlık onun içinde kaynıyor. O sonsuz savaştan zevk alır ama neden? Kafatası dağının tepesinde ne bulacak?",
        War_Greetings3 = "Kanlı savaşın heyecanı sana yabancı mı? Ateş, tutku, şiddetli güç! Ne yapabildiğini göster! Tekli dövüşte beni eğlendir ya da öl!",
        ZONE_RAID = "Yeraltı Dünyası: Aşama 1",
        ZONE_RAID1 = "Yeraltı Dünyası: Aşama 2",
        ZONE_RAID2 = "Yeraltı Dünyası: Aşama 3",
        ZONE_RAID3 = "Yeraltı Dünyası: Aşama 4",
        ZONE_RAID4 = "Yeraltı Dünyası: Aşama 5",
        ZONE_RAID5 = "Yeraltı Dünyası: Aşama 6",
        ZONE_RAID6 = "Yeraltı Dünyası: Aşama 7",
        ZONE_RAID7 = "Yeraltı Dünyası: Aşama 8",
        blackness_enter_blackness_1 = "Döl. Büyük bir kurban. Bir küre. Zihin. Kasaplık. Hissediyorum. Kan dökeceksin. Acı görüyorum. Geleceği görüyorum. Sana göstereceğim.",
        blackness_greeting_blackness_1 = "Sorun ne Shadow? İyi değil misin?",
        blackness_greeting_lazarus_2 = "Simon? Ne pislik birisin! Neden insanları buraya getirdin? Düşüncelerinin kokusunu alacak! Karanlık zihnini tatmadan buradan uzaklaş!",
        blackness_greeting_may_1 = "Bunu duyuyor musun? Hiçbir şey! Sessizlik. Kuş cıvıltısı olmayınca, burası sanki kehribar içinde donmuş gibi. Doğru olanı mı yapıyoruz? Çok kötü bir hissim var...",
        blackness_greeting_saimon_2 = "Bu beyefendiler özgürlüğe biletin azizim. Siyahlı olan büyük olan, Dikilitaş ve Kapılarla bir şekilde bağlantılı. O sana yardım ediyor, sen de ona.",
        blackness_greetingn_saimon_1 = "Şaşmamalı. Kadim Kapılar'ın bir parçası buraya çarptığından beri, bu yerdeki yaşam istatistiksel bir anomali haline geldi. Gözlerini dört aç—Lazarus'u bulmamız gerek.",
        blackness_lose_blackness_1 = "Burada kalıyorsun. Sonsuza dek. Bir kan. Ebediyen. Seni okuyacağım. Besleneceğim.",
        blackness_win_sensei = "Bize yalan söyledin bilim adamı! Kimi özgür bıraktık? Bu dünyayı neye mahkum ettik? Ne yaptığının farkında mısın?!",
        characterMay = "MAY",
        characterMiniEventPriestess = "Rahibe",
        characterSensei = "SENSEY",
        characterThief = "SİNSİ",
        character_Blind = "ERMİN",
